const a={1:[["1","Ne mutlu kötülerin öğüdüyle yürümeyen, günahkârların yolunda durmayan, alaycıların sandalyesinde oturmayan insana."],["2","Ancak onun zevki Yahve’nin Yasası'dır. gece gündüz onun üzerinde derin derin düşünür."],["3","O kişi akarsu kıyısına dikilmiş ağaca benzer, meyvesini mevsiminde verir, yaprağı da solmaz. Ne yaparsa başarır."],["4","Kötüler böyle değildir, ancak rüzgârın savurduğu saman çöpü gibidirler."],["5","Bu nedenle kötüler yargılanınca ayakta kalamaz, günahkârlar doğrular topluluğunda duramaz."],["6","Çünkü Yahve doğruların yolunu bilir, ancak kötülerin yolu yok olur."]],2:[["1","Uluslar neden öfkeleniyor, halklar neden boş düzen kuruyor?"],["2","Dünyanın kralları ayağa kalkıyor, hükümdarlar birbiriyle öğütleşiyor, Yahve’ye ve Mesihi’ne karşı."],["3","“Koparalım onların bağlarını” diyorlar, “İplerini üzerimizden atalım.”"],["4","Göklerde oturan gülecek. Efendi onlarla alay edecek."],["5","O zaman hiddetle konuşacak onlara, gazabıyla onları dehşete düşürecek:"],["6","“Ben Kralımı kutsal dağım Siyon'a oturttum.”"],["7","Kararı bildireceğim: Yahve bana, “Sen benim oğlumsun” dedi. “Bugün ben senin baban oldum."],["8","Dile benden, mirasın olarak sana ulusları, mülk olarak yeryüzünün en uzak köşelerini vereyim."],["9","Onları demir sopayla kıracaksın, çömlekçi kabı gibi parçalayacaksın.”"],["10","Ey krallar, şimdi akıllı olun. Ey dünya hâkimleri, ders alın."],["11","Yahve’ye korkuyla hizmet edin, titreyerek sevinin."],["12","Oğul'a içtenlikle saygı gösterin ki öfkelenmesin, yoksa yolunuzda mahvolursunuz. Çünkü hiddeti yakında alevlenecek. Ne mutlu O'na sığınanlara."]],3:[["1","David’in oğlu Avşalom'dan kaçtığı zaman yazdığı mezmur Ey Yahve, düşmanlarım nasıl da çoğaldı! Bana karşı ayaklananlar çoktur."],["2","Canım için birçoğu, “Tanrı katında ona yardım yoktur” diyor. Selah."],["3","Ama sen, ey Yahve, çevremde kalkansın, yüceliğim ve başımı yükselten sensin."],["4","Yahve’ye seslenirim, kutsal dağından bana yanıt verir. Selah."],["5","Yattım ve uyudum. Uyandım, çünkü Yahve bana destek oldu."],["6","Her yönden bana karşı koyan on binlerden korkmam."],["7","Kalk, ey Yahve! Tanrım, kurtar beni! Çünkü sen tüm düşmanlarımın çene kemiğine vurdun. Kötülerin dişlerini kırdın."],["8","Kurtuluş Yahve’nindir. Kutsaman halkının üzerinde olsun! Selah."]],4:[["1","Seslenince yanıtla beni, doğruluğumun Tanrısı! Beni sıkıntımdan kurtar. Bana merhamet et ve duamı duy."],["2","Ey insanoğulları, ne zamana dek yüceliğim utanca çevrilecek? Boş şeyleri sevip yalanın peşinden mi gideceksiniz? Selah."],["3","Ama Yahve’nin tanrısal olanı kendine ayırdığını bilin. Kendisine seslenince Yahve beni duyar."],["4","Titreyin ve günah işlemeyin. Yatağınızda yüreğinizi yoklayın ve sakin olun. Selah."],["5","Doğruluk kurbanları sunun. Yahve’ye güvenin."],["6","“Bize kim iyilik gösterecek?” diyenler çoktur. Yüzünün ışığı üzerimizde parlasın, ey Yahve."],["7","Yüreğime verdiğin sevinç, onların tahıllarının ve yeni şaraplarının çoğaldığı zamankinden fazladır."],["8","Esenlik içinde hem yatar, hem uyurum. Çünkü yalnız sen, ey Yahve, güvenlik içinde yaşatırsın beni."]],5:[["1","Müzik şefi için - Telli sazlarla - David'in mezmuru Sözlerime kulak ver, ey Yahve. İçine daldığım düşünceleri gör."],["2","Feryadıma kulak ver, ey Kralım ve Tanrım; çünkü sana dua ediyorum."],["3","Sabahları sesimi işiteceksin, ey Yahve, sabahları dileklerimi önüne serip umutla bekleyeceğim."],["4","Çünkü sen kötülükten hoşlanan bir Tanrı değilsin. Kötülük seninle yaşayamaz."],["5","Kibirliler önünde duramaz. Kötülüğün tüm işçilerinden nefret edersin."],["6","Yalan söyleyenleri yok edersin. Yahve kana susamış ve düzenbaz adamdan nefret eder."],["7","Bense senin sevgi dolu iyiliğinin bolluğuyla evine gireceğim. Sana saygıyla kutsal tapınağına doğru eğileceğim."],["8","Ey Yahve, düşmanlarıma karşı doğruluğunla bana yol göster. Yolunu önümde düzle."],["9","Çünkü ağızlarında sadakat yoktur. Yürekleri yıkımdır. Boğazları açık bir mezar. Dilleriyle yaltaklanırlar."],["10","Onları suçlu çıkar, ey Tanrım! Kendi öğütleriyle düşsünler. İsyanlarının çokluğunda onları kov, çünkü sana karşı isyan ettiler."],["11","Ama sana sığınanların hepsi sevinsinler. Her zaman sevinç çığlıkları atsınlar, çünkü onları savunan sensin. Adını sevenler de sende sevinçle coşsunlar."],["12","Çünkü sen doğru kişiyi kutsayacaksın, ey Yahve çevresini kalkan gibi lütfunla saracaksın."]],6:[["1","Müzik şefi için - Sekiz telli sazlarla - David'in mezmuru Ey Yahve, öfkenle beni azarlama, beni gazabınla terbiye etme."],["2","Acı bana, ey Yahve, çünkü bitkinim. Ey Yahve, iyileştir beni, çünkü kemiklerim sızlıyor."],["3","Canım da büyük bir ıstırap içinde. Ama sen, ey Yahve, ne zamana dek?"],["4","Ey Yahve, dön. Canımı özgür kıl, sevgi dolu iyiliğin uğruna beni kurtar."],["5","Çünkü senin anılman ölümün içinde yoktur. Şeol'de sana kim şükredecek?"],["6","İnlemekten yoruldum. Her gece yatağım su içinde. Gözyaşlarımla döşeğimi ıslatıyorum."],["7","Gözüm kederden sönüyor, bütün düşmanlarımdan ötürü yaşlanıyor."],["8","Ey kötülük yapanların hepsi benden uzak durun, çünkü Yahve ağlayışımı duydu."],["9","Yahve yalvarışımı işitti. Yahve duamı kabul edecektir."],["10","Bütün düşmanlarım utanıp dehşet içinde kalacak. Dönecekler, ansızın rezil olacaklar."]],7:[["1","Benyaminli Kûş'un sözlerine ilişkin David’in Yahve’ye okuduğu şigayon Ey Yahve, Tanrım, sana sığınıyorum. Peşime düşenlerin hepsinden kurtar beni, özgür kıl."],["2","Kurtaracak kimse yok diye, aslan gibi canımı parçalamasınlar, paramparça etmesinler onu."],["3","Ey Yahve, Tanrım, eğer şunu yaptıysam, eğer elimde kötülük varsa,"],["4","benimle barış içinde olan birine kötülükle karşılık verdiysem (evet, sebepsiz yere düşmanımı soyduysam),"],["5","düşman canımın peşine düşsün ve ele geçirsin beni, hayatımı yere çalsın, yüceliğimi toza katsın. Selah."],["6","Öfkeyle kalk, ey Yahve. Düşmanlarımın öfkesine karşı yüksel. Benim için uyan. Hükmü sen buyurdun."],["7","Uluslar topluluğu çevreni sarsın. Yücelerden onları yönet."],["8","Yahve halkları yargılar, beni doğruluğuma göre yargıla, ey Yahve, dürüstlüğüme göre."],["9","Kötülerin kötülüğü son bulsun, ama doğru olanı pekiştir, onların akıllarını ve yüreklerini araştıran adil Tanrı’dır."],["10","Benim kalkanım Tanrı’yla olmaktır, yüreği doğru olanı O kurtarır."],["11","Tanrı adil bir yargıçtır, evet, her gün öfkelenen bir Tanrı’dır."],["12","Biri tövbe etmezse kılıcını biler, eğip yayını gerer."],["13","Ona karşı ölüm silahlarını hazırlamıştır. Alevli okları hazırdır."],["14","İşte o kişi, kötülük sancısı çekiyor. Kötülüğe gebe kalıp, yalan doğurdu."],["15","Bir çukur kazdı, kazdığı çukura kendisi düştü."],["16","Neden olduğu bela kendisine dönecek. Zorbalığı kendi başına inecek."],["17","Doğruluğundan ötürü Yahve’ye şükredeceğim, yüce Yahve'nin adını ilahilerle öveceğim."]],8:[["1","Müzik şefi için - Gittit üzerine - David’in mezmuru Ey Efendimiz Yahve, ne yüce adın var bütün yeryüzünde! Görkemini göklerin üstüne yükselttin!"],["2","Sana düşman olanlardan ötürü, düşmanı ve öç alanı susturmak için çocukların ve bebeklerin dudaklarından gücü kurdun."],["3","Senin göklerini, ellerinin eserini, koyduğun ay ve yıldızları düşününce dedim:"],["4","“İnsan ne ki, onu düşünesin? İnsanoğlu nedir ki, ona değer veresin?”"],["5","Onu meleklerden biraz aşağı kıldın, ve onu yücelik ve saygınlıkla taçlandırdın."],["6","Ellerinin işleri üzerinde onu hâkim kıldın. Her şeyi ayaklarının altına serdin."],["7","Tüm koyunları ve sığırları, kır hayvanlarını,"],["8","Gökteki kuşları, denizdeki balıkları, denizlerin yollarından geçen her şeyi."],["9","Ey Efendimiz Yahve, ne yüce adın var bütün yeryüzünde!"]],9:[["1","Müzik şefi için - “Oğulun Ölümü” makamında - David’in mezmuru Bütün yüreğimle Yahve’ye şükredeceğim. Şaşkınlık verici işlerinin hepsini anlatacağım."],["2","Sende sevinip coşacağım. Adına ilahiler söyleyeceğim, ey Yüceler Yücesi."],["3","Düşmanlarım geri çekilirken, senin önünde tökezleyip yok oluyorlar."],["4","Çünkü haklı davamı sen gördün. Tahtında oturur adil şekilde yargılarsın."],["5","Ulusları azarladın. Kötüleri yok ettin. Adlarını sonsuza dek sildin."],["6","Düşman sonsuz yıkıma uğradı. Yerinden söküp attığın kentlerin anıları bile yok oldu."],["7","Ama Yahve sonsuza dek hüküm sürer. Tahtını yargı için hazırlamıştır."],["8","Dünyayı doğrulukla yargılayacak. O, halkları doğrulukla yargılayacaktır."],["9","Yahve ezilenler için bir sığınak, sıkıntılı zamanlarda yüksek bir kuledir."],["10","Adını bilenler sana güvenecekler, çünkü sen, ey Yahve, seni arayanları terk etmezsin."],["11","Siyon'da oturan Yahve’yi ilahilerle övün, yaptıklarını halklar arasında ilan edin."],["12","Çünkü kanın öcünü alan onları hatırlar. Mazlumların feryadını unutmaz."],["13","Bana merhamet et, ey Yahve. Benden nefret edenler yüzünden çektiğim acıyı gör, beni ölümün kapılarından kaldır da,"],["14","övgülerinin tümünü gösterebileyim. Siyon kızının kapılarında kurtarışınla sevineceğim."],["15","Uluslar kazdıkları çukura düştüler. Gizledikleri ağ kendi ayaklarına takıldı."],["16","Yahve kendisini tanıttı. Yargısını gerçekleştirdi. Kötü kişi kendi ellerinin işiyle tuzağa düştü. Higayon - Selah."],["17","Kötüler Şeol'e döndürüleceklerdir. Tanrı’yı unutan tüm uluslar da."],["18","Çünkü yoksullar hep unutulmayacak, mazlumun umudu sonsuza dek yok olmayacak."],["19","Kalk, ey Yahve! İnsan galip çıkmasın. Uluslar senin önünde yargılansın."],["20","Onları korkut, ey Yahve. Uluslar, yalnızca insan olduklarını bilsinler. Selah."]],10:[["1","Neden uzakta duruyorsun, ey Yahve? Sıkıntı zamanlarında neden kendini saklıyorsun?"],["2","Kötüler kibirle mazlumları avlıyor. Mazlumlar kötülerin kurduğu tuzağa düşüyor."],["3","Çünkü kötü kişi yüreğindeki arzularla övünür. Açgözlüleri yüceltir ve Yahve’yi yerer."],["4","Kötü kişi gururlu yüzüyle, düşüncelerinde Tanrı'ya yer vermez."],["5","Kötünün yolları hep bolluk içindedir. Kibirlidir ve senin yasaların onun gözlerinden uzaktır. Düşmanlarının hepsini küçümser."],["6","Yüreğinden, “Ben sarsılmam. Hiçbir devirde sıkıntıya düşmem.” der."],["7","Ağzı lanet, hile ve zulümle dolu. Dilinin altında kötülük ve fesat vardır."],["8","Köylerin yakınında pusuda bekler. Pusuda masumu öldürür. Gözlerini gizlice çaresize dikmiştir."],["9","Pusuya yatmış aslan gibi, gizlice pusudadır. Çaresizi yakalamak için yatıp bekler. Çaresizi ağına çekip yakalar."],["10","Çaresiz onun gücünün altında Çöküp ezilir."],["11","Yüreğinden, “Tanrı unuttu” der. “Yüzünü gizledi, hiçbir zaman görmeyecek.”"],["12","Kalk, ey Yahve! Tanrım, elini kaldır! Çaresizi unutma."],["13","Kötü kişi neden Tanrı'yı suçlasın? Yüreğinden “Tanrı hesap sormaz” desin."],["14","Ama sen sıkıntı ve kederi görürsün. Onu eline almayı düşünürsün. Mağdura ve babasızlara yardım edersin."],["15","Kötünün kolunu kır. Kötüye gelince, kötülüğü kalmayıncaya kadar ondan hesabını sor."],["16","Yahve sonsuza dek Kraldır! Uluslar O'nun diyarından yok olacak."],["17","Yahve, alçakgönüllülerin dileğini duydun. Onların yüreğini hazırlayacaksın. Kulağını onlara açacaksın,"],["18","Yetimlerin ve ezilenlerin yargısını vermek için, öyle ki toprak olan insan artık bir daha dehşet saçmasın."]],11:[["1","Müzik şefi için - David’in mezmuru Ben Yahve’ye sığınırım. Nasıl olur da canıma, “Kuş gibi dağa kaç” dersiniz?"],["2","Çünkü işte, kötüler yaylarını geriyor. Karanlıkta dürüst yüreklileri vurmak için, Oklarını kiriş üzerine yerleştirdiler."],["3","Temeller yıkılırsa, doğru kişi ne yapabilir?"],["4","Yahve kutsal tapınağındadır. Yahve gökte tahtındadır. O’nun gözleri bakar. Gözleri insanoğullarını sınar."],["5","Yahve doğru kişiyi sınar, ama O'nun canı kötüden ve zorbalığı sevenden nefret eder."],["6","Kötülerin üzerine kızgın korlar yağdıracak; ateş, kükürt ve kavurucu rüzgâr onların kâsesine düşen pay olacak."],["7","Çünkü Yahve doğrudur. Doğruluğu sever. Doğru kişi O’nun yüzünü görecek."]],12:[["1","Müzik şefi için - Sekiz telli sazlarla Yardım et, ey Yahve, çünkü tanrısal kişi kalmadı. İnsanoğulları arasında sadık olanlar tükeniyor."],["2","Herkes komşusuna yalan söylüyor. Yaltaklanan dudaklarla, çift yürekle konuşuyorlar."],["3","Yahve tüm yaltaklanan dudakları, ve övünen dilleri kessin."],["4","Onlar, “Dilimizle galip geleceğiz. Dudaklarımız bizimdir. Kim bizim üzerimizde efendidir?” derler."],["5","“Mazlumların ezilmesinden ve yoksulların iniltilerinden ötürü, şimdi kalkacağım” diyor Yahve, “Ona kötülük edenlerden kurtarıp güvenli bir yere koyacağım.”"],["6","Yahve’nin sözleri kusursuzdur, toprak ocakta eritilmiş, yedi kez arıtılmış gümüşe benzer."],["7","Sen onları koruyacaksın, ey Yahve. Onları bu kuşaktan daima koruyacaksın."],["8","Alçaklık insanoğulları arasında yüceltildiğinde, kötüler her yanda dolaşır."]],13:[["1","Müzik şefi için - David’in mezmuru Ne zamana dek, ey Yahve? Beni sonsuza dek mi unutacaksın? Yüzünü benden daha ne kadar gizleyeceksin?"],["2","Her gün yüreğimde keder var, ne zamana dek canımı teselli edeceğim? Ne zamana dek düşmanım bana karşı zafer kazanacak?"],["3","Bak ve yanıt ver bana, ey Tanrım Yahve. Gözlerime ışık ver ki, ölüm uykusuna yatmayayım,"],["4","öyle ki, düşmanım, “Onu yendim” demesin, Düştüğümde düşmanlarım sevinmesin."],["5","Ama ben senin sevgi dolu iyiliğine güveniyorum. Yüreğim senin kurtuluşunla seviniyor."],["6","Yahve’ye ezgiler söyleyeceğim, çünkü bana iyilik etti."]],14:[["1","Müzik Şefi için David’in mezmuru Akılsız yüreğinde, “Tanrı yoktur” dedi. Yozlaştılar, iğrenç işler yaptılar. İyilik eden kimse yok."],["2","Anlayan, Tanrı’yı arayan birisi var mı diye, Yahve gökten insanoğullarına baktı,"],["3","hepsi saptı. Hepsi birlikte yozlaştılar. İyilik eden kimse yok, bir kişi bile yok."],["4","Kötülük edenlerin hiçbirinin bilgisi yok mu? Halkımı ekmek yer gibi yiyorlar. Yahve’yi çağırmıyorlar."],["5","Orada dehşet içinde kaldılar. Çünkü Tanrı doğruların kuşağının yanındadır."],["6","Yoksulların tasarısını engellersiniz, ama onun sığınağı Yahve’dir."],["7","Ah, keşke İsrael'in kurtuluşu Siyon'dan gelseydi! Yahve halkının servetini geri döndürdüğünde, o zaman Yakov sevinecek ve İsrael coşacak."]],15:[["1","David’in mezmuru Ey Yahve, tapınağında kim oturabilir? Kutsal dağında kim yaşayabilir?"],["2","Kusursuzca yürüyen, doğru olanı yapan, yüreğinde gerçeği söyleyen,"],["3","Böylesi iftira etmez, dostuna kötülük etmez, komşusuna kara çalmaz."],["4","Aşağılık insanı hor görür, ama Yahve'den korkanlara saygı duyar. Kendi zararına ant içse bile, andını bozmaz."],["5","Parasını tefeciye vermez, suçsuza karşı rüşvet almaz. Bunları yapan asla sarsılmaz."]],16:[["1","David'in şiiri Koru beni, ey Tanrı, çünkü sana sığınıyorum."],["2","Canım, Yahve’ye şöyle dedi: “Efendim sensin. Senden ayrı bana iyilik yoktur.”"],["3","Yeryüzündeki kutsallara gelince, harikadır onlar, bütün zevkim onlardadır."],["4","Başka ilâha armağan sunanların kederi çoğalacak. Onların kan sunularını ben sunmayacağım, ne de adlarını ağzıma alacağım."],["5","Yahve payımı, kâsemi belirledi. Benim hissemi güvende tutan sensin."],["6","Sınırlar hoş yerlerde düştü bana. Evet, iyi bir mirasım var."],["7","Bana öğüt veren Yahve’yi yücelteceğim. Evet, geceleyin yüreğim beni uyarır."],["8","Yahve’yi hep önüme koydum. O benim sağımda olduğu için sarsılmam."],["9","Bu nedenle yüreğim coşku dolu, dilim sevinir. Bedenim de güvenlik içinde yaşar."],["10","Çünkü sen canımı Şeol'e terk etmeyeceksin, kutsalının çürümesine izin vermeyeceksin."],["11","Bana hayat yolunu göstereceksin. Bol sevinç senin huzurundadır. Sağ elinde sonsuz zevkler vardır."]],17:[["1","David’in bir duasıdır. Ey Yahve, haklı yakarışımı işit. Hileli dudaklardan çıkmayan duama kulak ver."],["2","Hükmüm senin huzurundan çıksın. Senin gözlerin adalete baksın."],["3","Yüreğimi denedin. Geceleyin beni ziyaret ettin. Beni yokladın ama hiçbir şey bulmadın. Ağzımdan itaatsiz söz çıkarmamaya kararlıyım."],["4","İnsanların yaptıklarına gelince, senin dudaklarının sözüyle, şiddet yollarından kendimi uzak tuttum."],["5","Adımlarım senin yollarını sımsıkı tuttu. Ayaklarım kaymadı."],["6","Sana seslendim, çünkü bana yanıt verirsin, Tanrım. Kulak ver bana. Sözümü duy."],["7","Sevgiyle dolu muhteşem iyiliğini göster, sana sığınanları sağ elinle düşmanlarından kurtaran sensin."],["8","Gözbebeğin gibi koru beni. Beni kanatlarının gölgesinde sakla,"],["9","bana baskı yapan kötülerden, Etrafımı saran ölümcül düşmanlarımdan."],["10","Duygusuz yüreklerini kapatırlar. Ağızlarıyla gururla konuşurlar."],["11","Artık adımlarımızın çevresini sardılar. Bizi yere çalmak için gözlerini diktiler."],["12","Avına karşı doyumsuz bir aslan, pusuya yatmış genç bir aslan gibi."],["13","Kalk, ey Yahve, onunla uğraş. Yere çal onu. Kılıcınla kurtar canımı kötülerden,"],["14","elinle insanlardan, ey Yahve, payı bu hayatta olan dünya insanlarından. Değer verdiklerinin karnını doyurursun. Oğulların bolluk içindedir, onlar da çocukları için servet biriktirirler."],["15","Bana gelince, yüzünü doğrulukla göreceğim. Uyandığımda senin suretini görmeye doyacağım."]],18:[["1","Müzik şefi için - Yahve’nin hizmetkârı David'in mezmuru - Yahve kendisini bütün düşmanlarının pençesinden ve Saul'un elinden kurtardığı gün David Yahve’ye şu ezgiyi okudu: Seni seviyorum, ey Yahve, gücüm sensin."],["2","Yahve benim kayam, kalem ve kurtarıcımdır, Tanrım, kayam, sığındığımdır, kalkanım ve kurtuluşumun boynuzu, yüksek kulem."],["3","Övülmeye layık olan Yahve’yi çağırırım, ve kurtulurum düşmanlarımdan."],["4","Ölüm ipleri sarmıştı beni. Tanrısızlık selleri beni ürküttü."],["5","Şeol'ün ipleri çevremdeydi. Ölüm tuzakları üzerime indi."],["6","Sıkıntı içinde Yahve’yi çağırdım, Tanrım’a haykırdım. Duydu sesimi tapınağından. Önündeki feryadım kulaklarına erişti."],["7","O zaman yeryüzü sarsılıp titredi. Dağların temelleri de yerinden oynadı, çünkü Yahve öfkelenmişti."],["8","Burnundan duman yükseldi. Ağzından yakıp tüketen bir ateş çıktı. Ondan korlar tutuştu."],["9","Gökleri yarıp indi. Ayakları altında koyu bir karanlık vardı."],["10","Bir keruva binip uçtu. Ve rüzgârın kanatları üzerinde süzüldü."],["11","Karanlığı kendisine saklanacak yer, karanlık suları, gökyüzünün koyu bulutlarını, çevresine çardak yaptı."],["12","Önündeki parıltıdan dolu ve alevli korlarla, O’nun koyu bulutları geçti."],["13","Yahve gökte gürledi. Yüceler Yücesi ses verdi, dolu ve alevli korlarla."],["14","Oklarını gönderip onları dağıttı. Onları büyük yıldırımlarla bozguna uğrattı."],["15","Ey Yahve senin azarlamandan, burnundan çıkan güçlü soluktan, suların yatakları göründü, dünyanın temelleri belirdi."],["16","Yukarıdan gönderdi. Beni tuttu. Beni çok sulardan çıkardı."],["17","Beni güçlü düşmanımdan, benden nefret edenlerden kurtardı. Çünkü onlar benden çok güçlüydüler."],["18","Felaket günümde üzerime geldiler, ama Yahve bana destek çıktı."],["19","Beni geniş bir yere çıkardı. Kurtardı beni çünkü benden hoşlandı."],["20","Yahve doğruluğuma göre ödüllendirdi beni. Ellerimin temizliğine göre bana karşılık verdi."],["21","Çünkü Yahve'nin yollarını tuttum, ve kötülükle Tanrım’dan uzaklaşmadım."],["22","Çünkü O'nun bütün ilkeleri önümdedir. Kurallarını kendimden uzaklaştırmadım."],["23","O’nunla suçsuzum. Günahımdan kendimi uzak tuttum."],["24","Bu nedenle Yahve beni doğruluğuma göre, ellerimin O’nun gözündeki temizliğine göre ödüllendirdi."],["25","Merhametli olana merhametini, kusursuz olana kusursuzluğunu gösterirsin."],["26","Pak olana paklığını, çarpık olana sertliğini gösterirsin."],["27","Çünkü mazlum insanları kurtarırsın, ama kibirli gözleri alaşağı edersin."],["28","Işığımı sen yakacaksın ey Yahve. Tanrım karanlığımı aydınlatacaksın."],["29","Çünkü senin sayende akıncıların üstüne çıkarım, Tanrım’la surları aşarım."],["30","Tanrı'ya gelince, O’nun yolu kusursuzdur. Yahve’nin sözü sınandı. O, kendisine sığınan herkese kalkandır."],["31","Çünkü Yahve'den başka Tanrı kimdir? Tanrımız’dan başka kaya kimdir?"],["32","O Tanrı ki, beni güçle donatır ve yolumu kusursuz kılar."],["33","Ayaklarımı geyik ayakları gibi eder, beni yüksek yerlerime diker."],["34","Ellerime savaşmayı öğretir, kollarımla tunç bir yayı gereyim diye."],["35","Bana kurtuluşunun kalkanını da verdin. Sağ elin destekler beni. Senin sevecenliğin beni büyük etti."],["36","Adımlarımın yerini genişlettin, ayaklarım kaymadı."],["37","Düşmanlarımı kovalayıp onlara yetişirim, onlar yok olana dek geri dönmem."],["38","Onları ezerim, kalkamazlar, ayaklarımın altına serilirler."],["39","Çünkü savaş için bana güç verdin. Bana karşı çıkanları bana boyun eğdirdin."],["40","Benden nefret edenleri yok edeyim diye, düşmanlarımın sırtını bana çevirttin."],["41","Feryat ettiler ama kurtaracak kimse yoktu, Yahve’yi bile çağırdılar ama O yanıt vermedi."],["42","O zaman onları yelin önündeki toz gibi ezdim. Onları sokak çamuru gibi dışarı fırlattım."],["43","Halkın çekişmelerinden beni kurtardın. Beni ulusların başı yaptın. Tanımadığım bir halk bana hizmet edecek."],["44","Duyar duymaz benim sözümü dinleyecekler. Yabancılar bana boyun eğecekler."],["45","Yabancılar yok olup gidecek, kalelerinden titreyerek çıkacaklar."],["46","Yahve yaşıyor! Kayam’a övgüler olsun! Kurtuluşumun Tanrısı yücelsin!"],["47","Benim için öç alan, halkları bana boyun eğdiren Tanrı O’dur."],["48","Düşmanlarımdan kurtarır. Bana karşı çıkanların üstüne çıkarırsın beni. Beni zorbadan kurtarırsın."],["49","Bunun için uluslar arasında sana şükredeceğim, ey Yahve, adını ilahilerle öveceğim."],["50","O, kralına büyük bir kurtuluş verir, meshedilmiş olanına, David ve soyuna, sonsuza dek sevgi dolu iyiliğini gösterir."]],19:[["1","Müzik şefi için - David’in mezmuru Gökler Tanrı'nın görkemini bildirir. Gök boşluğu ellerinin eserini sergiler."],["2","Gün güne söz söyler, gece geceye bilgi gösterir."],["3","Ne konuşma ne de dil vardır, sesleri duyulmaz."],["4","Sesleri tüm yeryüzüne, sözleri dünyanın sonuna dek ulaşır. Göklerde güneş için çadır kurdu Tanrı."],["5","Gerdekten çıkan güveye benzer güneş, yarışını koşan güçlü bir adam gibi sevinir."],["6","Göklerin bir ucundan çıkar, öbür ucuna dek döner. Sıcaklığından hiçbir şey saklanmaz."],["7","Yahve'nin yasası kusursuzdur, canı tazeler. Yahve’nin antlaşması emindir, saf kişiyi bilge kılar."],["8","Yahve’nin kuralları doğrudur, yüreği sevindirir. Yahve’nin buyruğu paktır, gözleri aydınlatır."],["9","Yahve korkusu temizdir, sonsuza dek kalıcıdır. Yahve’nin ilkeleri gerçektir ve tamamıyla doğrudur."],["10","Altından, bol miktarda saf altından daha çok arzu edilir, baldan, süzme petek balından daha tatlıdır."],["11","Üstelik hizmetkârını uyaran onlardır. Onlara uyanların ödülü büyüktür."],["12","Kusurlarını kim fark edebilir? Gizli kusurlarımdan dolayı beni bağışla."],["13","Hizmetkârını bilerek işlenen günahlardan uzak tut. Üzerimde hakimiyet kurmasınlar. O zaman doğru olurum. Büyük isyandan suçsuz ve masum çıkarım."],["14","Ağzımdan çıkan sözler ve yüreğimin düşüncesi senin önünde kabul görsün, ey Yahve, kayam ve kurtarıcım."]],20:[["1","Müzik şefi için- David’in mezmuru Yahve sıkıntılı gününde sana yanıt versin. Yakov'un Tanrısı'nın adı seni yükseltsin,"],["2","kutsal yerden sana yardım göndersin, Siyon’dan destek versin."],["3","Bütün sunularını hatırlasın, yakmalık sunularını kabul etsin. Selah."],["4","Sana yüreğine göre versin, ve bütün öğütlerini yerine getirsin."],["5","Senin kurtarışında zafer kazanacağız. Tanrı’nın adıyla sancaklarımızı dikeceğiz. Yahve bütün dileklerini yerine getirsin."],["6","Şimdi biliyorum ki, Yahve meshettiğini kurtarıyor. Sağ elinin kurtarıcı gücüyle, kutsal cennetten ona yanıt veriyor."],["7","Bazıları savaş arabalarına, bazıları atlara güvenir, ama biz Tanrımız Yahve’nin adına güveniriz."],["8","Onlar eğildiler ve düştüler, ama biz kalktık ve dik durduk."],["9","Kurtar, ey Yahve! Seslendiğimizde Kral bize yanıt versin!"]],21:[["1","Müzik şefi için David’in mezmuru Kral senin gücüne sevinir, ey Yahve! Kurtarışınla ne büyük sevinç duyar!"],["2","Yüreğinin isteğini ona verdin, dudaklarının dileğini geri çevirmedin. Selah."],["3","Çünkü iyilik bereketleriyle onu karşıladın. Başına saf altından taç koydun."],["4","Senden hayat istedi, sonsuza dek sürecek uzun günler verdin ona."],["5","Senin kurtarışınla yüceliği büyüktür. Ona saygınlık ve yücelik giydirdin."],["6","Çünkü sen onu daima en kutsanmış kıldın. Huzurunda onu sevinçle coşturdun."],["7","Çünkü kral Yahve’ye güvenir, Yüceler Yücesi'nin sevgi dolu iyiliği sayesinde sarsılmaz."],["8","Elin bütün düşmanlarını bulacak. Sağ elin senden nefret edenleri bulacaktır."],["9","Öfkelendiğin zaman onları kızgın fırına çevireceksin. Yahve gazabıyla onları yutacak. Ateş onları yiyip bitirecektir."],["10","Onların soyunu yeryüzünden, gelecek kuşaklarını insanoğulları arasından yok edeceksin."],["11","Çünkü sana karşı kötülük etmeye niyetlendiler. Sana karşı başarılı olamayacak bir kötülük tasarladılar."],["12","Çünkü sırtlarını döndüreceksin, gerilmiş yayını yüzlerine doğrulttuğunda."],["13","Gücünle yüksel, ey Yahve, ezgiler söyleyip kudretini övelim."]],22:[["1","Müzik şefi için - “Tan Geyiği” makamında - David’in mezmuru Tanrım, Tanrım, beni neden bıraktın? Neden bana yardım etmekten, iniltimin sözlerinden bu kadar uzaksın?"],["2","Tanrım, gündüz çağırıyorum ama yanıt vermiyorsun, geceleyin ve sessiz kalmıyorum."],["3","Oysa sen kutsalsın, meskenini İsrael'in övgüleri üzerine kurarsın."],["4","Atalarımız sana güvendi. Güvendiler ve sen de onları kurtardın."],["5","Sana seslendiler ve kurtuldular. Sana güvendiler ve hayal kırıklığına uğramadılar."],["6","Ama toprak kurduyum ben, insan değilim, insanların yüz karasıyım, halkın hor gördüğü biri."],["7","Beni görenlerin hepsi benimle alay ediyor. Dudaklarıyla beni aşağılıyorlar. Başlarını sallayıp şöyle diyorlar:"],["8","“Yahve’ye güvendi. Onu kurtarsın. Madem ondan hoşlanıyor, onu kurtarsın bakalım!”"],["9","Oysa beni rahimden sen çıkardın. Ana kucağındayken güvenmemi sağladın."],["10","Ana rahminden sana teslim edildim. Doğumumdan beri Tanrım sensin."],["11","Benden uzak durma, çünkü sıkıntı yakın. Çünkü yardım edecek kimse yok."],["12","Birçok boğalar beni kuşattı. Başan'ın güçlü boğaları çevremi sardı."],["13","Bana karşı ağızlarını sonuna kadar açıyorlar, avını parçalayan aslanlar gibi kükrüyorlar."],["14","Su gibi dökülüyorum. Bütün kemiklerim eklemlerinden çıktı. Yüreğim balmumu gibi, içimde eriyor."],["15","Gücüm çömlek parçası gibi kurudu. Dilim damağıma yapışıyor. Beni ölüm toprağına yatırdın."],["16","Çünkü köpekler çevremi sardı. Kötüler sürüsü beni kuşattı. Ellerimi ve ayaklarımı deldiler."],["17","Bütün kemiklerimi sayabilirim. Gözlerini dikmiş, bana bakıyorlar."],["18","Giysilerimi aralarında paylaşıyorlar. Elbisem için kura çekiyorlar."],["19","Ama sen, ey Yahve, uzak durma! Sensin benim yardımcım. Bana yardım etmek için acele et!"],["20","Canımı kılıçtan, değerli hayatımı köpeğin gücünden kurtar."],["21","Aslanın ağzından kurtar beni! Evet, beni yaban öküzlerinin boynuzlarından kurtardın."],["22","Adını kardeşlerime duyuracağım. Topluluğun ortasında seni öveceğim."],["23","Ey Yahve'den korkanlar, O’nu övün! Ey Yakov soyu, O'nu yüceltin! Ey İsrael soyu, O'ndan korkun!"],["24","Çünkü O, mazlumun sıkıntısını küçümsemedi, tiksinmedi. Yüzünü de ondan gizlemedi; ama mazlum O’na seslenince, O sesini duydu."],["25","Büyük toplulukta övgüm sendendir. O’ndan korkanların önünde adaklarımı yerine getireceğim."],["26","Alçakgönüllüler yiyip doyacak. O’nu arayanlar Yahve'ye şükredecekler. Yürekleriniz sonsuza dek yaşasın."],["27","Yeryüzünün bütün uçları hatırlayacak ve Yahve’ye dönecek. Ulusların bütün soyları senin önünde tapınacaklar."],["28","Çünkü krallık Yahve’nindir. Uluslar üzerinde hükümdar O’dur."],["29","Dünyanın bütün zenginleri yiyecek ve tapınacaklar. Toprağa inen herkes O’nun önünde eğilecek, canını hayatta tutamayanlar bile."],["30","Gelecek kuşaklar O’na hizmet edecek. Sonraki kuşaklara Efendi anlatılacak."],["31","Gelip O'nun doğruluğunu henüz doğmamış halka bildirecekler. Çünkü bunu O yaptı."]],23:[["1","David’in mezmuru Yahve benim çobanımdır, hiç eksiğim olmaz."],["2","Beni yeşil çayırlarda yatırır. Sakin suların yanına götürür."],["3","Canımı onarır. Adı uğruna doğruluk yollarında bana rehberlik eder."],["4","Ölüm gölgesindeki vadiden geçsem bile, kötülükten hiç korkmam, çünkü sen benimlesin. Senin asan, değneğin, onlar rahatlatır beni."],["5","Düşmanlarımın huzurunda, önüme sofra kurarsın. Başımı yağla meshedersin. Kâsem taşmakta."],["6","Kesinlikle hayatımın bütün günlerinde iyilik ve sevgi izleyecek beni, ve daima Yahve’nin evinde oturacağım."]],24:[["1","David’in mezmuru Yahve’nindir yeryüzü, doluluğuyla birlikte. Dünya ve onda oturanlar."],["2","Çünkü O’dur onu denizlerin üzerinde kuran, taşkınlar üzerinde durduran."],["3","Yahve’nin dağına kim çıkabilir? Kim O’nun kutsal yerinde durabilir?"],["4","Elleri temiz, yüreği pak olan; canını yalana kaptırmamış, hileyle yemin etmemiştir böylesi."],["5","O kişi Yahve’nin bereketini, kurtuluşunun Tanrısı’ndan gelen doğruluğu alacaktır."],["6","Bu O'nu arayanların kuşağıdır, senin yüzünü arayanların— Yakov gibi. Selah."],["7","Kaldırın başınızı, ey kapılar! Yükselin, ey ebedi kapılar, yücelik Kralı içeri girsin."],["8","Kimdir o Yücelik Kralı? Yahve’dir O, güçlü ve kudretli, Yahve savaşta kudretlidir."],["9","Kaldırın başınızı, ey kapılar, yükselin ey ebedi kapılar, yücelik Kralı içeri girsin."],["10","Kimdir o yücelik Kralı? Ordular Yahvesi, yücelik Kralı O’dur! Selah."]],25:[["1","David’in mezmuru Ey Yahve, canımı sana kaldırıyorum."],["2","Tanrım, sana güvendim, utandırma beni. Düşmanlarımın bana galip gelmesine izin verme."],["3","Seni bekleyen hiç kimse utanmayacak. Sebepsiz yere hainlik edenler utanacaklar."],["4","Bana yollarını göster, ey Yahve. Bana yönlerini bildir."],["5","Bana kendi gerçeğinde yol göster ve öğret, çünkü sen kurtuluşumun Tanrısı’sın, bütün gün seni bekliyorum."],["6","Ey Yahve, sevecen merhametlerini ve sevgi dolu iyiliğini hatırla, çünkü onlar eski zamanlardan beri aynıdır."],["7","Gençlik günahlarımı ve gençlik isyanlarımı hatırlama. Beni sevgi dolu iyiliğinle, iyiliğine göre hatırla, ey Yahve."],["8","Yahve iyi ve doğrudur, bu nedenle günahkârlara yolu gösterir."],["9","Alçakgönüllülere adalet yolunda yol gösterecek. Kendi yolunu onlara öğretecek."],["10","Antlaşmasını ve tanıklıklarını tutanlar için, Yahve’nin bütün yolları sevgi dolu iyilik ve gerçektir."],["11","Adın uğruna, ey Yahve, günahımı bağışla, çünkü günahım büyüktür."],["12","Yahve'den korkan adam kimdir? Yahve ona seçeceği yolu bildirecektir."],["13","Onun canı rahat edecek. Soyu ülkeyi miras alacaktır."],["14","Yahve’nin dostluğu kendisinden korkanlarladır. Onlara antlaşmasını gösterecektir."],["15","Gözlerim hep Yahve’nin üstündedir, çünkü ayaklarımı ağdan O çıkarır."],["16","Bana yüzünü çevir ve merhamet et, çünkü kimsesiz ve dertliyim."],["17","Yüreğimin darlıkları çoğaldı. Beni sıkıntılarımdan kurtar."],["18","Çektiğim sıkıntıları ve acıları gör de, bütün günahlarımı bağışla."],["19","Düşmanlarıma bak, çünkü çokturlar. Şiddetle benden nefret ediyorlar."],["20","Canımı koru, kurtar beni. Hayal kırıklığına uğramayayım, çünkü sana sığınıyorum."],["21","Beni dürüstlük ve doğruluk korusun, çünkü seni bekliyorum."],["22","Ey Tanrı, İsrael'i bütün sıkıntılarından kurtar."]],26:[["1","David’in mezmuru Beni yargıla, ey Yahve, çünkü dürüstlüğümle yürüdüm. Sarsılmadan Yahve'ye güvendim."],["2","Beni dene, ey Yahve, sına beni. Yüreğimi ve aklımı yokla."],["3","Çünkü sevgi dolu iyiliğin gözlerimin önündedir. Senin gerçeğinde yürüdüm."],["4","Hilekâr adamlarla oturmadım, ikiyüzlülerin arasına da girmem."],["5","Kötülük yapanlar topluluğundan nefret ederim, kötülerle birlikte oturmam."],["6","Ellerimi masumiyetle yıkar, sunağının etrafında dönerim, ey Yahve,"],["7","ta ki, şükran sesini duyurayım ve tüm harika işlerini anlatayım."],["8","Ey Yahve, oturduğun evi, görkeminin bulunduğu yeri severim."],["9","Canımı günahkârlarla, hayatımı kana susamış adamlarla bir araya getirme."],["10","Kötülük ellerindedir, sağ elleri rüşvetle doludur."],["11","Ama ben dürüstlüğümle yürüyeceğim. Beni kurtar ve bana merhamet et."],["12","Ayağım düzlükte durur. Topluluklarda Yahve'yi yücelteceğim."]],27:[["1","David’in mezmuru Yahve benim ışığım ve kurtuluşumdur. Kimden çekineyim? Yahve hayatımın gücüdür. Kimden korkayım?"],["2","Kötüler etimi yemek için üzerime geldiklerinde, hasımlarım ve düşmanlarım bile tökezlediler ve düştüler."],["3","Bana karşı bir ordu konaklasa, yüreğim korkmaz. Bana karşı savaş açılsa, yine de güvenimi korurum."],["4","Yahve'den tek bir şey diledim ve onu ararım: Yahve’nin güzelliğini görüp, O’nun tapınağında hayran olmak için, hayatımın bütün günlerinde Yahve’nin evinde oturmaktır."],["5","Çünkü sıkıntı gününde beni gizlice çardağında tutacak. Beni çadırının gizli yerinde saklayacak. Kaya üzerinde beni yükseltecek."],["6","Artık başım çevremdeki düşmanlarımın üzerinde yükselecek. O’nun çadırında sevinç kurbanları sunacağım. Ezgilerle, ilahilerle Yahve’yi öveceğim."],["7","Sesimle çağırdığımda duy, ey Yahve. Bana merhamet et, yanıtla beni."],["8","“Yüzümü ara” dediğin zaman, yüreğim sana, “Yüzünü arıyorum, ey Yahve” dedi."],["9","Yüzünü benden gizleme. Hizmetkârını öfkeyle uzaklaştırma. Yardımcım sen oldun. Bırakma, terk etme beni, ey kurtuluşumun Tanrısı."],["10","Babamla annem beni terk ettiğinde, Yahve beni yukarı kaldırır."],["11","Bana kendi yolunu öğret, ey Yahve. Düşmanlarımdan ötürü bana doğru yolda rehber ol."],["12","Beni hasımlarımın keyfine bırakma, Çünkü yalancı tanıklar karşıma dikildi, şiddet soluyorlar."],["13","Yaşayanlar diyarında Yahve’nin iyiliğini göreceğimden ben hâlâ eminim."],["14","Yahve’yi bekle. Güçlü ol ve yüreğin cesaretli olsun. Evet, Yahve'yi bekle."]],28:[["1","David’in mezmuru Ey Yahve, sana sesleniyorum, kayam benim, kulak tıkama sesime, bana karşı sessiz kalırsan, çukura inenler gibi olurum."],["2","Sana haykırdığımda, ellerimi En Kutsal Yerine doğru kaldırdığımda, dileklerimin sesini duy."],["3","Beni kötülerle, kötülüğün işçileriyle aynı yere çekme. Onlar komşularıyla barış konuşurlar ama yüreklerinde kötülük vardır."],["4","Onlara yaptıklarına göre, işledikleri kötülüğün karşılığına göre ver. Ellerinin işlerine göre onlara ver. Onlara hak ettiklerinin karşılığını ver."],["5","Madem Yahve’nin işlerine, ellerinin işine saygı duymuyorlar, Yahve onları yıkacak ve bina etmeyecektir."],["6","Yahve’ye övgüler olsun, çünkü dileklerimin sesini duydu."],["7","Yahve benim gücüm ve kalkanımdır. Yüreğim O’na güvendi ve yardım buldum. Bu nedenle yüreğim coşuyor. Ezgimle O’na şükredeceğim."],["8","Yahve onların gücüdür. O, meshettiğinin kurtuluş kalesidir."],["9","Halkını kurtar, mirasını kutsa. Onların çobanı ol, ve onları daima taşı."]],29:[["1","David’in mezmuru Ey kudretli olanın oğulları, Yahve’ye verin, Yahve’ye yücelik ve güç verin."],["2","Adından ötürü yüceliği Yahve’ye verin. Kutsal düzen içinde Yahve’ye tapının."],["3","Yahve'nin sesi suların üstündedir. Yücelik Tanrısı, Yahve birçok sular üstünde gürlüyor."],["4","Yahve'nin sesi güçlüdür. Yahve’nin sesi heybetle doludur."],["5","Yahve’nin sesi sedir ağaçlarını kırar. Evet, Yahve Lübnan sedirlerini parçalar."],["6","Onları buzağı gibi, Lübnan’ı ve Siryon’u yaban öküzü yavrusu gibi sıçratır."],["7","Yahve’nin sesi şimşek gibi çakar."],["8","Yahve'nin sesi çölü sarsar. Yahve Kadeş Çölü’nü sarsar."],["9","Yahve’nin sesi geyikleri doğurtur, ormanları çıplak bırakır. O’nun tapınağındaki her şey “Yücesin!” diyor."],["10","Yahve Tufan'da tahtına oturdu. Evet, Yahve sonsuza dek Kral olarak oturur."],["11","Yahve halkına güç verir. Yahve halkını esenlikle kutsar."]],30:[["1","Tapınak adanırken söylenen bir ilahi Seni överim, ey Yahve, çünkü beni ayağa kaldırdın, düşmanlarımı bana sevindirmedin."],["2","Ey Yahve Tanrım, sana seslendim, ve bana şifa verdin."],["3","Ey Yahve, canımı Şeol'den çıkardın. Çukura inmeyeyim diye beni hayatta tuttun."],["4","Ey O’nun kutsalları, Yahve’yi ilahilerle övün. O'nun kutsal adına şükredin."],["5","Çünkü öfkesi bir an içindir. Lütfu ise bir ömür. Ağlayış bir gece kalabilir, ama sabahleyin sevinç gelir."],["6","Bense, bolluk içinde şöyle dedim: “Asla sarsılmayacağım.”"],["7","Ey Yahve, lütfunla dağımı sağlamlaştırdın; ama sen yüzünü gizleyince sıkıntı duydum."],["8","Ey Yahve, sana seslendim. Efendime rica ettim:"],["9","“Eğer çukura inersem, yıkımımın ne yararı olur? Toprak seni över mi? Senin gerçeğini ilan eder mi?"],["10","Duy, ey Yahve, bana merhamet et. Yardımcım ol, ey Yahve!”"],["11","Yasımı benim için raksa çevirdin. Çulumu çıkardın ve bana sevinç giydirdin,"],["12","ta ki yüreğim seni ilahilerle övsün ve susmasın. Ey Yahve Tanrım, sana daima şükredeceğim!"]],31:[["1","Müzik şefi için - David’in mezmuru Ey Yahve, sana sığınıyorum, hiçbir zaman beni hayal kırıklığına uğratma. Beni kendi doğruluğunla kurtar."],["2","Kulak ver bana. Beni tez kurtar. Bana güçlü bir kaya, beni kurtarmak için sığınacak ev ol."],["3","Çünkü sen benim kayam ve kalemsin, bu nedenle, adın uğruna bana yol göster ve bana rehber ol."],["4","Benim için gizlice kurdukları ağdan beni çekip çıkar, çünkü sen benim kalemsin."],["5","Ruhumu ellerine emanet ediyorum. Gerçeğin Tanrısı, ey Yahve, beni kurtar."],["6","Yalancı putlara saygı duyanlardan nefret ederim, ancak Yahve’ye güvenirim."],["7","Senin sevgi dolu iyiliğinle sevinip coşacağım, çünkü çektiğim sıkıntıyı gördün. Canımı sıkıntılar içinde bildin."],["8","Beni düşmanın eli içinde kapatmadın. Ayaklarımı geniş bir yere yerleştirdin."],["9","Bana merhamet et, ey Yahve, çünkü sıkıntıdayım. Gözüm, canım, bedenim kederden eriyip gidiyor."],["10","Çünkü ömrüm kederle geçti, yıllarım iniltiyle, suçumdan ötürü gücüm tükeniyor. Kemiklerim eriyip gidiyor."],["11","Bütün düşmanlarım yüzünden komşularıma karşı büsbütün aşağılık birisi, tanıdıklarım için dehşet oldum. Beni sokakta görenler benden kaçar oldu."],["12","Ölü bir adam gibi yüreklerinden unutulup gittim. Kırık bir çömlek gibiyim."],["13","Çünkü birçok insanın iftiralarını duydum, her tarafta dehşet içinde. Onlar bana karşı düzen kurarken, canımı almak için anlaştılar."],["14","Ama ben sana güveniyorum, ey Yahve. “Tanrım sensin” dedim."],["15","Vakitlerim senin elinde. Beni düşmanlarımın elinden ve bana zulmedenlerden kurtar."],["16","Yüzün hizmetkârının üzerinde parlasın. Beni sevgi dolu iyiliğinle kurtar."],["17","Hayal kırıklığına uğramayayım, ey Yahve, çünkü seni çağırdım. Kötüler hayal kırıklığına uğrasınlar. Şeol'de sessiz kalsınlar."],["18","Yalan söyleyen dudaklar sessiz kalsın, doğruların aleyhinde küstahça, gurur ve küçümsemeyle konuşurlar."],["19","Senden korkanlar için sakladığın, sana sığınanlar için yaptığın, insanoğullarının önündeki, iyiliğin ne büyüktür!"],["20","Onları huzurunun barınağında, insanların tuzaklarından gizlersin. Kavgacı dillerden bir çardakta onları saklarsın."],["21","Yahve’ye övgüler olsun, çünkü güçlü bir kentte bana şaşılası sevgi dolu iyiliğini gösterdi."],["22","Bana gelince, aceleyle, “Gözlerinin önünden atıldım” dedim. Yine de sana seslendiğimde dileklerimin sesini duydun."],["23","Yahve’yi sevin, ey O’nun kutsalları! Yahve sadıkları korur, kibirli davrananlara tam karşılığını verir."],["24","Ey sizler, Yahve’ye umut bağlayanlar, hepiniz, güçlü olun ve yüreğiniz cesaretli olsun."]],32:[["1","David’in mezmuru - Maskil Ne mutlu itaatsizliği bağışlanmış, günahı örtülmüş olan insana."],["2","Ne mutlu Yahve tarafından suçu sayılmayan, ruhunda hile olmayan insana."],["3","Sustuğumda gün boyu inlemelerimden kemiklerim eridi."],["4","Gece gündüz elin üzerimde ağırdı. Yaz sıcağında gücüm tükendi. Selah."],["5","Günahımı sana itiraf ettim. Suçumu saklamadım. “Yahve'ye isyanlarımı itiraf edeceğim” dedim. Günahımın suçunu bağışladın. Selah."],["6","Bunun için, bulunabileceğin sırada, tanrısal olan herkes sana dua etsin. Büyük sular taştığında kesinlikle ona erişemezler."],["7","Sensin benim sığınağım. Beni sıkıntıdan korursun. Beni kurtuluş ezgileriyle kuşatırsın. Selah."],["8","Eğiteceğim seni, gideceğin yolu sana öğreteceğim. Gözüm üzerinde, sana öğüt vereceğim."],["9","Anlayışsız at ya da katır gibi olmayın. Onları tutmak için gem ve dizgin olmazsa, sana yaklaşamazlar."],["10","Çok keder gelir kötülerin başına, ama güveni Yahve olanı sevgi dolu iyilik kuşatacaktır."],["11","Ey doğrular, Yahve ile sevinin ve coşun! Ey yüreği doğru olanlar, sevinçle haykırın!"]],33:[["1","Ey doğrular, Yahve ile sevinin! Doğrulara övgü yaraşır."],["2","Lir çalarak Yahve’ye şükredin. On telli arpla O'nu ilahilerle övün."],["3","O’na yeni bir ezgi söyleyin. Sevinç çığlığıyla ustaca çalın!"],["4","Çünkü Yahve’nin sözü doğrudur. Bütün işlerini sadakatle yapar."],["5","Doğruluğu ve adaleti sever. Dünya Yahve’nin sevgi dolu iyiliğiyle doludur."],["6","Gökler Yahve’nin sözüyle, onların bütün orduları ağzının soluğuyla yaratıldı."],["7","Denizin sularını bir yığın gibi toplar. Derinliklerini ambarlarda yığar."],["8","Bütün yeryüzü Yahve'den korksun. Dünyada yaşayan herkes O’na hayranlık duysun."],["9","Çünkü O söyledi ve oldu. O buyurdu ve sağlam durdu."],["10","Yahve ulusların öğüdünü boşa çıkarır. Halkların düşüncelerini hiç eder."],["11","Yahve’nin öğüdü sonsuza dek, yüreğinin düşünceleri tüm kuşaklar boyunca yerinde durur."],["12","Ne mutlu Tanrısı Yahve olan ulusa, kendi mirası olarak seçtiği halka."],["13","Yahve gökten bakar. Bütün insanoğullarını görür."],["14","Yaşadığı yerden yeryüzünde yaşayanların tümünü gözler."],["15","Her birinin yüreğine biçim veren, onların bütün işlerini tartan O’dur."],["16","Asker çokluğuyla kurtulan kral yoktur. Ne de büyük gücüyle kurtulan bir yiğit vardır."],["17","Güvenlik için at boştur, büyük gücüne karşın kimseyi kurtarmaz."],["18","İşte, Yahve’nin gözü kendisinden korkanların, O’nun sevgi dolu iyiliğine umut bağlayanların üzerindedir."],["19","Böylece onları ölümden kurtarır, kıtlık içinde onları yaşatır."],["20","Canımız Yahve’yi bekler. O bizim yardımımız ve kalkanımızdır."],["21","Yüreğimiz O’nda sevinç bulur, çünkü biz O'nun kutsal adına güvendik."],["22","Madem umudumuz sende, sevgi dolu iyiliğin üzerimizde olsun, ey Yahve!"]],34:[["1","David’in mezmuru Avimelek’in önünde kendini deli gibi gösterip kovulduğu, ayrıldığı zaman Yahve’yi her zaman öveceğim. O’nun övgüsü hep ağzımda olacak."],["2","Canım Yahve ile övünür. Alçakgönüllüler bunu duyup sevinsin."],["3","Yahve'yi benimle birlikte övün. Adını hep birlikte yüceltelim."],["4","Yahve’yi aradım ve bana yanıt verdi, ve beni tüm korkularımdan kurtardı."],["5","O’na baktılar, ışıl ışıl parladılar. Yüzlerini asla utanç kaplamayacak."],["6","Bu yoksul adam yakardı ve Yahve onu duydu, ve onu bütün sıkıntılarından kurtardı."],["7","Yahve’nin meleği kendisinden korkanların çevresinde, ordugâh kurar, onları kurtarır."],["8","Tadın ve görün, Yahve ne iyidir. Ne mutlu O'na sığınan insana."],["9","Yahve'den korkun, ey O’nun kutsalları, çünkü O'ndan korkanların eksiği olmaz."],["10","Genç aslanlar muhtaç olur, açlık çekerler, ama Yahve’yi arayanlar hiçbir iyilikten yoksun kalmaz."],["11","Gelin ey çocuklar, beni dinleyin. Size Yahve korkusunu öğreteyim."],["12","Kimdir hayatı arzulayan kişi, iyilik görmek için uzun günler seven?"],["13","Dilini kötülükten, dudaklarını yalan söylemekten uzak tutsun."],["14","Kötülükten uzak durun, iyilik yapın. Esenliği arayın ve ardınca gidin."],["15","Yahve’nin gözleri doğruların üzerindedir. Kulakları onların feryadını duyar."],["16","Yahve’nin yüzü kötülük yapanlara karşıdır, onların anılarını yeryüzünden kesip atar."],["17","Doğrular feryat eder, Yahve duyar, onları bütün sıkıntılarından kurtarır."],["18","Yahve yüreği kırık olanlara yakındır, ruhu ezilmiş olanları kurtarır."],["19","Doğrunun dertleri çoktur, ama Yahve onu hepsinden kurtarır."],["20","Bütün kemiklerini korur. Onlardan hiçbiri kırılmaz."],["21","Kötüyü kötülük öldürür. Doğru kişiden nefret edenler mahkûm olurlar."],["22","Yahve hizmetkârının canını kurtarır. O’na sığınanların hiçbiri mahkûm olmaz."]],35:[["1","David’in mezmuru Ey Yahve, benimle çekişenlerle sen çekiş, bana karşı savaşanlarla sen savaş."],["2","Küçük ve büyük kalkanı al, yardımım için ayağa kalk."],["3","Mızrağı savur ve beni kovalayanları engelle. Canıma, “Senin kurtuluşun benim.” de."],["4","Canımı almak isteyenler hayal kırıklığına uğrayıp rezil olsunlar. Bana kötülük düşünenler geri dönüp şaşkına dönsünler."],["5","Rüzgârın önündeki saman çöpü gibi olsunlar, Yahve’nin meleği onları sürsün."],["6","Yolları karanlık ve kaygan olsun, Yahve'nin meleği onların peşlerine düşsün."],["7","Çünkü nedensiz yere benim için ağlarını çukurda gizlediler. Hiçbir sebep yokken canıma çukur kazdılar."],["8","Habersiz yıkım üzerine gelsin. Gizlediği ağ kendisini yakalasın. O yıkımın içine kendisi düşsün."],["9","Canım Yahve’de sevinç bulacak. O’nun kurtarışıyla sevinecek."],["10","Bütün kemiklerim şöyle diyecek: “Senin gibisi var mı, ey Yahve, yoksulu kendisine göre çok güçlü olanın elinden, yoksulu, muhtacı soyguncudan kurtaran?”"],["11","Yalancı tanıklar ayağa kalkıyor. Bilmediğim şeyleri bana soruyorlar."],["12","Canımı kederlendirmek için, iyiliğe karşı bana kötülük ediyorlar."],["13","Ben ise, onlar hastalandıklarında çul kuşanırdım. Oruçla canımı alçaltırdım. Duam kendi bağrıma dönerdi."],["14","Onlara dostum ya da kardeşimmiş gibi davranırdım. Annesi için yas tutan birisi gibi yas tutarak yere kapanırdım."],["15","Ama benim sıkıntım karşısında sevindiler ve bir araya toplandılar. Saldırganlar bana karşı toplandılar ve ben bunu bilmiyordum. Bana saldırdılar ve durmadılar."],["16","Ziyafetlerdeki kirli soytarılar gibi, bana dişlerini gıcırdattılar."],["17","Ey Efendim, ne zamana dek bakacaksın? Canımı onların yok edişinden, hayatımı genç aslanlardan kurtar."],["18","Büyük toplantıda sana şükürler sunacağım. Kalabalığın ortasında seni öveceğim."],["19","Düşmanlarım haksız yere bana karşı sevinmesinler; benden nedensiz yere nefret edenler, göz kırpmasınlar."],["20","Çünkü onlar esenlikten söz etmezler, ama ülkenin sakin insanlarına karşı hileli sözler uydururlar."],["21","Bana karşı ağızlarını sonuna kadar açtılar. “Oh! Oh! Gözümüz bunu gördü!” diyorlar."],["22","Sen bunu gördün, ey Yahve. Sessiz kalma. Ey Efendim benden uzak durma."],["23","Ey Tanrım, uyan, kalk ve savun beni! Ey Efendim, benim için gayrete gel!"],["24","Doğruluğuna göre beni haklı çıkar, ey Yahve Tanrım. Bana karşı sevinmelerine izin verme."],["25","Yüreklerinde, “Oh! Dileğimiz buydu, onu yuttuk!” demesinler."],["26","Felaketime sevinenler, hayal kırıklığına uğrayıp şaşkına dönsünler. Bana karşı kendilerini yüceltenler, utanç ve rezilliğe bürünsünler."],["27","Haklı davamı destekleyenler, sevinçle haykırıp coşsunlar. Sürekli şöyle desinler: “Hizmetkârının bolluk içinde olmasından hoşlanan Yahve yücelsin!”"],["28","Dilim gün boyu senin doğruluğundan, övgülerinden söz edecek."]],36:[["1","Müzik şefi için- Yahve’nin hizmetkârı David’in mezmuru Kötünün itaatsizliği hakkında yüreğimde bir esin var: “Gözünde Tanrı korkusu yoktur.”"],["2","Kendini beğendiği için, günahını fark edemez ve ondan nefret etmez."],["3","Ağzının sözleri kötülük ve hiledir. Akıllı olmayı ve iyilik yapmayı bırakmıştır."],["4","Yatağında kötülük tasarlar. Kendini iyi olmayan bir yola sokar. Kötülükten nefret etmez."],["5","Sevgi dolu iyiliğin, ey Yahve, göklerdedir. Sadakatin gökyüzüne ulaşır."],["6","Doğruluğun Tanrı'nın dağları, yargıların büyük derinlik gibidir. Ey Yahve, insanı ve hayvanı koruyan sensin."],["7","Sevgi dolu iyiliğin ne değerli, ey Tanrı! İnsanoğulları kanatlarının gölgesine sığınır."],["8","Evinin bolluğuyla bol bol doyacaklar. Senin zevklerinin ırmağından onlara içireceksin."],["9","Çünkü hayatın kaynağı sendedir. Senin ışığında ışığı göreceğiz."],["10","Seni tanıyanlara sevgi dolu iyiliğini, yüreği doğru olanlara karşı doğruluğunu sürdür."],["11","Gururlunun ayağının bana karşı gelmesine, kötünün elinin beni kovmasına izin verme."],["12","Orada kötülük yapanlar düştü. Yıkıldılar ve kalkamazlar."]],37:[["1","David’in mezmuru Kötülük edenler yüzünden üzülme, haksızlık yapanlara da özenme."],["2","Çünkü yakında ot gibi biçilecekler, yeşil bitki gibi solup gidecekler."],["3","Yahve’ye güven ve iyilik et. Ülkede otur ve güvenli otlakların tadını çıkar."],["4","Yahve’den de zevk al, O da sana yüreğinin dileklerini verecektir."],["5","Yolunu Yahve'ye teslim et. O’na güven, O da şunu yapacaktır:"],["6","Doğruluğunu ışık gibi, hakkını öğlen güneşi gibi parlatacaktır."],["7","Yahve’de dinlen, O’nu sabırla bekle. Üzülme işi yolunda olup da, kötü planlarını gerçekleştiren kişi için."],["8","Kızmaktan vazgeç, öfkeyi bırak. Üzülme, bu yalnızca kötülüğe sürükler."],["9","Çünkü kötülük edenler kesilip atılacak, ama Yahve’yi bekleyenler ülkeyi miras alacak."],["10","Kısa bir süre sonra kötüler yok olacak. Yerini arasan bile artık orada bulunmayacak."],["11","Ama alçakgönüllüler ülkeyi miras alacaklar, taşkın esenlikten tad alacaklar."],["12","Kötü doğruya karşı düzen kurar, ve ona diş gıcırdatır."],["13","Efendi ona güler, çünkü onun gününün geldiğini görür."],["14","Kötüler kılıç çekip yaylarını gerdiler, yoksulları ve muhtaçları yere sermek, yolu doğru olanları öldürmek için."],["15","Onların kılıcı kendi yüreklerine girecek, yayları kırılacaktır."],["16","Doğrunun azı, birçok kötünün bolluğundan daha iyidir."],["17","Çünkü kötülerin gücü kırılacak, ama Yahve doğrulara destek olur."],["18","Yahve kusursuz olanların günlerini bilir. Onların mirası daima kalıcıdır."],["19","Kötülük zamanında hayal kırıklığına uğramayacaklar. Kıtlık günlerinde doyurulacaklar."],["20","Ama kötüler yok olacaklar. Yahve’nin düşmanları kırların güzelliğine benzeyecek. Duman gibi dağılıp yok olacak."],["21","Kötü kişi ödünç alır da geri vermez, ama doğru kişi cömertçe verir."],["22","Çünkü O’nun kutsadıkları ülkeyi miras alacak. O’nun lanetledikleri kesilip atılacaktır."],["23","İnsanın adımları Yahve tarafından pekiştirilir. Onun yolundan hoşnuttur."],["24","Tökezlese de düşmez, çünkü elinden tutan Yahve’dir."],["25","Gençtim, şimdi yaşlandım, yine de doğruların terk edildiğini, ve de çocuklarının ekmek dilendiğini hiç görmedim."],["26","Bütün gün merhametle davranır ve ödünç verir. Onun soyu kutsanır."],["27","Kötülükten uzak dur, iyilik et. Sonsuza dek güven içinde yaşa."],["28","Çünkü Yahve adaleti sever, kutsallarını terk etmez. Onlar daima korunur, ama kötülerin soyu kesilip atılacak."],["29","Doğrular ülkeyi miras alacak, ve daima içinde yaşayacaklar."],["30","Doğrunun ağzı bilgelik konuşur. Dili adaleti söyler."],["31","Tanrısı’nın yasası yüreğindedir. Adımlarından hiçbiri kaymaz."],["32","Kötü doğruyu gözetler, onu öldürmenin yolunu arar."],["33","Yahve onu kötünün eline bırakmaz, yargılandığında onu mahkûm etmez."],["34","Yahve'yi bekle, O’nun yolunu tut, ülkeyi miras almak için seni yükseltecektir. Kötüler kesilip atıldığı zaman, bunu göreceksin."],["35","Kötüyü büyük güç içinde gördüm, yeşil bir ağaç gibi bittiği yerde yayılmış."],["36","Ama gelip geçti işte, artık o yok. Onu aradım ama bulunamadı."],["37","Kusursuz adamın üzerine bir nişan koy, doğru adama bak, çünkü gelecek esenlik adamınındır."],["38","İsyan edenlere gelince, onlar hep birlikte yok edilecekler. Kötülerin geleceği kesilip atılacaktır."],["39","Ama doğruların kurtuluşu Yahve'dendir. O, sıkıntı zamanlarında onların kalesidir."],["40","Yahve onlara yardım eder ve onları kurtarır. Onları kötülerin elinden kurtarıp özgür kılar, çünkü O’na sığındılar."]],38:[["1","Anma sunusu için David’in mezmuru Ey Yahve, öfkenle beni azarlama, gazapla beni yola getirme."],["2","Çünkü okların beni deldi, elin üzerime ağır basıyor."],["3","Öfken yüzünden bedenime rahat yok, günahımdan ötürü kemiklerimde de hiç sağlık kalmadı."],["4","Çünkü kötülüklerim başımı aştı. Ağır bir yük gibi, bana çok ağır geldiler."],["5","Akılsızlığım yüzünden, yaralarım iğrenç ve irinlidir."],["6","Acı çekiyorum, iki büklüm eğildim. Bütün gün yas içindeyim."],["7","Çünkü belim ateşle dolu. Bedenimde hiçbir rahat yok."],["8","Baygınım ve alabildiğine yaralıyım. Yüreğimin acısından inliyorum."],["9","Ey Efendim, bütün dileğim senin önündedir. İnlemelerim senden gizli değil."],["10","Yüreğim çarpıyor. Gücüm tükeniyor. Gözlerimin feri de beni terk etti."],["11","Sevenlerim ve dostlarım felaketimden uzak duruyorlar. Akrabalarım da uzakta durmaktalar."],["12","Canımı almanın yolunu arayanlar da tuzak kuruyorlar. Zararımı arayanlar kötü söz söylüyorlar, gün boyu hileler düşünüyorlar."],["13","Ama ben sağır biri gibi duymuyorum. Ağzını açmayan dilsiz gibiyim."],["14","Ağzında yanıt olmayan, duymayan biri gibiyim."],["15","Çünkü ben sana güveniyorum, ey Yahve. Sen yanıtlayacaksın, ey Efendi Tanrım."],["16","Çünkü dedim ki, “Benden ötürü sevinmesinler, ayağım kayınca böbürlenmesinler.”"],["17","Çünkü ben düşmek üzereyim. Kederim hep önümde."],["18","Çünkü suçumu itiraf ederim. Günahımdan ötürü üzgünüm."],["19","Ama düşmanlarım güçlü ve çoktur. Benden nedensiz yere nefret edenler çoktur."],["20","İyiliğe karşılık kötülük yapanlar bana karşıdırlar, çünkü ben iyilik peşindeyim."],["21","Beni bırakma, ey Yahve! Ey Tanrım, benden uzak durma."],["22","Tez yardım et bana, ey Efendim, kurtuluşum benim."]],39:[["1","Müzik Şefi Yedutun için - David’in mezmuru Şöyle dedim: “Dilimle günah işlemeyeyim diye yollarıma dikkat edeceğim. Kötü kişi karşımdayken, ağzıma gem vuracağım.”"],["2","Dilimi tutup sessiz kaldım. İyilik için bile sustum. Acım katlandı."],["3","Yüreğim yandı içimde. Derin derin düşünürken ateş alevlendi. Dilimle dedim:"],["4","“Ey Yahve, bana sonumu göster, günlerimin ölçüsü nedir? Ne kadar kırılgan olduğumu bana bildir."],["5","İşte günlerimi bir karış kıldın. Ömrüm senin önünde bir hiç gibidir. Besbelli herkes bir soluktur.” Selah."],["6","“Her insan kuşkusuz gölge gibi dolaşır. Gerçekten boş yere didinir durur. Yığar ama onu kimin toplayacağını bilmez."],["7","Şimdi, ey Efendim, ben neyi bekliyorum? Umudum sende."],["8","Beni bütün suçlarımdan kurtar. Akılsızların beni ayıplamasına izin verme."],["9","Sustum, ağzımı açmadım. Çünkü sen bunu yaptın."],["10","Kamçını benden uzaklaştır. Elinin vuruşuyla mahvoldum."],["11","İnsanı suçundan ötürü azarlayıp yola getirdiğinde, servetini güve gibi tüketirsin. Kesinlikle her insan yalnızca bir soluktur.” Selah."],["12","“Duamı işit, ey Yahve, feryadıma kulak ver. Gözyaşlarıma sessiz kalma. Çünkü senin yanında ben bir garibim. Bütün atalarım gibi bir yabancı."],["13","Beni esirge de gücüme kavuşayım, göçüp yok olmadan önce.”"]],40:[["1","Müzik şefi için - David’in mezmuru Yahve’yi sabırla bekledim. Bana döndü ve feryadımı duydu."],["2","Beni korkunç bir çukurdan, balçıktan çıkardı, ayaklarımı bir kaya üzerinde durdurdu. Ayakta durabileceğim sağlam bir yer verdi."],["3","Ağzıma yeni bir ezgi, Tanrımız’a bir övgü ilahisi koydu. Birçokları bunu görüp korkacak, ve Yahve’ye güvenecekler."],["4","Ne mutlu Yahve’ye güvenen insana, kibirlilere, yalana sapanlara saygı duymayana."],["5","Ey Yahve, Tanrım, yaptığın harikalar, bize yönelik düşüncelerin ne çoktur. Onlar sana geri bildirilemezler. İlan edip anlatmak istesem, sayılamayacak kadar çoktur."],["6","Kurban ve sunuyu istemedin. Kulaklarımı açtın. Yakmalık sunu ve günah sunusunu da istemedin."],["7","O zaman şöyle dedim: “İşte geldim. Kutsal Yazı tomarında benim için yazılmıştır."],["8","İsteğini yerine getirmekten zevk alırım, ey Tanrım. Yasan yüreğimin içindedir.”"],["9","Büyük toplulukta doğruluk müjdesini ilan ettim. İşte, dudaklarımı mühürlemeyeceğim, ey Yahve, sen bilirsin."],["10","Doğruluğunu yüreğimin içinde saklamadım. Sadakatini ve kurtuluşunu ilan ettim. Sevgi dolu iyiliğini ve gerçeğini büyük topluluktan gizlemedim."],["11","Sevecen merhametlerini benden esirgeme, ey Yahve. Sevgi dolu iyiliğin ve gerçeğin beni hep korusun."],["12","Çünkü sayısız kötülük çevremi sardı. Suçlarım beni ele geçirdi, artık başımı kaldıramıyorum. Onlar başımdaki saçlardan daha çoktur. Yüreğim beni bıraktı."],["13","Ey Yahve, beni kurtarmaya razı ol. Ey Yahve, tez yardımıma koş."],["14","Canımı almanın yolunu arayanlar, hepsi hayal kırıklığına uğrayıp utansınlar. Acı çekmemden zevk duyanlar, geri dönüp rezil olsunlar."],["15","Bana, “Oh! Oh” çekenler utançlarından perişan olsunlar."],["16","Seni arayanların hepsi sende sevinip coşsunlar. Kurtarışını sevenler sürekli şöyle söylesin: “Yahve yücelsin!”"],["17","Ama ben yoksul ve muhtacım. Efendim beni düşünsün. Sen benim yardımcım ve kurtarıcımsın. Gecikme, ey Tanrım."]],41:[["1","Müzik şefi için- David’in mezmuru Ne mutlu yoksulu düşünen insana. Yahve kurtarır onu kötü günde."],["2","Yahve onu korur ve yaşatır. Yeryüzünde onu kutsar. Onu düşmanlarının keyfine bırakmaz."],["3","Yahve hasta yatağında ona destek olur, hastalık yatağından kaldırır onu."],["4","“Ey Yahve, bana merhamet et!” dedim. “Beni iyileştir, çünkü sana karşı günah işledim.”"],["5","Düşmanlarım bana karşı kötülük konuşuyor: “Ne zaman ölecek ve adı yok olacak?”"],["6","Eğer biri beni görmeye gelirse yalan konuşuyor. Yüreği kendine kötülük biriktiriyor. Dışarı çıktığında bunu söylüyor."],["7","Benden nefret edenlerin hepsi bana karşı fısıldaşıyor. Benim için en kötüsünü düşünüyorlar."],["8","“Kötü bir hastalık bulaştı ona” diyorlar. “İşte yattı, bir daha kalkamaz.”"],["9","Ekmeğimi yiyen, güvendiğim yakın dostum bile, bana karşı topuklarını kaldırdı."],["10","Ama sen, ey Yahve, bana merhamet et, beni kaldır ki, onlara karşılığını vereyim."],["11","Bununla benden hoşnut olduğunu bileceğim. Çünkü düşmanım bana galip gelemeyecek."],["12","Bana gelince, dürüstlüğümde bana destek olur, sonsuza dek beni huzurunda durdurursun."],["13","İsrael'in Tanrısı Yahve'ye öncesizlikten sonsuza dek, övgüler olsun! Amin ve amin."]],42:[["1","Müzik şefi için - Korahoğulları’nın Maskili Geyiğin akarsuları özlediği gibi, canım da seni öyle özler, ey Tanrı."],["2","Canım Tanrı'ya, hay olan Tanrı'ya susadı. Ne zaman gelip Tanrı'nın önünde görüneceğim?"],["3","Gözyaşlarım gece gündüz yemeğim oldu, bana sürekli “Tanrın nerede?” diye soruyorlar."],["4","Şunları hatırlıyor, canımı içime döküyorum; sevinç ve övgü sesiyle nasıl gider, Kutsal Günü kutlayan toplulukla birlikte, onları Tanrı'nın evine nasıl götürürdüm."],["5","Neden umutsuzsun, ey canım? Neden içim huzursuz? Tanrı’ya umut bağla! Çünkü kurtaran varlığınla yardımcım olduğun için O’nu yine de öveceğim."],["6","Ey Tanrım, canım iç varlığımda umutsuzluk içinde. Bu yüzden Yarden diyarından, Hermon dağlarından, Misar Tepesi’nden seni hatırlıyorum."],["7","Çağlayanların ses çıkarınca derin derinliğe sesleniyor. Bütün dalgaların ve sellerin üzerimden geçti."],["8","Yahve gündüz vakti sevgi dolu iyiliğini buyurur. Gece vakti O’nun ezgisi, hayatımın Tanrısı’na dua benimledir."],["9","Kayam olan Tanrı'ya diyeceğim: “Beni neden unuttun? Düşmanın zulmü yüzünden neden yas tutuyorum?”"],["10","Düşmanlarım kemiklerime saplanmış bir kılıç gibi, hakaret ediyorlar, bana sürekli “Tanrın nerede?” diye soruyorlar."],["11","Neden umutsuzsun, ey canım? Neden içim huzursuz? Tanrı’ya umut bağla! Çünkü yine de O’nu öveceğim, yüzümün kurtuluşu ve Tanrım O’dur."]],43:[["1","Davamı gör, ey Tanrım, tanrısız ulusa karşı davamı savun. Beni hileci ve kötü insanlardan kurtar."],["2","Çünkü sen benim gücümün Tanrısı’sın. Beni neden reddettin? Düşmanın zulmünden ötürü neden yas tutayım?"],["3","Işığını ve gerçeğini gönder. Bana yol göstersinler. Beni kutsal dağına, çadırına götürsünler."],["4","O zaman Tanrı'nın sunağına, büyük sevincim olan Tanrım'a gideceğim. Seni arpla öveceğim, Tanrım, Tanrım benim."],["5","Neden umutsuzluk içindesin, ey canım? Neden içim huzursuz? Tanrı’ya umut bağla! Çünkü yine O’nu öveceğim. Kurtarıcım, yardımcım, Tanrım benim."]],44:[["1","Müzik şefi için - Korahoğulları’nın Maskili Kulaklarımızla duyduk, ey Tanrı, atalarımız onların günlerinde, eski günlerde, yaptığın işi bize anlattı."],["2","Ulusları elinle kovdun, ama onları diktin. Halkları kırdın, ama onları yaydın."],["3","Çünkü ülkeyi kendi kılıçlarıyla mülk edinmediler, onları kurtaran kendi kolları da değildi. Ancak senin sağ elin, kolun ve yüzünün ışığıydı. Çünkü sen onları kayırdın."],["4","Ey Tanrı, sensin benim Kralım. Yakov için zaferleri buyur!"],["5","Senin sayende düşmanlarımızı devireceğiz. Bize karşı ayaklananları senin adınla ezeceğiz."],["6","Çünkü ben yayıma güvenmem, kılıcım da beni kurtarmaz."],["7","Ama sensin bizi düşmanlarımızdan kurtaran, bizden nefret edenleri utandıran."],["8","Bütün gün Tanrı'yla övünürüz. Adına daima şükrederiz. Selah."],["9","Ama şimdi sen bizi reddettin ve bizi utandırdın, ordularımızla yola çıkmıyorsun."],["10","Bizi düşmanın önünde geri döndürüyorsun. Bizden nefret edenler kendileri için yağma topluyorlar."],["11","Bizi yenilecek koyun gibi ettin, bizi ulusların arasına dağıttın."],["12","Halkını bedavaya sattın, satışından da hiçbir şey kazanmadın."],["13","Bizi komşularımıza yüzkarası, çevremizdekiler için eğlence ve alay konusu ettin."],["14","Halklar arasında baş sallansın diye, bizi ulusların diline düşürdün."],["15","Rezilliğim gün boyu gözümün önünde, utanç yüzümü kaplıyor,"],["16","hakaret ve sövgüde bulunanın alayıyla, düşmanın ve intikamcının yüzünden."],["17","Bütün bunlar başımıza geldi, yine de seni unutmadık. Antlaşmana ihanet etmedik."],["18","Yüreğimiz geriye dönmedi, adımlarımız da senin yolundan sapmadı,"],["19","oysa sen bizi çakalların yerinde ezdin, üstümüzü ölümün gölgesiyle örttün."],["20","Eğer Tanrımız'ın adını unuttuysak, ya da ellerimizi yabancı bir ilâha uzattıysak,"],["21","Tanrı bunu araştırmaz mıydı? Çünkü O, yürekteki gizleri bilir."],["22","Evet, senin uğruna bütün gün öldürülüyoruz. Kasaplık koyunlar gibi görülüyoruz."],["23","Uyan! Neden uyuyorsun ey Efendim? Kalk! Bizi sonsuza dek reddetme."],["24","Neden yüzünü gizliyorsun? Çektiğimiz acıyı, üzerimizdeki baskıyı unutacak mısın?"],["25","Çünkü canımız toprağa kadar eğildi. Bedenimiz toprağa yapıştı."],["26","Kalk, yardım et bize. Sevgi dolu iyiliğin uğruna bizi kurtar."]],45:[["1","Müzik şefi için - “Zambaklar” makamında Korahoğulları’nın Maskili - Bir düğün ilahisi Yüreğim asil bir temayla dolup taşıyor. Kral için okuyorum şiirlerimi. Dilim usta bir yazarın kalemi gibidir."],["2","Sen insanoğullarının en harikasısın. Dudakların lütufla meshedilmiş. Bunun için Tanrı seni sonsuza dek kutsamış."],["3","Ey kudretli, kılıcını beline, ihtişamını ve heybetini kuşan."],["4","Gerçek, alçakgönüllülük ve doğruluk uğruna, heybetinle zaferle ilerle. Sağ elin harika işler sergilesin."],["5","Okların sivridir. Kral düşmanlarının yüreğine saplanır, uluslar altında yıkılır."],["6","Tahtın sonsuza dek kalıcıdır, ey Tanrı. Krallığının asası adalet asasıdır."],["7","Doğruluğu sevdin ve kötülükten nefret ettin. Bunun için Tanrı, senin Tanrın, seni akranlarından daha çok sevinç yağıyla meshetti."],["8","Bütün giysilerin mür, öd ve tarçın kokar. Fildişi saraylardan telli çalgılar seni sevindirir."],["9","Kral kızları senin saygın kadınların arasındadır. Kraliçe, Ofir altınları içinde senin sağında duruyor."],["10","Dinle kızım, düşün ve kulak ver. Halkını, babanın evini de unut."],["11","Böylece Kral senin güzelliğini arzulayacak, saygı duy O'na, çünkü efendin O'dur."],["12","Sur kızı bir hediyeyle geliyor. Halkın zenginleri senin lütfunu dileyecekler."],["13","Tüm ihtişamıyla kral kızı içerdedir. Giysileri altınla dokunmuştur."],["14","İşlemeli giysiler içinde kralın huzuruna çıkarılacak. Onu takip eden arkadaşları, el değmemiş kızlar sana getirilecek."],["15","Sevinç ve coşkuyla götürülecekler. Kralın sarayına girecekler."],["16","Oğulların atalarının yerini alacak. Onları bütün dünyaya beyler yapacaksın."],["17","Adını kuşaklar boyu anımsatacağım. Bunun için halklar daima sana şükredecekler."]],46:[["1","Müzik şefi için - Alamot - Korahoğulları ezgisi Tanrı sığınağımız ve gücümüzdür, sıkıntıda hemen yardıma hazırdır."],["2","Bu nedenle, dünya altüst olsa, dağlar denizlerin bağrına yıkılsa,"],["3","suları kükreyip çalkalansa, kabaran deniz dağları titretse bile, biz korkmayız. Selah."],["4","Bir ırmak var ki, suları Tanrı kentini, Yüceler Yücesi'nin kutsal çadırlarını sevindirir."],["5","Tanrı onun ortasındadır. Sarsılmaz o. Gün doğarken Tanrı ona yardım eder."],["6","Uluslar hiddetlendi. Krallıklar sarsıldı. O sesini yükseltince dünya eriyip gitti."],["7","Ordular Yahvesi bizimledir. Yakov’un Tanrısı bizim sığınağımızdır. Selah."],["8","Gelin, Yahve’nin işlerini görün, yeryüzünde ne büyük yıkımlar yaptı."],["9","Dünyanın ucuna kadar savaşları durdurur. Yayı kırar, mızrağı parçalar. Savaş arabalarını ateşte yakar."],["10","“Sakin olun, bilin ki, Tanrı benim! Uluslar arasında yüceleceğim. Yeryüzünde yüceleceğim.”"],["11","Ordular Yahvesi bizimledir. Yakov’un Tanrısı bizim sığınağımızdır. Selah."]],47:[["1","Müzik şefi için - Korahoğulları’nın mezmuru Ey bütün uluslar, el çırpın. Zafer sesiyle Tanrı'ya sesinizi yükseltin!"],["2","Çünkü Yüce Yahve muhteşemdir. O, tüm dünyanın üzerinde büyük Kral’dır."],["3","Ulusları altımıza, halkları ayaklarımızın altına serdi."],["4","Sevdiği Yakov’un yüceliği olan mirasımızı, O bizim için seçti. Selah."],["5","Tanrı yüksek sesle, Yahve boru sesiyle yükseldi."],["6","Tanrı'yı ezgilerle övün! Övün! Kralımız’ı ezgilerle övün! Övün!"],["7","Çünkü Tanrı tüm dünyanın Kralı’dır. Anlayışla övün."],["8","Tanrı ulusların üzerinden hüküm sürer. Tanrı kutsal tahtında oturur."],["9","Avraham’ın Tanrısı’na halk olmak üzere, halkların beyleri bir araya toplandılar. Çünkü yeryüzünün kalkanları Tanrı’ya aittir. O çok yücedir!"]],48:[["1","İlahi - Korahoğulları’nın mezmuru Yahve büyüktür, Tanrımız’ın kentinde, kutsal dağında övülmeye çok lâyıktır."],["2","Yüksekliği güzel, tüm dünyanın sevinci, kuzey taraflarındaki Siyon Dağı, Büyük Kral’ın kenti."],["3","Tanrı onun kalelerinde kendini sığınak olarak gösterdi."],["4","Çünkü işte, krallar toplandılar, birlikte geçtiler."],["5","Onu görünce hayrete düştüler. Dehşet içinde aceleyle kaçıştılar."],["6","Doğum sancısı çeken bir kadın gibi, orada onları bir titreme aldı."],["7","Doğu rüzgârıyla Tarşiş'in gemilerini parçalarsın."],["8","Nasıl duyduysak öyle gördük, Ordular Yahvesi'nin kentinde, Tanrımız’ın kentinde. Tanrı onu sonsuza dek pekiştirecektir. Selah."],["9","Ey Tanrı, tapınağının ortasında, senin sevgi dolu iyiliğini düşündük."],["10","Adın gibi, ey Tanrı, övgün de yeryüzünün dört bir bucağına kadar öyledir. Sağ elin doğrulukla doludur."],["11","Siyon Dağı sevinsin! Yahuda kızları senin hükümlerinden ötürü coşsunlar."],["12","Siyon'un çevresinde gezin, etrafını dolanın. Kulelerini sayın."],["13","Surlarına dikkatle bakın. Saraylarını düşünün ki, gelecek kuşağa anlatasınız."],["14","Çünkü bu Tanrı sonsuza dek bizim Tanrımız’dır. Ölüme dek O bize yol gösterecektir."]],49:[["1","Müzik şefi için - Korahoğulları’nın mezmuru Ey bütün halklar, şunu işitin, ey bütün dünya sakinleri,"],["2","hem aşağıdakiler hem yüksektekiler, zengin ve yoksul birlikte dinleyin."],["3","Ağzım bilgelik sözleri konuşacak. Yüreğim anlayış dile getirecek."],["4","Özdeyişe kulak vereceğim. Bilmecemi arpla çözeceğim."],["5","Kötü günlerde neden korkayım ki, alçakların kötülüğü beni kuşattığında?"],["6","Mallarına güveniyorlar, zenginliklerinin çokluğuyla övünüyorlar;"],["7","onların hiçbiri kardeşini kurtaramaz, Tanrı’ya onun için fidye veremez."],["8","Çünkü canlarının kurtuluşu pahalıdır, hiçbir şey bedelini karşılayamaz."],["9","Yoksa sonsuza dek yaşar insan, çürüme yüzü görmezdi."],["10","Çünkü insan bilgelerin öldüğünü görür; budala ve akılsız da aynı şekilde yok olur, mallarını başkalarına bırakırlar."],["11","İçlerindeki düşünce, meskenlerinin tüm kuşaklar boyunca, evlerinin daima kalacağıdır. Topraklarına kendi adlarını verirler."],["12","Ama insan zenginliğine rağmen dayanamaz. Yok olup giden hayvanlara benzer."],["13","Akılsızların, ve onların dediklerini onaylayanların varacakları yer budur. Selah."],["14","Onlar Şeol'e atanmış sürüye benzer. Ölüm onlara çobanlık edecektir. Doğrular sabahleyin onlara hâkim olacak. Konutlarından çok uzakta, güzellikleri Şeol'de çürüyecektir."],["15","Ama Tanrı canımı Şeol'ün elinden kurtaracak. Çünkü beni kabul edecektir. Selah."],["16","Bir adam zengin olursa, evinin görkemi artarsa korkma."],["17","Çünkü öldüğünde yanında hiçbir şey götüremez. Görkemi onun ardınca inmez."],["18","Gerçi yaşarken canını kutsadıysa da— kendin için iyilik ettiğinde insanlar seni överler—"],["19","atalarının nesline gidecektir. Işığı bir daha göremeyecekler."],["20","Anlayıştan yoksun zenginlik sahibi olan insan, yok olup giden hayvanlara benzer."]],50:[["1","Asaf’ın mezmuru Kudretli Olan Tanrı, Yahve konuşuyor, gün doğumundan gün batımına kadar yeryüzüne sesleniyor."],["2","Güzelliğin kusursuzluğu Siyon'dan, Tanrı parlıyor."],["3","Tanrımız geliyor ve susmuyor. Önününde ateş yiyip bitiriyor. Çevresi şiddetli fırtınayla kaplı."],["4","Yukarıdaki göklere sesleniyor, halkını yargılamak için yeryüzüne:"],["5","“Benimle kurban sunarak antlaşma yapan, kutsallarımı yanıma toplayın.”"],["6","Gökler O’nun doğruluğunu ilan edecek, çünkü yargıç Tanrı'nın kendisidir. Selah."],["7","“Ey halkım, dinle de konuşayım. Ey İsrael, sana karşı tanıklık edeyim. Ben Tanrı'yım, senin Tanrın’ım."],["8","Kurbanlarından ötürü seni azarlamıyorum. Yakmalık sunuların sürekli önümde."],["9","Ne ahırından bir boğaya, ne de ağıllarından tekelere ihtiyacım var."],["10","Çünkü tüm orman hayvanları, binlerce dağlardaki sığırlar benimdir."],["11","Dağların bütün kuşlarını bilirim. Kırdaki yabani hayvanlar benimdir."],["12","Aç olsam sana söylemezdim, çünkü dünya ve içindeki her şey benimdir."],["13","Ben boğaların etini yer miyim? Ya da keçilerin kanını içer miyim?"],["14","Tanrı'ya şükran kurbanı sun. Yüceler Yücesi’ne adaklarını öde."],["15","Sıkıntılı gününde beni çağır. Seni kurtarırım ve sen de beni yüceltirsin.”"],["16","Ama kötüye Tanrı şöyle diyor: “Kurallarımı ilan etmeye, antlaşmamı ağzına almaya ne hakkın var?"],["17","Yola getirilmekten nefret ettiğin için, sözlerimi arkana mı atacaksın?"],["18","Bir hırsız görünce ona uyuyor, zina edenlerle bir oluyorsun.”"],["19","“Kötülüğe ağzını veriyorsun dilinle hile uyduruyorsun."],["20","Oturup kardeşinin aleyhinde konuşuyor, kendi annenin oğluna iftira ediyorsun."],["21","Sen bunları yaptın, bense sustum. Beni de tıpkı kendin gibi mi sandın. Seni azarlıyor, gözlerinin önünde seni suçluyorum.”"],["22","“Ey siz Tanrı’yı unutanlar, şimdi şunu iyi tartın, yoksa sizi parçalarım, kurtaran kimse olmaz."],["23","Kim şükran kurbanını sunarsa beni yüceltir; kendisine Tanrı’nın kurtuluşunu göstermem için yolunu hazırlamış olur.”"]],51:[["1","Müzik şefi için. Bat-Şeva’nın yanına girdikten sonra Peygamber Natan ona geldiği zaman, David’in mezmuru Ey Tanrım, sevgi dolu iyiliğin uyarınca merhamet et bana. Sevecen merhametinin bolluğuna göre sil isyanlarımı."],["2","Beni suçumdan büsbütün yıka. Beni günahımdan temizle."],["3","Çünkü isyanlarımı biliyorum. Günahım sürekli karşımda."],["4","Sana karşı ve yalnızca sana karşı günah işledim, senin gözünde kötü olanı yaptım, bunun için söylediklerinde haklı, yargılarında adilsin."],["5","İşte, ben suç içinde doğdum. Annem günah içinde bana hamile kaldı."],["6","İşte, sen yürekten gerçeği istiyorsun. Bilgelik öğret bana en derinliklerimde."],["7","Beni mercanköşk otuyla arındır, temiz olayım. Yıka beni, kardan beyaz olayım."],["8","Sevinç ve coşkuyu duyur bana, öyle ki, kırdığın kemikler sevinsin."],["9","Günahlarıma karşı yüzünü ört, bütün suçlarımı sil."],["10","Bende temiz bir yürek yarat, ey Tanrım. İçimdeki doğru ruhu tazele."],["11","Beni huzurundan atma, ve Kutsal Ruhun’u benden alma."],["12","Kurtuluş sevincini bana geri ver. İstekli bir ruhla bana destek ol."],["13","O zaman isyan edenlere senin yollarını öğreteceğim. Günahkârlar sana geri dönecek."],["14","Beni kan dökme suçundan kurtar, ey Tanrı, kurtuluşumun Tanrısı. Dilim senin doğruluğunu yüksek sesle ezgilerle söylesin."],["15","Ey Efendim, dudaklarımı aç. Ağzım senin övgünü ilan etsin."],["16","Çünkü sen kurbandan hoşlanmazsın, yoksa sunardım sana. Yakmalık sunudan zevk almazsın."],["17","Tanrı'nın kurbanları kırık bir ruhtur. Ey Tanrı, sen kırık ve pişman bir yüreği hor görmezsin."],["18","Siyon'a iyi arzunla iyilik et. Yeruşalem’in surlarını yap."],["19","O zaman doğruluk kurbanlarından, yakmalık sunulardan ve tümüyle yakmalık sunulardan zevk alırsın. O zaman sunağında boğalar sunulur."]],52:[["1","Müzik şefi için David’in Maskili Edomlu Doek gelip Saul’a “David Ahimelek’in evine girdi” diye bildirdiği zaman. Neden kötülükle övünürsün, ey zorba? Tanrı’nın sevgi dolu iyiliği kalıcıdır."],["2","Dilin yıkım tasarlar, keskin bir ustura gibi hileyle çalışır."],["3","İyilikten çok kötülüğü, doğruyu konuşmaktan çok yalanı seversin. Selah."],["4","Ey sen aldatıcı dil, yıkıcı her sözü seversin."],["5","Tanrı da seni sonsuza dek yıkacak. Seni alıp çadırından çıkaracak, seni yaşayanlar diyarından kovacak. Selah."],["6","Doğru kişi de bunu görüp korkacak, ve ona gülüp şöyle diyecek:"],["7","“İşte, Tanrı'yı kendine kuvvet edinmeyen, zenginliğinin bolluğuna güvenen, kötülüğünde güçlenen adam budur.”"],["8","Ama ben Tanrı'nın evindeki yeşil zeytin ağacı gibiyim. Sonsuza dek Tanrı'nın sevgi dolu iyiliğine güvenirim."],["9","Yaptıkların için daima sana şükredeceğim. Kutsallarının önünde senin adına umut bağlarım, çünkü adın iyidir."]],53:[["1","Müzik şefi için - Mahalat makamında David’in Maskili Akılsız, yüreğinde “Tanrı yoktur” dedi. Yozlaştılar ve iğrenç şeyler yaptılar. İyilik eden kimse yok."],["2","Anlayan, Tanrı’yı arayan birinin olup olmadığını görmek için, Tanrı gökten insanoğullarına baktı."],["3","Hepsi geri döndü. Birlikte kirlendiler. İyilik eden kimse yok, bir kişi bile."],["4","Kötülük edenlerin bilgisi yok mu? Halkımı ekmek yer gibi yiyor, Tanrı'yı çağırmıyorlar."],["5","Korkunun olmadığı yerde çok korktular. Çünkü Tanrı sana karşı ordugâh kuranın kemiklerini dağıttı. Onları utandırdın, çünkü Tanrı onları reddetti."],["6","Keşke İsrael'in kurtuluşu Siyon'dan gelseydi! Tanrı, halkını sürgünden geri getirince, Yakov sevinecek, İsrael coşacak."]],54:[["1","Müzik şefi için - Telli sazlarla David’in Maskili Zifliler gelip Saul’a: “David aramızda gizleniyor” dedikleri zaman Ey Tanrı, adınla kurtar beni. Gücünle beni haklı çıkar."],["2","Ey Tanrı, duamı duy. Ağzımdan çıkan sözlere kulak ver."],["3","Çünkü yabancılar bana karşı ayaklandı. Zorbalar canımın peşindeler. Tanrı’yı önlerine koymadılar. Selah."],["4","İşte, Tanrı benim yardımcımdır. Canıma destek olan Efendim’dir."],["5","Düşmanlarıma yaptıkları kötülüğün karşılığını verecektir. Onları kendi gerçeğinle yok et."],["6","Sana gönülden kurban sunacağım. Ey Yahve adına şükredeceğim, çünkü adın iyidir."],["7","Çünkü beni her sıkıntıdan kurtardı. Gözüm düşmanlarıma karşı zaferi gördü."]],55:[["1","Müzik şefi için - Telli sazlarla David’in Maskili Ey Tanrı, duamı dinle. Yalvarışımdan kendini saklama."],["2","Dikkatini ver, yanıtla beni. Sıkıntı ve inilti içinde huzursuzum"],["3","düşmanın sesi, kötünün zulmü yüzünden. Çünkü üstüme sıkıntı getiriyorlar. Öfkeyle bana kin besliyorlar."],["4","Yüreğim sızlıyor içimde. Ölüm dehşeti çöktü üzerime."],["5","Üzerime korku ve titreme geldi. Dehşet içimi sardı."],["6","“Keşke güvercin gibi kanatlarım olsaydı!” dedim. Uçup gider, rahatlardım."],["7","İşte, o zaman uzaklara gider, çölde konaklardım. Selah."],["8","“Sert rüzgârdan ve kasırgadan hemen sığınağa koşardım.”"],["9","Akıllarını ve dillerini karıştır, ey Efendim, çünkü kentte şiddet ve çekişme gördüm."],["10","Gece gündüz kent surları üzerinde geziniyorlar. Kötülük ve gaddarlık kentin içindedir."],["11","Yıkıcı güçler onun içindedir. Tehdit ve yalanlar sokaklardan çıkmaz."],["12","Çünkü beni aşağılayan bir düşman değildi, yoksa buna katlanabilirdim. Benden nefret eden de bir hasım değildi, yoksa ondan gizlenirdim."],["13","Ama sendin, benim gibi biri, arkadaşım ve yakın dostum."],["14","Birlikte tatlı tatlı dostluk ederdik. Toplulukla Tanrı'nın evine yürürdük."],["15","Ölüm üzerlerine ansızın gelsin. Diri diri Şeol'e insinler. Çünkü kötülük onların arasında, evlerinin içindedir."],["16","Bense, Tanrı'ya seslenirim. Yahve kurtarır beni."],["17","Akşam, sabah ve öğle vakti sıkıntı içinde feryat ederim. O sesimi duyar."],["18","Bana karşı yapılan savaştan esenlik içinde kurtarır canımı, gerçi bana karşı çıkanlar da çoktur."],["19","Sonsuzluktan beri tahtında oturan Tanrı, işitecek ve onlara karşılık verecektir. Selah. Onlar asla değişmez, Tanrı’dan da korkmazlar."],["20","Dostlarına karşı elini kaldırdı, yaptığı antlaşmayı bozdu."],["21","Ağzı tereyağı gibi sakin, ama yüreği savaşçıdır. Sözleri yağdan yumuşak, ama onlar yalın kılıçtırlar."],["22","Yükünü Yahve’ye bırak, O sana destek olur. Doğrunun sarsılmasına asla izin vermez."],["23","Ama sen, ey Tanrı, Onları yıkım çukuruna indireceksin. Kana susamış ve hilekâr adamlar günlerinin yarısını bile yaşayamayacaklar. Bense sana güvenirim."]],56:[["1","Müzik şefi için “Uzak Yabanıl Fıstık Ağaçlarındaki Güvercin” makamında David’in Miktamı - Gar Kenti’nde Filistliler onu yakaladığı zaman Ey Tanrı merhamet et bana, çünkü insan beni yutmak istiyor. Gün boyu bana saldırıp baskı yapıyor."],["2","Düşmanlarım gün boyu beni yutmak istiyorlar, çünkü bana karşı gururla savaşanlar çoktur."],["3","Korktuğumda, sana güvenirim."],["4","Tanrı’ya, sözünü överim. Tanrı’ya güvenirim, korkmam. İnsan bana ne yapabilir?"],["5","Gün boyu sözlerimi çarpıtıyorlar. Bana karşı bütün düşünceleri kötülük içindir."],["6","Kötülük için anlaşıp pusuya yatıyorlar, adımlarımı izleyip, canımı almaya hevesleniyorlar."],["7","Onlar kötülükle mi kurtulacaklar? Ey Tanrı, öfkeyle halkları yere çal."],["8","Avare avare dolaşmalarımı saydın. Gözyaşlarımı kabına koydun. Onlar senin kitabında değil mi?"],["9","Seslendiğim gün düşmanlarım geri çekilecek. Biliyorum, Tanrı benden yanadır."],["10","Tanrı’ya, sözünü överim. Yahve’ye, sözünü överim."],["11","Tanrı'ya güvenirim, korkmam. İnsan bana ne yapabilir?"],["12","Ey Tanrı, adakların üzerimdedir, sana şükran kurbanları sunacağım."],["13","Çünkü canımı ölümden kurtardın, ayaklarımın kaymasına engel oldun, öyle ki, yaşayanların ışığında Tanrı'nın önünde yürüyeyim."]],57:[["1","Müzik şefi için - “Yok etme” makamında David’in Miktamı Saul’dan kaçıp mağaraya sığındığı zaman Merhamet et bana, ey Tanrı, bana merhamet et, çünkü canım sana sığınıyor. Felaket geçene dek kanatlarının gölgesine sığınacağım."],["2","Yüce Tanrı'ya, benim için isteklerimi yerine getiren Tanrı’ya sesleniyorum."],["3","Gökten gönderip beni kurtaracak, beni kovalayanı azarlayacak. Selah. Tanrı sevgi dolu iyiliğini ve gerçeğini gönderecektir."],["4","Canım aslanların arasında. Yakıcı insanoğulları arasında yatıyorum, dişleri mızrak ve ok, dilleri keskin bir kılıçtır."],["5","Ey Tanrı, göklerin üstünde yücel! Yüceliğin tüm yeryüzünü kaplasın!"],["6","Adımlarıma ağ kurdular. Canım çöktü. Önüme çukur kazdılar. İçine kendileri düştüler. Selah."],["7","Yüreğim değişmez, ey Tanrı. Yüreğim değişmez. Ezgiler, ilahiler söyleyeceğim."],["8","Uyan, ey görkemim! Uyan, ey ut ve arp! Şafağı ben uyandırayım."],["9","Halkların arasında sana şükredeceğim ey Efendim. Uluslar arasında seni ilahilerle öveceğim."],["10","Çünkü senin muazzam sevgi dolu iyiliğin göklere, gerçeğin gökyüzüne ulaşır."],["11","Ey Tanrı, göklerin üstünde yücel! Yüceliğin tüm yeryüzünü kaplasın!"]],58:[["1","Müzik şefi için - “Yok Etme” makamında David’in Miktamı Ey siz susanlar, gerçekten doğrulukla mı konuşursunuz? Ey insanoğulları, kusursuzca mı yargılarsınız?"],["2","Hayır, yüreğinizde haksızlık tasarlarsınız. Yeryüzünü ellerinizin zorbalığıyla ölçersiniz."],["3","Kötüler ana rahmindeyken yoldan saparlar. Doğdukları andan itibaren dik başlıdırlar, yalan söylerler."],["4","Onların zehiri yılanın zehiri gibidir, kulağını tıkayan sağır bir kobraya benzerler,"],["5","büyücülerin sesine kulak vermez, büyücü ne kadar hünerli olursa olsun."],["6","Ey Tanrı, kır onların ağızlarındaki dişleri. Sök genç aslanların azı dişlerini, ey Yahve."],["7","Akıp giden su gibi yok olup gitsinler. Yaylarını gerdiklerinde oklarının ucu kırılsın."],["8","Eriyip giden salyangoz gibi, güneşi görmeyen düşük çocuk gibi olsunlar."],["9","Kazanlarınız diken ateşini daha duymadan, yeşili de, tutuşmuş olanı da süpürüp atacaktır."],["10","Doğru kişi alınan öcü görünce sevinecek. Ayaklarını kötünün kanıyla yıkayacak,"],["11","o zaman insanlar şöyle diyecekler: “Kuşkusuz doğruların ödülü var. Kuşkusuz yeryüzünü yargılayan bir Tanrı var.”"]],59:[["1","Müzik şefi için - “Yok Etme” makamında David’in Miktamı - Saul’un David’i öldürtmek için adam gönderip evini gözetlediği zaman Kurtar beni düşmanlarımdan, ey Tanrım. Bana karşı ayaklananlardan beni yükseğe çıkar."],["2","Kurtar beni kötülüğün işçilerinden. Kurtar beni kana susamış insanlardan."],["3","Çünkü işte, canım için pusuya yatmış bekliyorlar. Güçlüler bana karşı toplanıyorlar, itaatsizliğim ya da günahımdan dolayı değil, ey Yahve."],["4","Suç işlemediğim halde bana saldırmaya hazırlanıyorlar. Bana yardım etmek için kalk ve bak!"],["5","Sen, Ordular Tanrısı Yahve, İsrael'in Tanrısı, ulusları cezalandırmak için uyan. Bu kötü hainlere merhamet gösterme. Selah."],["6","Akşamleyin köpekler gibi uluyarak geri dönerler, kentte dolaşırlar."],["7","İşte, ağızlarıyla kusuyorlar. Dudaklarında kılıç var, “Bizi kim duyacak ki?” diyorlar."],["8","Ama sen, ey Yahve, onlara gülersin. Bütün uluslarla eğlenirsin."],["9","Ey Gücüm, sana bakıyorum, çünkü Tanrı benim yüksek kulemdir."],["10","Tanrım sevgi dolu iyiliğiyle önümde yürüyecek. Tanrı düşmanlarıma zaferle bakmamı sağlayacak."],["11","Öldürme onları, yoksa halkım unutur. Gücünle onları dağıt ve alaşağı et, ey kalkanımız olan Efendi."],["12","Ağızlarının günahı ve dudaklarının sözleri için, ettikleri lanetler ve söyledikleri yalanlar için, kibirleri onları yakalasın."],["13","Öfkeyle tüket onları. Tüket onları, yok olsunlar. Bilsinler ki, yeryüzünün sonlarına kadar Yakov’da hüküm süren Tanrı’dır. Selah."],["14","Akşam dönsünler. Köpek gibi ulusunlar, kentte dolaşsınlar."],["15","Yiyecek bulmak için bir aşağı bir yukarı gezinsinler, doymazlarsa bütün gece bekleyecekler."],["16","Bense gücüne ezgiler söyleyeceğim. Evet, sabahları sevgi dolu iyiliğini yüksek sesle ezgiyle dile getireceğim. Çünkü sen benim yüksek kulem, sıkıntılı günümde sığınağım oldun."],["17","Seni ilahilerle öveceğim, ey gücüm. Çünkü Tanrı benim yüksek kulemdir, merhametimin Tanrısı’dır."]],60:[["1","Müzik şefi için - “Antlaşma Zambağı” makamında David’in öğretici Miktamı David’in Aram-Naharayimliler ve Aram-Sovalılar’la çarpıştığı ve Yoav geri dönüp Tuz Vadisi’nde on iki bin Edomlu öldürdüğü zaman Ey Tanrı, bizi reddettin ve yıktın. Öfkelendin, bizi eski halimize döndür."],["2","Ülkeyi salladın, yarıklar açtın çatlaklarını düzle, çünkü yer sarsılıyor."],["3","Halkına zor şeyler gösterdin. Bize sersemleten şarabı içirdin."],["4","Gerçek uğruna sergilensin diye, senden korkanlara sancak verdin. Selah."],["5","Sevdiklerin kurtulsun diye, sağ elinle kurtar ve yanıt ver bize."],["6","Tanrı kutsal yerinden şöyle konuştu: “Zafer kazanacağım. Şekem'i böleceğim, Sukkot Vadisi’ni ölçeceğim."],["7","Gilad benimdir, Manaşşe de benim. Efraim de başımın siperi, Yahuda asamdır."],["8","Moav yıkanma leğenimdir. Edom'un üzerine çarığımı atacağım. Filist üzerine zaferle haykıracağım.”"],["9","Kim beni surlu kente götürecek? Bana kim Edom'a kadar yol gösterecek?"],["10","Ey Tanrı, sen bizi reddetmedin mi? Ordularımızla yola çıkmıyorsun, ey Tanrı."],["11","Düşmana karşı bize yardım et, çünkü insanın yardımı boştur."],["12","Tanrı’yla yiğitlik ederiz, çünkü düşmanlarımızı ezecek olan O’dur."]],61:[["1","Müzik şefi için - Telli sazlarla - David’in mezmuru Ey Tanrı, feryadımı duy, duamı dinle."],["2","Yüreğim bunaldığında sana seslenirim yeryüzünün öbür ucundan. Beni benden daha yüksek olan kayaya götür."],["3","Çünkü sen bana sığınak, düşmana karşı güçlü bir kule oldun."],["4","Sonsuza dek çadırında kalayım. Kanatlarının koruması altına sığınayım. Selah."],["5","Çünkü sen, ey Tanrı, adaklarımı duydun. Adından korkanların mirasını bana verdin."],["6","Kralın ömrünü uzat. Onun yılları kuşaklar boyunca sürsün,"],["7","sonsuza dek Tanrı'nın huzurunda tahta otursun. Sevgi dolu iyiliğini ve gerçeğini sapta ki, onu korusunlar."],["8","Böylece daima ismine ilahiler söyleyeceğim, ta ki, adaklarımı her gün yerine getirebileyim."]],62:[["1","Müzik şefi Yedutun için - David’in mezmuru Canım yalnız Tanrı'da dinlenir. Kurtuluşum O’ndandır."],["2","Kayam, kurtuluşum ve kalem yalnız O’dur. Asla şiddetli sarsılmam."],["3","Eğik bir duvar, sallanan bir çit gibi, ne vakte kadar, hepiniz bir adamı ezmek için, ona saldıracaksınız?"],["4","Bütün düşünceleri onu bulunduğu yücelikten aşağıya atmaktır. Yalanlardan zevk alırlar. Ağızlarıyla kutsarken, içlerinden lanet okurlar. Selah."],["5","Ey canım, sessizce yalnız Tanrı’yı bekle, çünkü umudum O’ndandır."],["6","Kayam, kurtuluşum ve kalem yalnız O’dur. Sarsılmam."],["7","Kurtuluşum ve onurum Tanrı'yladır. Gücümün kayası ve sığınağım Tanrı'dadır."],["8","Ey halkım, O'na her zaman güven. Yüreğini O’nun önünde dök. Tanrı bizim için bir sığınaktır. Selah."],["9","Kesinlikle aşağı tabakadaki insanlar yalnızca bir soluktur; yukarı tabakadaki insanlar da bir yalan. Onlar tartıda kaldırıldıklarında, birlikte soluktan daha hafiftir."],["10","Gaddarlığa güvenmeyin. Soygunculukla övünmeyin. Zenginlik artarsa, ona gönül bağlamayın."],["11","Tanrı bir kez konuştu; Ben şunu iki kez işittim: Güç Tanrı’ya aittir."],["12","Sevgi dolu iyilik de sana aittir, ey Efendim, çünkü sen herkesi yaptığı işe göre ödüllendirirsin."]],63:[["1","Yahuda kırlarında bulunduğu zaman - David’in mezmuru Ey Tanrım, sensin benim Tanrım. Gayretle seni arıyorum. Canım sana susamış. Bedenim seni özlüyor, kurak, yorucu, susuz bir diyarda."],["2","Kutsal yerde sana baktım, gücünü ve görkemini görmek için."],["3","Dudaklarım seni över, çünkü senin sevgi dolu iyiliğin hayattan daha iyidir."],["4","Yaşadığım sürece seni böyle yücelteceğim. Senin adınla ellerimi kaldıracağım."],["5","Canım zengin yiyeceklere doyar gibi doyacak. Ağzım neşeli dudaklarla seni övecek."],["6","Seni yatağımda hatırladığımda, gece nöbetlerinde seni düşünürüm."],["7","Çünkü sen bana yardımcı oldun. Kanatlarının gölgesinde sevineceğim."],["8","Canım sana yakın durur. Sağ elin bana destek olur."],["9","Ama yok etmek için canımı arayanlar, yerin diplerine inecekler."],["10","Onlar kılıcın gücüne teslim edilecekler. Çakallara yem olacaklar."],["11","Ama kral Tanrı’yla sevinecek. O’nunla ant içenlerin hepsi O'nu övecekler, yalan söyleyenlerin ağızlarıysa susturulacak."]],64:[["1","Müzik şefi için - David’in mezmuru Yakındığımda sesimi duy, ey Tanrı. Hayatımı düşman korkusundan koru."],["2","Kötülerin gizli tasarılarından, fesat işleyenlerin gürültücü kalabalığından sakla beni."],["3","Dillerini kılıç gibi keskinleştiren, ölümcül sözlerle oklarını kuran,"],["4","masum insanları vurmak için pusuda yatan onlardır. Ansızın onu vururlar hiç korkmadan."],["5","Kötü tasarılar için birbirlerini teşvik ederler. Gizlice tuzak kurmaktan söz ederler. “Onları kim görecek ki?” derler."],["6","“Kusursuz bir plan yaptık!” deyip, adaletsizlik için düzen kurarlar. Besbelli insanın aklı ve yüreği kurnazdır."],["7","Ama Tanrı onlara ok atacaktır. Ansızın bir okla vurulacaklar."],["8","Kendi dilleri onları yıkıma uğratacak. Onları gören herkes başını sallayacak."],["9","Bütün insanlar korkacak. Tanrı’nın işini ilan edecekler, O’nun yaptıklarını bilgece ölçüp tartacaklar."],["10","Doğru kişi Yahve'de sevinecek, O’na sığınacaktır. Yüreği doğru olanların hepsi O'nu övecekler!"]],65:[["1","Müzik şefi için - David’in mezmuru - İlahi Ey Tanrı, Siyon'da seni övgü bekliyor. Adaklar yerine getirilecek."],["2","Ey Sen duayı işiten, bütün insanlar Sana gelecek."],["3","Günahlar beni bunalttı, ama Sen suçlarımızın kefaretini ödedin."],["4","Ne mutlu, avlularında otursun diye seçip yaklaştırdığın insana. Evinin, kutsal tapınağının iyiliğiyle doyacağız."],["5","Müthiş doğruluk işleriyle bizi yanıtlarsın. Ey kurtuluşumuzun Tanrısı. Ey Sen, dünyanın bütün uçlarının, uzak denizde bulunanların umudusun."],["6","Güçle kuşanmış olarak, kuvvetinle dağlara biçim veren,"],["7","denizlerin kükremesini, dalgalarının uğultusunu, ve ulusların kargaşasını yatıştıran sensin."],["8","Uzaklarda oturanlar da senin harikalarından korkarlar. Sabahın şafağını ve akşamı sevinç ezgileriyle çağırırsın."],["9","Yeryüzünü ziyaret edip onu sularsın. Onu çok zenginleştirirsin. Tanrı’nın nehri suyla doludur. Onlara tahıl sağlarsın, çünkü bunu sen buyurdun."],["10","Saban yarıklarını bolca sular, sırtlarını düzeltirsin. Yağmurlar yumuşatır, onu mahsulle kutsarsın."],["11","Yılı bolluğunla taçlandırırsın. Arabaların bereketle dolup taşar."],["12","Çöller yeşillikle taşar. Tepeler neşeyle bürünür."],["13","Otlaklar sürülerle kaplanır. Vadiler de buğdayla örtünür. Sevinçle bağrışır, ezgi söylerler."]],66:[["1","Müzik şefi için - İlahi - Mezmur Ey bütün yeryüzü, Tanrı’ya sevinçle haykırın!"],["2","Adının yüceliğine ilahi söyleyin! Görkem ve övgü sunun!"],["3","“İşlerin ne muhteşemdir!” deyin Tanrı’ya, “Gücünün büyüklüğünden düşmanların önünde boyun eğiyor."],["4","Bütün yeryüzü sana tapınacak, sana ilahi söyleyip adına ezgiler söyleyecekler.” Selah."],["5","Gelin ve Tanrı'nın yaptıklarını görün— insanlar adına muhteşem bir yapıt."],["6","Denizi kuru toprağa çevirdi. Onlar ırmağı yürüyerek geçtiler. Orada O’nda sevindik."],["7","O, kudretiyle sonsuza dek hüküm sürer. Gözleri ulusları gözler. Asiler O’na karşı baş kaldırmasın. Selah."],["8","Ey halklar, Tanrımız’ı övün! Övgüsünün sesini duyurun,"],["9","Diriler arasında hayatımızı koruyan, ayaklarımızın kaymasına izin vermeyen O’dur."],["10","Sen bizi sınadın, ey Tanrı. Gümüş arıtır gibi, arıttın bizi."],["11","Bizi zindana verdin. Sırtımıza yük koydun."],["12","İnsanların başımıza çıkmasına izin verdin. Ateşin ve suyun içinden geçtik, ama bizi bolluğun bulunduğu yere getirdin."],["13","Yakmalık sunularla tapınağına geleceğim."],["14","Sıkıntıdayken ağzımın söylemiş olduğu, dudaklarımın sana vaat ettiği adaklarımı yerine getireceğim."],["15","Sana yakmalık sunu olarak semiz hayvanlar sunacağım, koçlarla birlikte, boğalar, keçiler sunacağım. Selah."],["16","Ey Tanrı'dan korkanlar, gelin ve dinleyin. Canım için neler yapmış olduğunu bildireyim."],["17","Ağzımla O’na yakardım. Dilimle O övüldü."],["18","Günaha yüreğimde yer verseydim, Efendi dinlemezdi."],["19","Ama kesinlikle, Tanrı dinledi. Duamın sesini işitti."],["20","Duamı geri çevirmeyen, sevgi dolu iyiliğini benden esirgemeyen Tanrı'ya övgüler olsun!"]],67:[["1","Müzik şefi için - Telli sazlarla - Mezmur - İlahi Tanrı bize merhamet etsin ve bizi kutsasın, yüzüyle üzerimize ışık saçtırsın. Selah."],["2","Öyle ki, yeryüzünde yolun, bütün uluslar arasındaki kurtuluşun bilinsin."],["3","Halklar seni övsün, ey Tanrı. Bütün halklar seni övsün."],["4","Uluslar sevinsin, sevinçle ezgi söylesin, çünkü halkları adaletle yargılarsın, yeryüzündeki uluslara hükmedersin. Selah."],["5","Halklar seni övsün, ey Tanrı. Bütün halklar seni övsün."],["6","Yeryüzü mahsulünü verdi. Tanrı, bizim Tanrımız, bizi kutsasın."],["7","Tanrı bizi kutsasın. Bütün dünya uçları O’ndan korksun."]],68:[["1","Müzik şefi için - David’in mezmuru- İlahi Tanrı kalksın! Düşmanları dağılsın! O’ndan nefret edenler önünden kaçsınlar."],["2","Dumanın dağıldığı gibi, onları öyle dağıt. Ateşin önünde eriyen balmumu gibi, kötüler Tanrı'nın önünde öyle yok olsun."],["3","Ama doğrular sevinsin. Tanrı'nın önünde coşsunlar. Evet, neşeyle coşsunlar."],["4","Tanrı'ya ilahi söyleyin! O’nun adına ezgiler söyleyin! Bulutlar üzerine binmiş olanı yüceltin: Yah’dır, O’nun adı! O’nun önünde coşun!"],["5","Kutsal konutundaki Tanrı, yetimin babası ve dul kadınların savunucusudur."],["6","Tanrı yalnızlara aile kurar. Tutsakları ezgi söyleyerek dışarı çıkarır, ama isyan edenler güneşin kavurduğu ülkede yaşar."],["7","Ey Tanrı, halkının önüne çıktığında, çölde yürüdüğünde... Selah."],["8","Yer sarsıldı, ve Sina Tanrısı’nın önünde gökten yağmur yağdı, Tanrı’nın, İsrael’in Tanrısı önünde."],["9","Sen, ey Tanrı, bol yağmur gönderdin. Yorulduğu zaman mirasına kuvvet verdin."],["10","Topluluğun orada yaşadı. Sen, ey Tanrı, iyiliğini yoksullar için hazırladın."],["11","Efendi sözünü duyurdu. Bunu ilan edenler büyük bir topluluktu."],["12","“Orduların kralları kaçıyor! Kaçıyorlar!” Evde bekleyen kadın ganimeti bölüştürür,"],["13","sen kamp ateşinin arasında uyurken, tüyleri altın renkli, kanatları gümüşle kaplanmış bir güvercin gibi parlarsın."],["14","Her Şeye Gücü Yeten orada kralları dağıttığında, Salmon'a kar yağdı."],["15","Başan Dağları heybetli dağlardır. Başan Dağları sarptır."],["16","Ey sarp dağlar, neden kıskançlıkla bakıyorsunuz? Tanrı'nın hüküm sürmek için seçtiği dağa? Evet, Yahve sonsuza dek orada oturacak."],["17","Tanrı'nın savaş arabaları on binlerce, binlerce bindir. Efendi, Sina Dağı'ndan kutsal yere kadar onların ortasındadır."],["18","Yükseğe çıktın. Tutsakları götürdün. İnsanlardan, isyan edenlerden bile armağanlar aldın, oraya yerleşmek için ey Yah Tanrı."],["19","Her gün yüklerimizi taşıyan Efendi’ye, kurtuluşumuz olan Tanrı’ya övgüler olsun. Selah."],["20","Tanrı bizim için kurtuluş Tanrısı’dır. Ölümden kurtarış, Efendi Yahve’ye aittir."],["21","Ama Tanrı düşmanlarının başını, suçunda ısrar edenin kıllı kafasını ezer."],["22","Efendi şöyle dedi: “Seni Başan'dan geri getireceğim. Seni yeniden denizin derinliklerinden geri getireceğim,"],["23","öyle ki, ayağını kana batırıp onları ezesin, köpeklerinin dili de senin düşmanlarından payını alsın.”"],["24","Ey Tanrı, senin alaylarını Tanrım’ın, Kralım'ın kutsal yere doğru alaylarını gördüler."],["25","Tef çalan kızlar arasında, önde okuyucular, arkada çalgıcılar yürüdü."],["26","“Topluluklarda Tanrı'yı, İsrael topluluğunda Efendi’yi övün!”"],["27","Onların hükümdarı küçük Benyamin, Yahuda beyleri ve topluluğu, Zevulun beyleri ve Naftali beyleri oradadırlar."],["28","Senin gücünü Tanrı buyurdu. Bizim için yaptıklarını güçlendir, ey Tanrı."],["29","Yeruşalem'deki tapınağın uğruna, krallar sana hediyeler getirecek."],["30","Azarla kamışlar arasında yaşayan vahşi hayvanı, halkların buzağılarını ve boğalar sürüsünü. Gümüş külçe getirenleri alçalt, savaştan zevk alan ulusları dağıt."],["31","Mısır'dan beyler gelecek. Etiyopya ellerini Tanrı'ya uzatmak için acele edecek."],["32","Ey yeryüzünün krallıkları, Tanrı'ya ezgi söyleyin! Efendi’ye ilahiler söyleyin—Selah—"],["33","kadim göklerin göğü üstüne binmiş olana. İşte, sesini ortaya koyuyor, heybetli sesini."],["34","Gücü Tanrı'ya atfedin! O’nun yüceliği İsrael'in üzerindedir, gücü göklerdedir."],["35","Kutsal yerlerinde muhteşemsin, ey Tanrı. İsrael'in Tanrısı halkına güç ve kudret verir. Övgüler olsun Tanrı’ya!"]],69:[["1","Müzik şefi için - “Zambaklar” makamında - David’in mezmuru Kurtar beni ey Tanrı, çünkü sular boynuma kadar geldi!"],["2","Ayak basılacak yerin olmadığı derin bataklığa batmaktayım. Sellerin beni aştığı derin sulara geldim."],["3","Ağlamaktan yoruldum. Boğazım kurudu. Gözlerim Tanrı’yı aramayı bırakıyor."],["4","Nedensiz yere benden nefret edenler başımın saçından çoktur. Beni yok etmek isteyen haksız düşmanlarım güçlüdür. Almadığım şeyi geri vermem gerekiyor."],["5","Ey Tanrı, akılsızlığımı biliyorsun. Günahlarım senden gizli değil."],["6","Seni bekleyenler benim yüzümden utanmasın, ey Orduların Efendisi Yahve. Ey İsrael'in Tanrısı benim yüzümden seni arayanlar rezil olmasın."],["7","Çünkü senin uğruna aşağılanmaya katlandım. Utanç yüzümü kapladı."],["8","Kardeşlerime yabancı, annemin çocuklarına el oldum."],["9","Çünkü senin evinin gayreti beni tüketti. Sana edilen hakaretler benim üzerime düştü."],["10","Ağlayıp oruç tuttuğumda, bu da bana ayıp sayıldı."],["11","Giysimi çul yaptığımda, onlar için bir masal oldum."],["12","Kent kapısında oturanlar hakkımda konuşuyorlar. Sarhoşların şarkısı oldum."],["13","Bense ey Yahve, uygun zamanda duam sanadır. Ey Tanrı, sevgi dolu iyiliğinin bolluğuyla, kurtarışının gerçeğiyle yanıtla beni."],["14","Beni çamurdan kurtar, batmayayım. Benden nefret edenlerden ve derin sulardan kurtulayım."],["15","Sel suları beni boğmasın, derinlik beni yutmasın, çukur üzerime ağzını kapamasın."],["16","Yanıtla beni, ey Yahve, çünkü sevgi dolu iyiliğin iyidir. Sevecen merhametlerinin bolluğuna göre bana yönel."],["17","Yüzünü hizmetkârından gizleme, çünkü sıkıntıdayım. Bana tez yanıt ver!"],["18","Canıma yaklaş ve onu kurtar. Düşmanlarımdan ötürü beni fidyeyle kurtar."],["19","Bana edilen hakareti, utancı, rezaleti bilirsin. Düşmanlarımın hepsi senin önündedir."],["20","Aşağılanma kalbimi kırdı ve içim ağırlaştı. Acıyacak birilerini aradım ama yoktu, teselli edecek kimseyi bulamadım."],["21","Yiyecek için bana zehir verdiler. Susadığımda içmem için bana sirke verdiler."],["22","Önlerindeki sofra tuzak olsun, bu onlara ceza ve kapan olsun."],["23","Gözleri kararsın ki göremesinler. Sırtları hep bükük olsun."],["24","Gazabını üzerlerine dök. Öfkenin şiddeti onlara yetişsin."],["25","Yaşadıkları yer ıssız olsun. Çadırında oturan olmasın."],["26","Çünkü yaraladığın insana zulmediyorlar. Yaraladığın insanın acısını anlatıyorlar."],["27","Onların cezalarına ceza kat. Senin doğruluğuna girmelerine izin verme."],["28","Onlar hayat kitabından silinsinler, doğrularla birlikte yazılmasınlar."],["29","Bense acı ve sıkıntı içindeyim. Senin kurtarışın, ey Tanrı, beni korusun."],["30","Tanrı'nın adını bir ezgiyle öveceğim, O’nu şükranla yücelteceğim."],["31","Yahve’yi bir öküzden, boynuzlu, tırnaklı bir boğadan daha çok memnun eder bu."],["32","Alçakgönüllüler bunu gördü ve sevindi. ey Tanrı'yı arayan sizler, yüreğiniz yaşasın."],["33","Çünkü Yahve yoksulu duyar, kendi tutsak halkını hor görmez."],["34","Gök ve yeryüzü, denizler ve içinde kımıldayan her şey O’nu övsün!"],["35","Çünkü Tanrı Siyon'u kurtaracak, Yahuda kentlerini yeniden inşa edecek. Onlar oraya yerleşip mülk edinecekler."],["36","Hizmetkârının çocukları da onu miras alacaklar. O’nun adını sevenler orada oturacaklar."]],70:[["1","Müzik şefi için - Anma sunusu için - David’in mezmuru Ey Tanrı, beni kurtarmak için acele et. Yardımıma koş, ey Yahve."],["2","Canımı arayanlar hayal kırıklığına uğrayıp şaşkına dönsünler. Mahvolmamı isteyenler rezil olup geri dönsünler."],["3","Bana “Oh! Oh!” diyenler utançlarından geri dönsünler."],["4","Bütün seni arayanlar sende sevinip coşsunlar. Senin kurtarışını sevenler sürekli, “Tanrı yücelsin!” desinler."],["5","Bense yoksul ve muhtacım. Tez bana gel, ey Tanrı. Sensin benim yardımcım ve kurtarıcım. Geç kalma ey Yahve."]],71:[["1","Sana sığınıyorum, ey Yahve. Hayal kırıklığına uğratma beni hiçbir zaman."],["2","Beni kendi doğruluğunla kurtar, bana yardım et. Kulak ver bana ve beni kurtar."],["3","Her zaman gidebileceğim sığınacak kayam ol. Kurtulmam için buyruk ver, çünkü kayam ve kalem sensin benim."],["4","Ey Tanrı, kurtar beni, kötünün, haksızın, zalimin elinden."],["5","Çünkü benim umudum, gençliğimden beri güvendiğim sensin, ey Efendi Yahve."],["6","Ana rahminden beri sana güvendim. Beni ana rahminden çıkaran sensin. Seni hep öveceğim."],["7","Birçokları için şaşılacak biriyim, ama sen benim güçlü sığınağımsın."],["8","Ağzım senin övgünle, gün boyu senin yüceliğinle dolu olacak."],["9","Yaşlılığımda beni reddetme. Gücüm tükendiğinde beni bırakma."],["10","Çünkü düşmanlarım hakkımda konuşuyor. Canımı gözleyenler birlikte düzen kuruyorlar."],["11","“Tanrı onu terk etti” diyorlar. “Peşine düşün de yakalayın, çünkü onu kurtaracak kimse yok.”"],["12","Ey Tanrı, benden uzak durma. Tanrım, yardımıma koş."],["13","Beni suçlayanlar hayal kırıklığıyla yok olsunlar. Bana zarar vermek isteyenleri, rezillik ve utanç kaplasın."],["14","Ama ben hep umut ederim, övgülerine övgü eklerim."],["15","Ağzım senin doğruluğunu, tam ölçüsünü bilmesem de, tüm gün senin kurtuluşundan söz edecek."],["16","Efendi Yahve’nin büyük işleriyle geleceğim. Senin doğruluğundan, yalnızca senin doğruluğundan söz edeceğim."],["17","Ey Tanrı, gençliğimden beri bana öğrettin. Şimdiye dek şaşılası işlerini ilan ettim."],["18","Evet, yaşlanıp saçlarıma ak düşse de, ey Tanrı gücünü gelecek kuşağa, büyüklüğünü gelecek olanların hepsine bildirene dek, beni bırakma,"],["19","Ey Tanrı, doğruluğun göklere erişiyor. Büyük işler yaptın. Senin gibisi var mı, ey Tanrı?"],["20","Sen ki, bize çok acı dertler gösterdin, beni yaşatacak, yerin derinliklerinden bizi yeniden çıkaracaksın."],["21","Saygınlığımı artır, beni yeniden rahatlat."],["22","Ben de seni sadakatinden ötürü seni arpla öveceğim, ey Tanrım. Lirle sana ilahiler söyleyeceğim, ey İsrael'in Kutsalı."],["23","Dudaklarım sevinçle haykıracak! Kurtarmış olduğun canım seni ezgilerle övecek!"],["24","Dilim de bütün gün senin doğruluğundan söz edecek, çünkü bana zarar vermek isteyenler, hayal kırıklığına uğrayıp kahroldular."]],72:[["1","Solomon’un mezmuru Ey Tanrı, adaletini krala, doğruluğunu kral oğluna ver."],["2","Halkını doğrulukla, yoksullarını adaletle yargılasın."],["3","Dağlar halka bolluk getirsin. Tepeler doğruluğun meyvesini versin."],["4","Halkının yoksullarına hakkını versin. Muhtaçların çocuklarını kurtarsın, zalimi parçalasın."],["5","Güneş ve ay durdukça, tüm nesiller boyunca senden korksunlar."],["6","Yeni biçilmiş çayıra düşen yağmur gibi, toprağı sulayan bol yağmurlar gibi olsun."],["7","Onun günlerinde doğrular serpilip gelişsin, ay yok olana dek esenlik çoğalsın."],["8","Denizden denize, ırmak'tan dünyanın sonlarına dek hüküm sürsün."],["9","Çölde yaşayanlar önünde eğilsin. Düşmanları toz yalasın,"],["10","Tarşiş ve ada kralları ona haraç getirsin. Saba ve Seva kralları armağanlar sunsun."],["11","Bütün krallar önünde yere kapansın. Bütün uluslar ona hizmet etsin."],["12","Çünkü yardım için haykıran muhtacı, destekçisi olmayan yoksulu kurtarır."],["13","Yoksula ve muhtaca merhamet eder. Muhtaçların canlarını kurtarır."],["14","Canlarını baskı ve şiddetten kurtarır. Gözünde onların kanı değerlidir."],["15","Onlar yaşasınlar ve ona Saba altınından verilsin. Onun için sürekli dua etsinler. Bütün gün onu kutsasınlar."],["16","Ülkenin her yerinde tahıl bolluğu olsun. Meyvesi Lübnan gibi dalgalansın. Toprağın çayırı gibi serpilip gelişsin."],["17","Adı sonsuza dek dursun. Güneş durdukça adı dursun. İnsanlar onun tarafından kutsansın. Bütün uluslar ona kutsanmış desinler."],["18","İsrael'in Tanrısı, Yahve Tanrı'ya övgüler olsun. Şaşılacak işler yapan yalnızca O’dur."],["19","O'nun yüce adına sonsuza dek övgüler olsun! Bütün yeryüzü O’nun yüceliğiyle dolsun! Amin ve amin."],["20","Böylece Yişay oğlu David'in duası sona erer."]],73:[["1","Asaf’ın mezmuru Tanrı kesinlikle İsrael’e, yüreği temiz olanlara karşı iyidir."],["2","Ama benim ayaklarım neredeyse tükenmişti. Adımlarım az kalsın kaymıştı."],["3","Çünkü kötülerin bolluk içinde olduğunu görünce, kibirlileri kıskandım."],["4","Çünkü ölümlerinde çırpınma yoktur, güçleri sağlamdır."],["5","İnsan yüklerinden özgürdürler, öteki insanlar gibi dertli de değiller."],["6","Bu nedenle gurur onların boynundaki zincir gibi, şiddet onları saran bir giysi gibidir."],["7","Gözleri şişmanlıktan dışarı fırlamış, akılları kibrin sınırlarını aşmıştır."],["8","Alay ederler ve kötü niyetle konuşurlar. Kibirle, baskıyla tehdit ederler."],["9","Ağızlarını göklere çevirdiler. Dilleri yeryüzünde dolaşır."],["10","Bu nedenle onların halkları onlara geri döner, bolluk sularından içerler."],["11","Onlar, “Tanrı nereden biliyor?” derler. “Yüceler Yücesi'nde bilgi var mı?”"],["12","İşte, kötüler bunlardır. Daima rahatlar ve zenginliklerini artırırlar."],["13","Gerçekten yüreğimi boşuna temizlemişim, ellerimi masumiyetle yıkamışım,"],["14","gün boyunca sıkıntı çektim, her sabah cezalandırıldım."],["15","Eğer “Ben böyle konuşayım” deseydim, işte, senin çocuklarının nesline ihanet etmiş olurdum."],["16","Bunu anlamaya çalıştığımda, bana çok acı verdi,"],["17","ta ki, Tanrı’nın tapınağına girip, onların sonunu anlayana kadar."],["18","Gerçekten onları kaygan yerlere koyarsın. Onları yıkıma atarsın."],["19","Nasıl da ansızın yok oluyorlar! Dehşet içinde büsbütün süpürülüp atıldılar."],["20","Uyanınca görülen bir rüya gibi, sen de ey Efendi, uyanınca onların hayallerini hor göreceksin."],["21","Çünkü canım acı çekiyordu. Yüreğim buruktu."],["22","Bense o denli akılsız ve bilgisiz, önünde vahşi bir hayvan gibiydim."],["23","Ama yine de sürekli seninleyim. Sağ elimden tuttun."],["24","Öğüdünle bana yol gösterirsin, sonunda beni yüceliğe alırsın."],["25","Gökte kimim var? Yeryüzünde senden başkasını istemem."],["26","Bedenim ve yüreğim tükeniyor, ama Tanrı yüreğimin gücü, sonsuza dek bana düşen paydır."],["27","Çünkü işte, senden uzak olanlar yok olur. Sana sadakatsiz olanların hepsini yok ettin."],["28","Ama Tanrı'ya yaklaşmak benim için iyidir. Senin bütün işlerini bildireyim diye, Efendi Yahve’yi kendime sığınak yaptım."]],74:[["1","Asaf’ın Maskili Ey Tanrı, neden bizi sonsuza dek reddettin? Otlağının koyunlarına karşı öfken neden için için yanıyor?"],["2","Eskiden satın aldığın topluluğunu, mirasın olmak üzere kurtardığın oymağı, üzerinde yaşadığın Siyon Dağı’nı hatırla."],["3","Ayaklarını sonsuz yıkıntılara doğru kaldır, düşman kutsal yerde her kötülüğü etti."],["4","Düşmanların senin toplantı yerinin ortasında kükrüyor. İşaret olarak kendi bayraklarını diktiler."],["5","Gür bir ormanı kesen baltalı adamlar gibi davrandılar."],["6","Şimdi onun bütün oyma işlerini balta ve çekiçlerle kırıyorlar."],["7","Tapınağını yakıp yıktılar. Adını taşıyan konutu kirlettiler."],["8","Yüreklerinde, “Onları tamamen ezeceğiz” dediler. Ülkede Tanrı'ya tapınılan her yeri yaktılar."],["9","Hiçbir mucizevi belirti görmüyoruz. Artık peygamber yok, içimizde ne kadar süreceğini bilen de yok."],["10","Düşman ne zamana dek azarlayacak, ey Tanrı? Düşman sonsuza dek mi senin ismine sövecek?"],["11","Elini, sağ elini niçin geri çekiyorsun? Onu göğsünden çıkar ve onları yakıp kül et!"],["12","Ama Tanrı eski zamanlardan beri Kralım’dır, tüm yeryüzünde kurtuluş sağlar."],["13","Gücünle denizi yardın. Sulardaki deniz canavarlarının kafasını kırdın."],["14","Sen Livyatan'ın başlarını parçaladın. Onu yiyecek olarak insanlara ve çöl canlılarına verdin."],["15","Sen pınarı ve kaynağı fışkırttın. Güçlü ırmakları kuruttun."],["16","Gündüz senindir, gece de senin. Işığı ve güneşi sen hazırladın."],["17","Yeryüzünün bütün sınırlarını sen belirledin. Yazı ve kışı yaratan sensin."],["18","Düşmanın seninle alay ettiğini unutma, ey Yahve. Akılsız bir halk senin adına küfretti."],["19","Kendi kumrunun canını canavarlara teslim etme. Yoksullarının hayatını sonsuza dek unutma."],["20","Antlaşmanı say, çünkü yeryüzünün karanlık yerleri zorbalık inleriyle dolmuş."],["21","Ezilen utanç içinde geri dönmesin. Yoksul ve muhtaçlar senin adını yüceltsinler."],["22","Kalk, ey Tanrı! Kendi davanı savun. Akılsızın bütün gün seninle nasıl alay ettiğini hatırla."],["23","Düşmanlarının sesini unutma. Sana karşı ayaklananların patırtısı sürekli yükseliyor."]],75:[["1","Müzik şefi için - “Yok Etme” makamında - Asaf’ın mezmuru - İlahi Sana şükrederiz ey Tanrı. Şükrederiz, çünkü adın yakındır. İnsanlar senin şaşılası işlerini anlatırlar."],["2","Belirlenen vakti seçtiğimde, kusursuzca ben yargılayacağım."],["3","Yeryüzünde oturanların tümü sarsılıyor. Onun direklerini sağlam bir şekilde ben tutuyorum. Selah."],["4","Kibirlilere, “Övünmeyin!”, kötülere, “Boynuzu yukarı kaldırmayın” dedim."],["5","“Boynuzunuzu kaldırmayın. Sert boyunla konuşmayın.”"],["6","Çünkü ne doğudan, ne de batıdan, ne de güneyden gelir yükselme."],["7","Yargıç ancak Tanrı'dır. Birini alçaltır, ötekini yükseltir."],["8","Çünkü Yahve’nin elinde bir kase var, baharatla karıştırılmış köpüklü şarapla dolu. Ondan döker. Gerçekten dünyanın kötüleri onun tortusuna dek yalayıp içerler."],["9","Bense daima bunu ilan edeceğim, Yakov'un Tanrısı'nı ilahilerle öveceğim."],["10","Kötülerin bütün boynuzlarını kıracağım, doğruların boynuzlarıysa yükseltilecektir."]],76:[["1","Müzik şefi için - Telli sazlarla - Asaf’ın mezmuru - İlahi Yahuda'da Tanrı bilinir. İsrael'de adı büyüktür."],["2","Konutu Şalem’dedir, meskeni Siyon'da."],["3","Orada yayın alevli oklarını, kalkanı, kılıcı ve savaş silahlarını kırdı. Selah."],["4","Ne yüce, ne muhteşemsin, av dağlarından daha yüce."],["5","Yiğitler yağmalanmış halde yatıyor, son uykuya yattılar. Hiçbir savaş eri elini kaldıramaz."],["6","Ey Yakov'un Tanrısı, sen azarlayınca, savaş arabası da atlar da ölüm uykusuna daldılar."],["7","Yalnız sensin korkulması gereken. Öfkelendiğinde kim karşında durabilir?"],["8","Yeryüzünde acı çekenleri kurtarmak için Tanrı yargılamaya kalktığında,"],["9","Yargını gökten bildirdin, yer korktu ve sustu. Selah."],["10","Elbette insanın gazabı seni över. Gazabından sağ kurtulanlar dizginlendi."],["11","Tanrınız Yahve’ye adak adayın, onları yerine getirin! Armağanlar sunun korkulması gereken O’na, ey siz çevresindekiler."],["12","O, beylerin ruhunu kırar. Yeryüzü kralları O’ndan korkar."]],77:[["1","Müzik Şefi Yedutun için - Asaf’ın mezmuru Haykırışım Tanrı’yadır! Yardım için, beni duysun diye Tanrı'ya haykırırım."],["2","Sıkıntılı günde Efendi’yi aradım. Geceleyin elimi açtım ve gevşemedi. Canım teselli edilmeyi reddetti."],["3","Tanrı'yı anıyorum ve inliyorum. Yakınıyorum ve ruhum bunalmış durumda. Selah."],["4","Göz kapaklarımı açık tutuyorsun. Konuşamayacak kadar çok sıkıntılıyım."],["5","Eski günleri, geçmiş devirlerin yıllarını düşünmekteyim."],["6","Gece ilahimi hatırlıyorum. Kendi yüreğimi düşünüyorum; ruhum inceden inceye soruyor:"],["7","“Efendi bizi sonsuza dek mi reddedecek? Bir daha lütuf göstermeyecek mi?"],["8","O’nun sevgi dolu iyiliği sonsuza dek mi yok oldu? Nesiller boyunca verdiği söz boşa mı çıkıyor?"],["9","Tanrı lütufkâr olmayı unuttu mu? Merhametini öfkeyle geri mi çekti?” Selah."],["10","Sonra şöyle düşündüm: “Yüceler Yücesi'nin sağ elinin yıllarını anacağım.”"],["11","Yah'ın yaptıklarını hatırlayacağım; çünkü senin eski harikalarını anarım."],["12","Ben de senin bütün işlerin üzerinde derin derin düşünürüm, yaptıklarını dikkate alırım."],["13","Senin yolun, ey Tanrı, kutsal yerdedir. Hangi ilâh Tanrı kadar büyüktür?"],["14","Sen harikalar yaratan Tanrı’sın. Gücünü halklar arasında bildirdin."],["15","Halkını kolunla, Yakov ve Yosef’in oğullarını kurtardın. Selah."],["16","Sular seni gördü, ey Tanrı. Sular seni gördü ve çalkalandı. Derinlikler de sarsıldı."],["17","Bulutlar suyunu boşalttı. Gökler gök gürültüsüyle ses verdi. Okların da etrafta ışık çaktı."],["18","Gürleyişinin sesi kasırgadaydı. Şimşekler dünyayı aydınlattı. Yer titredi ve sarsıldı."],["19","Senin yolun denizden geçiyordu; yolların büyük sulardaydı. Ayak izlerin belli değildi."],["20","Moşe ve Aron’un eliyle, halkını sürü gibi güttün."]],78:[["1","Asaf’ın Maskili Öğrettiğime kulak verin, ey halkım. Ağzımdan çıkan sözlere kulaklarınızı çevirin."],["2","Ağzımı bir benzetmeyle açacağım. Eskilerin sırlarını söyleyeceğim,"],["3","onları işittik ve bildik, atalarımız bize anlattı."],["4","Onları çocuklarından saklamayacağız, Yahve’nin övgülerini, gücünü ve yaptığı şaşılası işleri, gelecek kuşağa anlatacağız."],["5","Çünkü Yakov'la bir antlaşma yaptı, İsrael'de bir öğreti atadı, atalarımıza bunları çocuklarına öğretmelerini buyurdu."],["6","Gelecek nesiller, hatta doğmamış çocuklar bilsin de, onlar da kalkıp kendi çocuklarına anlatsınlar."],["7","Böylece umutlarını Tanrı'ya bağlasınlar, Tanrı’nın yaptıklarını unutmasınlar, buyruklarını tutsunlar."],["8","Ataları gibi inatçı ve asi, yürekleri vefasız, ruhları Tanrı’ya sadakatsiz bir nesil olmasınlar."],["9","Silahlı, yay taşıyan Efraim'in çocukları, savaş gününde geri döndüler."],["10","Tanrı'nın antlaşmasına uymadılar, O’nun yasasında yürümeyi reddettiler."],["11","O’nun yaptıklarını, onlara göstermiş olduğu şaşılası işlerini unuttular."],["12","Mısır diyarında, Soan kırında, atalarımızın önünde şaşılacak işler yaptı."],["13","Denizi yardı ve onları içinden geçirdi. Suları yığın gibi durdurdu."],["14","Gündüzleri bulutla, gece boyu ateş ışığıyla onlara yol gösterdi."],["15","Çölde kayaları yardı, derinliklerden geliyormuşçasına onlara bol bol içirdi."],["16","Kayadan dereler çıkardı, suları ırmaklar gibi akıttı."],["17","Yine de O’na karşı günah işlemeye devam ettiler. En Yüce Olan'a isyan ettiler."],["18","İştahlarına göre yemek isteyerek, yüreklerinde Tanrı’yı denediler."],["19","Tanrı'ya karşı konuşup, “Tanrı çölde sofra kurabilir mi?” dediler."],["20","“İşte kayaya vurdu ve sular fışkırdı, ırmaklar taştı. Ekmek de verebilir mi? Halkına et sağlayabilir mi?”"],["21","Bunun üzerine Yahve işitip öfkelendi. Yakov'a karşı ateş tutuştu, ve öfke İsrael'e karşı yükseldi,"],["22","Çünkü Tanrı'ya inanmadılar, O’nun kurtarışına güvenmediler."],["23","Yine de yukarıda göklere buyurdu, göklerin kapılarını açtı."],["24","Yemek için üzerlerine man yağdırdı, onlara gökten yiyecek verdi."],["25","İnsanlar meleklerin ekmeğini yedi. Onlara doyasıya yiyecek gönderdi."],["26","Gökte doğu rüzgârını estirdi. Gücüyle güney rüzgârına yol gösterdi."],["27","Üzerlerine toz gibi et, denizlerin kumu gibi kanatlı kuşlar yağdırdı."],["28","Onları ordugâhlarının ortasına, oturdukları yerlerin çevresine düşürdü."],["29","Böylece yediler ve iyice doydular. Onlara dilediklerini verdi."],["30","Arzularından vazgeçmediler. Yiyecekleri hâlâ ağızlarındayken"],["31","Tanrı'nın öfkesi onlara karşı yükseldi, en şişmanlarından bazılarını öldürdü, İsrael'in gençlerini yere serdi."],["32","Bütün bunlara rağmen yine günah işlediler, O’nun şaşılası işlerine inanmadılar."],["33","Bu yüzden günlerini boşlukla, yıllarını dehşetle tüketti."],["34","Kendilerini öldürdüğü zaman O'nu araştırdılar. Geri döndüler ve gayretle Tanrı'yı aradılar."],["35","Tanrı'nın kayaları olduğunu, yüce Tanrı’nın kurtarıcıları olduğunu hatırladılar."],["36","Ama ağızlarıyla O'nu överken, dilleriyle O’na yalan söylediler."],["37","Çünkü yürekleri O’nunla doğru değildi, ne de O’nun antlaşmasına sadıklardı."],["38","Ama O, merhametli davranarak kötülüğü bağışladı ve onları yok etmedi. Evet, birçok kez öfkesini yatıştırdı, gazabını tümüyle uyandırmadı."],["39","Onların yalnızca insan olduğunu hatırladı, geçip giden ve bir daha dönmeyen bir yel."],["40","Çölde O’na kaç kez isyan ettiler, ıssız yerde O’nu gücendirdiler!"],["41","Dönüp dönüp Tanrı'yı denediler, ve İsrael'in Kutsalı’nı kışkırttılar."],["42","O’nun elini, düşmandan kurtardığı günü hatırlamadılar."],["43","Mısır'da gerçekleştirdiği belirtileri, Soan bölgesindeki şaşılası işleri,"],["44","ırmaklarını ve akarsularını, içmesinler diye kana çevirdi."],["45","Aralarına onları yiyip bitiren sinek sürüleri, onları yok eden kurbağalar gönderdi."],["46","Onların mahsullerini tırtıla, emeğini çekirgeye verdi."],["47","Bağlarını doluyla, yabanıl incir ağaçlarını kırgınla yok etti."],["48","Hayvanlarını doluya, sürüleri yakıcı yıldırımlara teslim etti."],["49","Kızgın öfkesini üzerlerine, gazap, hışım ve sıkıntı, bir alay kötülük meleği gönderdi."],["50","Öfkesine yol açtı, canlarını ölümden esirgemedi, hayatlarını vebaya teslim etti,"],["51","Mısır'da ilk doğanların hepsini, Ham'ın çadırlarındaki güçlerinin ilkini vurdu."],["52","Ama kendi halkını koyun gibi götürdü, çölde onları sürü gibi güttü."],["53","Onları güvenlik içinde götürdü ve korkmadılar. Ama deniz düşmanlarını alt etti."],["54","Onları kendi tapınağının sınırına, sağ elinin götürdüğü bu dağa getirdi."],["55","Önlerinden ulusları da kovdu, onlara miras olarak sırayla pay verdi, İsrael oymaklarını çadırlarında oturttu."],["56","Ama yine de Yüce Tanrı'yı deneyip O’na isyan ettiler. O’nun tanıklıklarını tutmadılar."],["57","Ataları gibi geri dönüp hainlik yaptılar. Aldatıcı bir yay gibi eğrildiler."],["58","Çünkü yüksek yerleriyle O'nu öfkelendirdiler, oyma suretleriyle O’nu kıskandırdılar."],["59","Tanrı bunu duyunca öfkelendi, İsrael'den büsbütün iğrendi,"],["60","Böylece insanlar arasında kurduğu çadırı, Şilo çadırını terk etti,"],["61","gücünü sürgüne, yüceliğini düşmanın eline teslim etti."],["62","Halkını da kılıca teslim etti, mirasına öfkelenmişti."],["63","Gençlerini ateş yuttu. El değmemiş kızların düğün şarkısı yoktu."],["64","Kâhinleri kılıçla düştüler, dul karıları ağlayamadı."],["65","Bunun üzerine Efendi uykudan uyanan biri gibi, şaraptan bağıran güçlü bir adam gibi uyandı."],["66","Düşmanlarını arkadan vurdu. Onları sonsuz utanç içinde bıraktı."],["67","Üstelik Yosef'in çadırını da reddetti, Efraim oymağını seçmedi,"],["68","Ama Yahuda oymağını, sevdiği Siyon Dağı’nı seçti."],["69","Tapınağını yükseklikler gibi, sonsuza dek kurduğu yeryüzü gibi yaptı."],["70","Ve hizmetkârı David'i seçti; onu koyun ağıllarından aldı,"],["71","Halkı Yakov’u ve mirası İsrael’in çobanı olmak üzere, onu yavru kuzuların peşinden getirdi."],["72","Böylece yüreğinin dürüstlüğüne göre onların çobanı oldu, becerikli elleriyle onlara yol gösterdi."]],79:[["1","Asaf’ın mezmuru Ey Tanrı, uluslar senin mirasına girdiler. Kutsal tapınağını kirlettiler. Yeruşalem’i taş yığınlarına döndürdüler."],["2","Hizmetkârlarının cesetlerini gökteki kuşlara, kutsallarının etini yeryüzündeki hayvanlara yem olsun diye verdiler."],["3","Kanlarını Yeruşalem'in çevresine su gibi döktüler. Onları gömecek kimse yok."],["4","Komşularımıza yüz karası, etrafımızdakilere eğlence ve alay konusu olduk."],["5","Ne zamana dek, ey Yahve? Sonsuza dek kızgın mı kalacaksın? Kıskançlığın ateş gibi yanacak mı?"],["6","Öfkeni seni tanımayan ulusların üzerine, senin adını anmayan krallıkların üzerine dök."],["7","Çünkü onlar Yakov'u yuttular, yurdunu yok ettiler."],["8","Atalarımızın suçlarını bize karşı tutma. Sevecen merhametlerin bizimle tez buluşsun, çünkü çok muhtacız."],["9","Adının yüceliği uğruna bize yardım et, ey kurtuluşumuzun Tanrısı. Adın uğruna bizi kurtar ve günahlarımızı bağışla."],["10","Uluslar neden “Nerede onların Tanrısı?” desin? Hizmetkârlarının dökülen kanının intikamı alındığı, gözlerimizin önünde, uluslar arasında bilinsin."],["11","Tutsakların iniltisi senin önüne gelsin. Gücünün büyüklüğüne göre, ölüme mahkûm olanları koru."],["12","Komşularımıza sana ettikleri hakaretin aşağılanmasını, onların bağrına yedi kat geri öde, ey Efendimiz."],["13","Böylece biz, senin halkın ve otlağının koyunları, sana daima şükredeceğiz. Tüm nesiller boyunca seni daima öveceğiz."]],80:[["1","Müzik şefi - “Zambaklar Antlaşması” makamında - Asaf’ın mezmuru Duy bizi, ey İsrael’in Çobanı, Yosef'i sürü gibi güden, keruvlar üzerinde oturan sensin, saç ışığını."],["2","Efraim, Benyamin ve Manaşşe'nin önünde uyandır gücünü! Gel ve kurtar bizi!"],["3","Ey Tanrı, bizi döndür, yüzün parlasın, biz de kurtuluruz."],["4","Ordular Tanrısı Yahve, halkının duasına karşı daha ne kadar öfkeleneceksin?"],["5","Onları gözyaşı ekmeğiyle besledin, onlara içmeleri için bol miktarda gözyaşı verdin."],["6","Bizi komşularımızla çekişme kaynağı haline getirdin. Düşmanlarımız kendi aralarında gülüşüyorlar."],["7","Bizi döndür, ey Ordular Tanrısı. Yüzün parlasın, biz de kurtuluruz."],["8","Mısır'dan bir asma getirdin. Ulusları kovdun ve onu diktin."],["9","Onun için toprağı temizledin. Derin kök saldı ve ülkeyi doldurdu."],["10","Dağlar onun gölgesiyle kaplandı. Dalları Tanrı’nın sedirleri gibiydi."],["11","Dalları denize, filizleri nehre kadar uzandı."],["12","Duvarlarını neden yıktın, yoldan geçen herkes onu neden koparıyor?"],["13","Ormandan çıkan domuz onu harap ediyor. Kırdaki yabanıl hayvanlar ondan besleniyor."],["14","Sana yalvarıyoruz, ey Ordular Tanrısı, geri dön gökten aşağıya bak ve gör bu asmayı,"],["15","sağ elinin diktiği çubuğu, Kendin için kuvvetlendirdiğin dalı ziyaret et."],["16","Ateşle yandı. Kesildi. Senin azarlamanla yok olup gidiyorlar."],["17","Senin elin, sağ elinin adamı üzerinde, kendin için kuvvetlendirdiğin insanoğlunun üzerinde olsun."],["18","Böylece senden ayrılmayacağız. Canlandır bizi, biz de senin adını çağıralım."],["19","Ey Ordular Tanrısı Yahve, bizi döndür, yüzün parlasın, biz de kurtuluruz."]],81:[["1","Müzik şefi için - Gittit üzerine - Asaf’ın mezmuru Gücümüz olan Tanrı'ya yüksek sesle ilahi söyleyin! Yakov'un Tanrısı'na sevinçle haykırın!"],["2","Bir ilahi yükseltin, tefi, arpla birlikte hoş liri buraya getirin."],["3","Yeni Ay’da, dolunayda, bayram günümüzde boru çalın."],["4","Çünkü bu İsrael için bir yasadır, Yakov'un Tanrısı'nın bir fermanıdır."],["5","Mısır diyarından çıktığı zaman, bunu Yosef için bir antlaşma olarak belirledi. Orada bilmediğim bir dili duydum."],["6","“Onun omzunu yükten kurtardım. Elleri küfeden kurtuldu."],["7","Sıkıntıda çağırdın ve sizi kurtardım. Gök gürültüsünün gizli yerinden sana yanıt verdim. Seni Meriva sularında sınadım.” Selah."],["8","“Dinle ey halkım, size tanıklık edeceğim. Ey İsrael, eğer beni dinlersen!"],["9","Sende yabancı bir ilâh olmayacak, yabancı bir ilâha tapmayacaksın."],["10","Ben senin Tanrın Yahve'yim, seni Mısır diyarından kim çıkardı? Ağzını iyice aç da onu doldurayım."],["11","Ama halkım sesimi dinlemedi. İsrael beni istemedi."],["12","Ben de onları yüreklerindeki inatçılığın ardından salıverdim, kendi öğütlerince yürüsünler diye."],["13","Keşke halkım beni dinleseydi, İsrael benim yollarımda yürüseydi!"],["14","Düşmanlarını hemen boyun eğdirir, elimi düşmanlarına karşı çevirirdim."],["15","Yahve'den nefret edenler O'nun önünde sinerdi, onların cezası sonsuza dek sürerdi."],["16","Ve onu buğdayın en iyisiyle de beslerdim. Seni kayadan bal ile doyururdum.”"]],82:[["1","Asaf’ın mezmuru Tanrı büyük toplantıyı yönetir. İlâhlar arasında hükmeder."],["2","“Ne vakte kadar haksızca yargılayacak, kötüden yana taraf tutacaksınız?” Selah."],["3","“Zayıfı, yoksulu ve yetimi savunun. Yoksulun ve ezilenin hakkını koruyun."],["4","Güçsüzü, muhtaç olanı kurtarın. Onları kötülerin elinden özgür kılın.”"],["5","Bilmiyorlar ve anlamıyorlar. Karanlıkta ileri geri yürüyorlar. Yeryüzünün bütün temelleri sarsılıyor."],["6","“Sizler ilâhlarsınız” dedim. “Hepiniz Yüceler Yücesi'nin oğullarısınız."],["7","Yine de insanlar gibi öleceksiniz, hükümdarlardan biri gibi düşeceksiniz.”"],["8","Kalk, ey Tanrı, yeryüzünü yargıla, çünkü bütün ulusları sen miras alacaksın."]],83:[["1","İlahi - Asaf’ın mezmuru Ey Tanrı, susma. Sessiz ve sakin kalma, ey Tanrı."],["2","Çünkü işte, düşmanların ayağa kalkıyor. Senden nefret edenler başlarını kaldırdılar."],["3","Halkına karşı kurnazca düzen kuruyorlar. Değer verdiğin insanlara karşı öğütleşiyorlar."],["4","“Gelin” diyorlar, “Onları ulus olarak yok edelim. Öyle ki, İsrael’in adı bir daha anılmasın.”"],["5","Tek bir akılla düzen kudular. Sana karşı ittifak oluşturdular."],["6","Edom'un ve İsmailoğulları'nın çadırları, Moavlılar ve Hagarlılar,"],["7","Geval, Ammon ve Amalek, Filist ve Sur halkı,"],["8","Aşur da onlara katıldı. Lut'un çocuklarına yardım ettiler. Selah."],["9","Onlara Midyan’a, Kişon Irmağı’nda Sisera’ya ve Yavin’e yaptığının aynısını yap,"],["10","Onlar En-dor’da yok oldular. Toprak için gübre gibi oldular."],["11","Onların soylularını Orev ve Zeev gibi, beylerini Zevah ve Salmunna’ya yaptığın gibi yap."],["12","Onlar ki, “Tanrı'nın otlaklarını kendimize mülk edinelim” dediler."],["13","Tanrım, onları çalı gibi, rüzgârın önündeki saman çöpü gibi yap."],["14","Ormanı yakan ateş gibi, dağları tutuşturan alev gibi,"],["15","fırtınanla onların peşlerine düş, kasırganla dehşet içinde bırak onları."],["16","Yüzlerini şaşkınlıkla kaplat, ta ki, adını arasınlar, ey Yahve."],["17","Sonsuza dek hayal kırıklığı içinde kalsınlar, dehşete düşsünler. Şaşkınlık içinde kalıp yok olsunlar,"],["18","bilsinler ki, yalnız sen, adı Yahve olan, tüm yeryüzü üzerinde En Yüce’dir."]],84:[["1","Müzik şefi için - Gittit üzerine - Korahoğulları’nın mezmuru Ey Ordular Yahvesi, meskenlerin ne kadar güzeldir!"],["2","Canım Yahve’nin avlularını, bayılırmış gibi özlüyor. Yüreğim ve bedenim hay olan Tanrı’ya haykırıyor."],["3","Serçe bile bir yuva, kırlangıç yavrularını koyabilecek bir yuva buldu, senin sunaklarının yanında, ey Ordular Yahvesi, Kralım ve Tanrım benim."],["4","Ne mutlu senin evinde oturanlara. Sürekli seni överler. Selah."],["5","Ne mutlu, gücü sende olanlara, yüreklerini Siyon’u ziyaret etmeye koyanlara."],["6","Ağlama Vadisi'nden geçerken orayı pınarlara çevirirler. Sonbahar yağmuru onu bereketle kaplar."],["7","Gittikçe güçlenirler. Her biri Siyon'da Tanrı'nın önünde görünür."],["8","Ordular Tanrısı ey Yahve, duamı duy. Dinle, ey Yakov'un Tanrısı. Selah."],["9","Ey kalkanımız olan Tanrı, bak, meshettiğinin yüzünü gör."],["10","Çünkü, avlularında bir gün, bin günden iyidir. Kötülük çadırlarında oturmaktansa, Tanrım’ın evinin kapıcısı olmayı yeğlerim."],["11","Çünkü Yahve Tanrı bir güneş, bir kalkandır. Yahve lütuf ve yücelik verir. Suçsuz olarak yürüyenlerden hiçbir iyiliği esirgemez."],["12","Ey Ordular Yahvesi, ne mutlu sana güvenen insana."]],85:[["1","Müzik şefi için - Korahoğulları’nın mezmuru Ey Yahve, ülkene iyilik ettin. Yakov'un zenginliğini geri getirdin."],["2","Halkının suçunu bağışladın. Bütün günahlarını örttün. Selah."],["3","Bütün gazabını uzaklaştırdın. Öfkenin kızgınlığından geri döndün."],["4","Döndür bizi, kurtuluşumuzun Tanrısı, bize olan öfkeni dindir."],["5","Sonsuza dek bize kızgın mı kalacaksın? Öfkeni tüm nesillere yayacak mısın?"],["6","Halkın sende sevinsin diye, bizi yeniden diriltmeyecek misin?"],["7","Bize sevgi dolu iyiliğini göster, ey Yahve. Kurtuluşunu bize bağışla."],["8","Yahve Tanrı’nın ne söyleyeceğini dinleyeceğim. Çünkü halkına, kutsallarına esenlik konuşacak, ama onlar bir daha akılsızlığa dönmesinler."],["9","Kesinlikle O'nun kurtarışı, kendisinden korkanlara yakındır; ta ki görkem topraklarımızda otursun."],["10","Merhamet ve gerçek buluştular. Doğruluk ve esenlik öpüştüler."],["11","Gerçek yerden bitecek. Doğruluk gökten aşağıya bakacak."],["12","Evet, Yahve iyi olanı verecek. Diyarımız, artarak ürün verecektir."],["13","Doğruluk O’nun önünden gidecektir, adımlarına yol hazırlayacaktır."]],86:[["1","David’in duası Duy, ey Yahve, yanıtla beni, çünkü ben yoksul ve muhtacım."],["2","Canımı koru, çünkü ben tanrısal biriyim. Sen Tanrım, sana güvenen hizmetkârını kurtar."],["3","Bana merhamet et, ey Efendim, çünkü bütün gün sana sesleniyorum."],["4","Hizmetkârının canını sevindir, çünkü canımı sana kaldırıyorum, ey Efendim."],["5","Çünkü sen iyisin, bağışlamaya hazırsın, ey Efendi seni çağıran herkese karşı boldur sevgi dolu iyiliğin."],["6","Duamı duy, ey Yahve. Dileklerimin sesine kulak ver."],["7","Sıkıntılı günümde seni çağırırım, çünkü sen beni yanıtlarsın."],["8","İlâhlar arasında senin gibisi yoktur, ey Efendim, işlerin de benzersizdir."],["9","Yarattığın bütün uluslar gelip sana tapınacaklar, ey Efendim. Adını yüceltecekler."],["10","Çünkü sen büyüksün ve şaşılası işler yaparsın. Yalnız Tanrı sensin."],["11","Ey Yahve, yolunu bana öğret. Senin gerçeğinde yürüyeyim. Adından korkmak için yüreğimi tam kıl."],["12","Ey Efendi Tanrım, bütün yüreğimle seni öveceğim. Adını daima yücelteceğim."],["13","Çünkü bana karşı sevgi dolu iyiliğin büyüktür. Canımı Şeol'ün derinliğinden kurtardın."],["14","Ey Tanrı, gururlular bana karşı ayağa kalktılar. Zorbalar takımı canımın peşine düştü, kendi önlerinde sana saygıları yoktur."],["15","Ama sen, ey Efendim merhametli ve lütufkâr bir Tanrı’sın. Yavaş öfkelenirsin, sevgi dolu iyiliğin ve gerçeğin boldur."],["16","Bana dön de merhamet et! Gücünü hizmetkârına ver. Hizmetkârının oğlunu kurtar."],["17","Bana iyiliğinin bir işaretini göster, ta ki, benden nefret edenler bunu görüp utansınlar, çünkü sen, ey Yahve, bana yardım ettin ve beni teselli ettin."]],87:[["1","Korahoğulları’nın mezmuru - İlahi Onun temeli kutsal dağlardadır."],["2","Yahve Siyon'un kapılarını Yakov'un bütün konutlarından daha çok sever."],["3","Ey Tanrı kenti, senin hakkında görkemli şeyler söylenir. Selah."],["4","Beni tanıyanlar arasında Rahav'ı ve Babil'i kaydedeceğim. İşte, Filist, Sur ve Etiyopya: “Bu da orada doğmuştur.”"],["5","Siyon için şöyle denecek: “Bu ve şu onda doğmuştur.” En Yüce Olan’ın kendisi onu pekiştirecektir."],["6","Yahve ulusları yazarken sayacak, “Bu orada doğmuştur.” Selah."],["7","Dans edenlerle şarkı söyleyenler şöyle diyecek: “Bütün kaynaklarım sendedir.”"]],88:[["1","Korahoğulları’nın mezmuru - İlahi - Müzik şefi için - “Mahalat Leannot” makamında - Ezrahlı Heman Maskili Ey Yahve, kurtuluşumun Tanrısı, gündüz ve gece senin önünde yakardım."],["2","Duam senin önüne gelsin. Yakarışıma kulağını eğ."],["3","Çünkü canım sıkıntılarla dolu. Hayatım Şeol'e yaklaştı."],["4","Çukura inenler arasında sayılıyorum. Yardımcısı olmayan biri gibiyim,"],["5","ölüler arasına ayrılmış, artık hatırlamadığın, Mezarda yatan öldürülmüşler gibiyim. Onlar senin elinden ayrılmıştır."],["6","Beni en derin çukura, en karanlık derinliklerde koydun."],["7","Gazabının ağırlığı üzerimdedir. Bütün dalgalarınla beni ezdin. Selah."],["8","Dostlarımı benden aldın. Beni onlara iğrenç kıldın. Kapatıldım ve kaçamıyorum."],["9","Kederden gözlerim sönüyor. Her gün seni çağırdım, ey Yahve. Ellerimi sana açtım."],["10","Harikalarını ölülere mi göstereceksin? Göçüp gitmiş olan ruhlar mı kalkıp seni övecek? Selah."],["11","Sevgi dolu iyiliğin mezarda, sadakatin yıkım diyarında mı ilan edilir?"],["12","Harikaların karanlıkta, sadakatin unutulmuşluk diyarında mı bilinir?"],["13","Ama ben ey Yahve, sana yakardım. Sabahleyin duam huzuruna gelir."],["14","Ey Yahve, canımı neden reddediyorsun? Neden yüzünü benden gizliyorsun?"],["15","Gençliğimden beri dertliyim ve ölmeye hazırım. Senin dehşetlerine katlanırken, şaşkınım."],["16","Şiddetli öfken üzerime çöktü. Dehşetlerin beni yok etti."],["17","Bütün gün su gibi çevremi sardılar. Beni tamamen içine aldılar."],["18","Sevgiliyi, dostu benden uzaklaştırdın, dostlarım da karanlıktadır."]],89:[["1","Ezrahlı Eytan’ın Maskili Yahve’nin sevgi dolu iyiliğini daima ezgilerle öveceğim. Senin sadakatini bütün kuşaklara ağzımla duyuracağım."],["2","Doğrusu şunu derim: “Sevgi sonsuza dek durur. Gökleri sen kurdun. Senin sadakatin onlardadır.”"],["3","“Seçtiğim kişiyle antlaşma yaptım, hizmetkârım David’e ant içtim:"],["4","‘Senin soyunu daima sürdüreceğim, tahtını bütün nesiller için kuracağım.’” Selah."],["5","Ey Yahve, gökler harikalarını, sadakatini de kutsallar topluluğunda överler."],["6","Göklerde kim Yahve’yle kıyaslanabilir? Göksel varlıkların oğulları arasında Yahve’ye benzeyen kimdir?"],["7","Kutsallar topluluğunda çok heybetli bir Tanrı’dır, çevresinde olanların hepsinden korkunçtur."],["8","Ey Yahve, Ordular Tanrısı, senin gibi güçlü olan kimdir? Ey Yah, sadakatin de çevrendedir."],["9","Denizin gururuna hükmedersin. Dalgaları kabardığında onları sakinleştirirsin."],["10","Rahav'ı öldürülmüş bir adam gibi parçaladın. Güçlü kolunla düşmanlarını dağıttın."],["11","Gökler senindir. Dünya ve onun doluluğuyla birlikte, yeryüzü de senindir. Onları sen kurdun."],["12","Kuzeyi ve güneyi sen yarattın. Tabor ve Hermon senin adınla sevinirler."],["13","Güçlü kolun var. Elin kuvvetlidir, sağ elin yücedir."],["14","Doğruluk ve adalet tahtının temelidir. Sevgi dolu iyilik ve gerçek yüzünün önünden gider."],["15","Ne mutlu seni alkışlamayı öğrenen halka. Senin varlığının ışığında yürürler, ey Yahve."],["16","Bütün gün senin adınla sevinirler. Senin doğruluğunla yükselirler."],["17","Çünkü sen onların gücünün yüceliğisin. Senin lütfunla, boynuzumuz yükselir."],["18","Çünkü kalkanımız Yahve’ye aittir, Kralımız İsrael'in Kutsalı'na."],["19","Sonra kutsallarına görümde konuşup şöyle dedin: “Savaşçıya güç verdim. Bir genci halkın arasından yükselttim."],["20","Hizmetkârım David'i buldum. Onu kutsal yağımla meshettim,"],["21","elimi onunla pekiştireceğim. Kolum da onu güçlendirecektir."],["22","Hiçbir düşman ondan haraç almayacak. Hiçbir kötü kişi onu ezmeyecektir."],["23","Düşmanlarını onun önünde yere sereceğim, ondan nefret edenleri vuracağım."],["24","Ama sadakatim ve sevgi dolu iyiliğim onunla birlikte olacak. Onun boynuzu benim adımla yükselecektir."],["25","Elini de deniz üzerine, sağ elini ırmakların üzerine koyacağım."],["26","Bana şöyle seslenecek: ‘Sen benim Babamsın, Tanrım ve kurtuluşumun kayası!’"],["27","Ben de onu ilk oğlum, dünya krallarının en yücesi olarak atayacağım."],["28","Ona olan sevgi dolu iyiliğimi sonsuza dek sürdüreceğim. Onunla antlaşmamı sabit kılacağım."],["29","Soyunu da sonsuza dek kalıcı, tahtını göğün günleri gibi yapacağım."],["30","Eğer çocukları yasamı terkederse, kurallarıma göre yürümezlerse;"],["31","eğer yasalarımı çiğnerlerse, buyruklarımı tutmazlarsa;"],["32","o zaman günahlarını değnekle, kötülüklerini sopayla cezalandıracağım."],["33","Ama sevgi dolu iyiliğimi ondan tümüyle geri almam. Sadakatimi boşa çıkarmam."],["34","Antlaşmamı bozmayacak, dudaklarımın söylediklerini değiştirmeyeceğim."],["35","Bir kere kutsallığım üzerine ant içtim, David'e yalan söylemeyeceğim."],["36","Onun soyu sonsuza dek, tahtı önümde güneş gibi duracak."],["37","Gökyüzündeki sadık tanık ay gibi, sonsuza dek duracak.” Selah."],["38","Ama sen reddettin ve attın. Meshettiğine öfkelendin."],["39","Hizmetkârının antlaşmasından vazgeçtin. Onun tacını toz toprakla kirlettin."],["40","Onun bütün surlarını yıktın. Kalelerini harabeye çevirdin."],["41","Yoldan geçen herkes onu soydu. Komşuları için bir utanç haline geldi."],["42","Düşmanlarının sağ elini yükselttin. Bütün düşmanlarını sevindirdin."],["43","Kılıcının ağzını da döndürdün, savaşta ona destek olmadın."],["44","Onun ihtişamına son verdin, tahtını yere çaldın."],["45","Gençlik günlerini kısalttın. Onu utançla kapladın. Selah."],["46","Ne vakte kadar, ey Yahve? Kendini sonsuza dek mi gizleyeceksin? Ne vakte kadar, gazabın ateş gibi yanacak?"],["47","Zamanımın ne kadar kısa olduğunu hatırla, insanoğullarının hepsini ne denli boş yaratmışsın!"],["48","Yaşayıp da ölümü görmeyen, Şeol'ün gücünden canını kurtaran biri var mı? Selah."],["49","Ey Efendim, nerede o eski sevgi dolu iyiliğin, sadakatinle David’e ant içttiğin?"],["50","Unutma, ey Efendi, hizmetkârının aşağılanmasını, bütün güçlü halkların alaylarını nasıl bağrımda taşıdığımı,"],["51","düşmanların onunla alay ettiler, ey Yahve, meshettiğinin ayak izleriyle alay ettiler."],["52","Sonsuza dek övgüler olsun Yahve’ye. Amin ve Amin."]],90:[["1","Tanrı adamı Moşe’nın duası Ey Efendi, bütün kuşaklar boyunca sen bizim meskenimiz oldun."],["2","Dağlar doğmadan önce, sen yeryüzünü ve dünyayı yaratmadan önce, öncesizlikten sonsuza dek, Tanrı sensin."],["3","İnsanı yıkıp şöyle dersin: “Geri dönün, insanoğulları.”"],["4","Çünkü senin gözünde bin yıl geçmiş dün gibi, gece nöbeti gibidir."],["5","Uyuduklarında onları süpürürsün. Sabahleyin biten ot gibidirler."],["6","Sabahleyin filizlenip yeşerir, akşama doğru solup kurur."],["7","Çünkü senin öfkenle tükeniriz. Gazabınla şaşkına döneriz."],["8","Kötülüklerimizi önüne, gizli günahlarımızı senin varlığının ışığına koydun."],["9","Çünkü bütün günlerimiz senin gazabında geçiyor. Yıllarımızı bir soluk gibi bitirmekteyiz."],["10","Yıllarımızın günleri yetmiş, ya da gücünle sekseni bulursa, yine de onların en parlak zamanı emek ve kederdir, çünkü çabuk geçiyor ve uçup gidiyoruz."],["11","Öfkenin gücünü, gazabını sana duyulan korkuya göre kim bilebilir?"],["12","Öyleyse bize günlerimizi saymayı öğret, öyle ki, bilge bir yürek kazanalım."],["13","Acı, ey Yahve! Ne vakte kadar? Hizmetkârlarına merhamet et!"],["14","Sabahleyin bizi sevgi dolu iyiliğinle doyur, öyle ki, tüm günlerimiz boyunca sevinip mutlu olalım."],["15","Bizi sıkıntıya soktuğun günler kadar, lötülük gördüğümüz yıllar kadar bizi sevindir."],["16","İşin hizmetkârlarına, yüceliğin onların çocuklarına görünsün."],["17","Tanrımız Yahve’nin lütfu üzerimizde olsun. Ellerimizin işini bizim için pekiştir. Evet, ellerimizin işini pekiştir."]],91:[["1","Yüceler Yücesi'nin gizli yerinde oturan Her Şeye Gücü Yeten’in gölgesinde dinlenir."],["2","Yahve için derim: “O benim sığınağım ve kalemdir, Tanrım’dır, O’na güvenirim.”"],["3","Çünkü O seni avcı tuzağından, ölümcül salgından kurtarır."],["4","Seni kanatlarıyla örter. O’nun kanatları altına sığınırsın. O’nun sadakati senin kalkanın ve siperindir."],["5","Ne gecenin dehşetinden korkarsın, ne de gündüz uçan oktan,"],["6","ne karanlıkta dolaşan salgın hastalıktan, ne de öğle vakti bitiren yıkımdan."],["7","Yanında bin kişi, sağında on bin kişi düşebilir, ama sana yaklaşmaz."],["8","Sen yalnız gözlerinle bakacak, kötülerin cezasını göreceksin."],["9","Çünkü sen Yahve’yi sığınak, En Yüce Olan’ı kendine konut edindiğin için,"],["10","başına kötülük gelmeyecek, evine felaket yaklaşmayacak."],["11","Çünkü tüm yollarında seni korusunlar diye, senin için meleklerini sorumlu kılacak,"],["12","ayağın bir taşa çarpmasın diye, seni elleri üzerinde taşıyacaklar,"],["13","aslanın ve kobranın üzerine basacaksın. Genç aslanı ve yılanı ayaklarının altında çiğneyeceksin."],["14","“Sevgisini bana bağladığı için onu kurtaracağım. Adımı bildiği için onu yücelteceğim."],["15","Beni çağıracak, ben de ona yanıt vereceğim. Sıkıntıda onun yanında olacağım. Onu kurtaracak ve yücelteceğim."],["16","Onu uzun ömürle doyuracağım, ona kurtarışımı göstereceğim.”"]],92:[["1","Mezmur - Şabat Günü için ilahi Yahve’ye şükretmek, ey Yüceler Yücesi, adını ilahilerle övmek,"],["2","sabahları sevgi dolu iyiliğini, her gece sadakatini,"],["3","on telli sazla, arpla, lirin ezgisiyle duyurmak ne iyidir."],["4","Çünkü, ey Yahve, işinle beni sevindirdin. Senin ellerinin işleriyle zafer kazanıyorum."],["5","İşlerin ne büyüktür, ey Yahve! Düşüncelerin çok derindir."],["6","Akılsız insan bilmez, budala da bunu anlamaz:"],["7","Kötüler ot gibi bitse de, kötülük edenlerin tümü serpilip gelişse de, onlar sonsuza dek yok edilecekler."],["8","Ama sen, ey Yahve, sonsuza dek yücelerdesin."],["9","Çünkü işte, senin düşmanların, ey Yahve, çünkü işte, düşmanların yok olacak. Bütün kötülük yapanlar dağılacaktır."],["10","Ama sen benim boynuzumu yaban öküzünki gibi yükselttin. Taze yağla meshedildim."],["11","Gözüm düşmanlarımı da gördü. Kulaklarım bana karşı çıkan kötü düşmanları duydu."],["12","Doğrular palmiye ağacı gibi serpilip gelişecektir. Lübnan'daki sedir ağacı gibi büyüyecektir."],["13","Onlar Yahve’nin evine dikilmişlerdir. Tanrımız’ın avlularında serpilip gelişeceklerdir."],["14","Onlar yaşlılıklarında da meyve verecekler. Taze ve yemyeşil olacaklar,"],["15","ta ki, Yahve’nin doğru olduğunu göstersinler. O benim kayamdır, ve O’nda hiç haksızlık bulunmaz."]],93:[["1","Yahve hüküm sürüyor! İhtişamla kuşanmış! Yahve kudretle donanmış. Dünya da pekiştirilmiş, sarsılmaz."],["2","Tahtın eskiden beri kurulmuştur. Sen sonsuzluktansın."],["3","Seller yükseldi, ey Yahve, seller sesini yükseltti. Seller, dalgalarını yükseltti."],["4","Bol suların seslerinin üstünde, denizin kudretli dalgalarından çok, yücelerdeki Yahve kudretlidir."],["5","Kuralların sağlam durur. Kutsallık evini süsler, sonsuza dek, ey Yahve."]],94:[["1","Ey Yahve, sen öcün sahibi olan Tanrı’sın, ey öcün sahibi olan Tanrı, parla."],["2","Kalk, ey yeryüzünün yargıcı. Küstahlara hak ettikleri karşılığı ver."],["3","Ey Yahve, kötüler ne zamana dek, ne zamana dek zafer kazanacaklar?"],["4","Küstahça sözler saçıyorlar. Kötülük edenlerin hepsi övünüyorlar."],["5","Ey Yahve, halkını parçalıyorlar, mirasına eziyet ediyorlar."],["6","Dul kadını ve garibi katlediyorlar, yetimleri öldürüyorlar."],["7","“Yah görmez” diyorlar, “Yakov'un Tanrısı dikkate almaz.”"],["8","Ey sizler, halk arasındaki akılsızlar, dikkat edin, siz ey ahmaklar, ne zaman akıllanacaksınız?"],["9","Kulağı yerleştiren duymaz mı? Göze biçim veren görmez mi?"],["10","Ulusları terbiye eden, cezalandırmaz mı? İnsana öğreten bilir."],["11","Yahve insanın düşüncelerinin, boş olduğunu bilir."],["12","Ey Yah, ne mutlu terbiye ettiğin, yasanı öğrettiğin insana."],["13","Kötüler için çukur kazılıncaya dek, sıkıntılı günlerde ona rahat verirsin."],["14","Çünkü Yahve halkını geri çevirmez, mirasını da bırakmaz."],["15","Çünkü yargı adalete dönecektir. Dürüst yüreklilerin hepsi onu izleyecektir."],["16","Kötülere karşı benim için kim kalkacak? Kötülük edenlere karşı kim beni savunacak?"],["17","Yahve yardımcım olmasaydı, canım hemen sessizlik içinde çökerdi."],["18","“Ayağım kayıyor!” dediğimde, sevgi dolu iyiliğin beni ayakta tuttu, ey Yahve."],["19","İçimdeki düşüncelerin çokluğunda, senin avutmaların canımı sevindiriyor."],["20","Yasayla kötülük eden şer tahtı, seninle paydaşlık içinde olur mu?"],["21","Doğru insanın canına karşı toplanıyorlar, masum kanı mahkûm ediyorlar."],["22","Ama Yahve benim yüksek kulem oldu, Tanrım sığındığım kaya oldu."],["23","kötülüklerini başlarına döndürdü, kendi kötülükleriyle onları kesip atacaktır. Tanrımız Yahve onları kesip atacaktır."]],95:[["1","Gelin, Yahve'ye ezgiler söyleyelim. Kurtuluşumuzun kayasına yüksek sesle haykıralım!"],["2","Şükranla huzuruna çıkalım. O’nu ezgilerle yüceltelim!"],["3","Çünkü Yahve büyük Tanrı’dır, tüm ilâhların üstünde büyük Kral’dır."],["4","Yerin derinlikleri O’nun elindedir. Dağların tepeleri de O’nundur."],["5","Deniz O’nundur ve onu yaratan kendisidir. Karaya biçim veren O’nun elleridir."],["6","Gelin, tapınalım, eğilelim. Yaratıcımız Yahve'nin önünde diz çökelim,"],["7","çünkü Tanrımız O’dur. Biz O’nun otlağının halkı, gözetimindeki koyunlarız. Keşke bugün O’nun sesini duysanız!"],["8","Meriva'da ve o gün Masa Çölü’nde olduğu gibi yüreğinizi katılaştırmayın,"],["9","atalarınız beni denediklerinde, beni sınadıklarında, işimi de görmüşlerdi."],["10","Kırk yıl boyunca o kuşakla kederlendim, “Bunlar, yürekleri kusurlu bir halktır” dedim. “Yollarımı bilmediler.”"],["11","Bunun için öfkemle ant içtim: “Benim dinlenme yerime girmeyecekler.”"]],96:[["1","Yahve’ye yeni bir ezgi söyleyin! Tüm yeryüzü Yahve’ye ezgi söyleyin."],["2","Ezgi söyleyin Yahve’ye! Adını yüceltin! Kurtarışını günden güne duyurun!"],["3","Görkemini uluslar arasında, şaşılası işlerini bütün halklar arasında ilan edin."],["4","Çünkü Yahve büyüktür, fazlasıyla övülmeye layıktır! Bütün ilâhlardan çok O’ndan korkulmalıdır."],["5","Çünkü halkların bütün ilâhları puttur, gökleri yaratansa Yahve’dir."],["6","Saygınlık ve ululuk O’nun önündedir. Güç ve güzellik O’nun tapınağındadır."],["7","Ey ulusların soyları, Yahve’ye verin, yüceliği ve gücü Yahve’ye verin."],["8","Adından ötürü yüceliği Yahve’ye verin. Sunu getirip avlularına girin."],["9","Yahve’ye kutsal düzen içinde tapının. Önünde titreyin, tüm yeryüzü."],["10","Uluslar arasında, “Yahve hüküm sürüyor” deyin. Dünya da pekiştirilmiştir, sarsılmaz. Halkları adaletle yargılar."],["11","Gökler sevinsin, yeryüzü coşsun. Deniz ve içindeki doluluk gürlesin!"],["12","Kır ve içindekilerin tümü coşsun! O zaman ormandaki bütün ağaçlar, sevinçle şarkı söyleyecek,"],["13","Yahve’nin önünde, çünkü O geliyor, yeryüzünü yargılamaya geliyor. Dünyaya doğrulukla, halklara gerçeğiyle hükmedecek."]],97:[["1","Yahve hükmediyor, coşsun yeryüzü! Bütün adalar sevinsin!"],["2","Bulutlar ve karanlık çevresindedir. Doğruluk ve adalet O’nun tahtının temelidir."],["3","O’nun önünden ateş yürüyor, düşmanlarını her yandan yakıyor."],["4","Şimşeği dünyayı aydınlatır. Yeryüzü görüp titrer."],["5","Yahve’nin önünde, tüm yeryüzünün Efendisi önünde dağlar balmumu gibi eridi."],["6","Gökler O’nun doğruluğunu ilan eder. Bütün halklar O’nun yüceliğini gördü."],["7","Oyma putlara hizmet edenlerin hepsi, putlarıyla övünenler, utansınlar. Ey bütün ilâhlar, O’na tapın!"],["8","Siyon duydu ve sevindi. Senin hükümlerinden ötürü, ey Yahve, Yahuda kızları coştu."],["9","Çünkü, ey Yahve, tüm yeryüzünde En Yüce Olan sensin. Bütün ilâhların üstünde çok yücesin."],["10","Ey sizler, Yahve’yi sevenler, kötülükten nefret edin! O, kutsallarının canlarını korur. Onları kötülerin elinden kurtarır."],["11","Doğru için ışık, yüreği dürüst olanlara sevinç ekilmiştir."],["12","Ey doğrular, Yahve’de sevinin! O’nun kutsal Adına şükredin."]],98:[["1","Mezmur Yahve’ye yeni bir ezgi söyleyin, çünkü O şaşılası şeyler yaptı! Sağ eli ve kutsal kolu kendisi için kurtuluş sağladı."],["2","Yahve kurtarışını bildirdi. Doğruluğunu ulusların önünde açıkça gösterdi."],["3","İsrael halkına olan sevgi dolu iyiliğini ve sadakatini hatırladı. Yeryüzünün bütün uçları Tanrımız’ın kurtarışını gördü."],["4","Ey bütün yeryüzü Yahve’ye sevinçle haykırın! Neşeyle ortalığı çınlatın, ezgiler söyleyin!"],["5","Arpla Yahve’ye ezgiler söyleyin, arp ve melodiyle ezgiler söyleyin."],["6","Borularla ve koç boynuzu sesiyle, Kral olan Yahve’nin önünde sevinçle haykırın."],["7","Deniz doluluğuyla, dünya ve onda oturanlar gürlesin."],["8","Irmaklar el çırpsın. Dağlar hep birlikte sevinçle haykırsın."],["9","Yahve’nin önünde ezgi söylesinler, çünkü O geliyor, yeryüzüne hükmetmeye. Dünyayı doğrulukla, halklara adaletle hükmedecek."]],99:[["1","Yahve hüküm sürüyor! Titresin halklar. Keruvlar arasında tahtında oturmuş. Sarsılsın yeryüzü."],["2","Yahve Siyon'da büyüktür. O, bütün halkların üstünde yücedir."],["3","Büyük ve heybetli adını övsünler. O Kutsal’dır!"],["4","Kral’ın gücü adaleti de sever. Doğruluğu sen kurarsın. Yakov'da adalet ve doğruluğu sen gerçekleştirirsin."],["5","Tanrımız Yahve’yi yüceltin. Ayaklarının taburesinde tapının. O Kutsal’dır!"],["6","Moşe'yle Aron O’nun kâhinleri arasındaydı. Samuel adını çağıranlar arasındaydı. Yahve’yi çağırdılar, O da onlara yanıt verdi."],["7","Bulut sütunu içinde onlarla konuştu. O’nun tanıklıklarını ve kendilerine vermiş olduğu kuralları tuttular."],["8","Ey Tanrımız Yahve, sen onlara yanıt verdin, yaptıklarının karşılığını ödetmiş olsan da, onları bağışlayan bir Tanrı oldun."],["9","Tanrımız Yahve’yi yüceltin. Kutsal dağında tapının, çünkü Tanrımız Yahve kutsaldır!"]],100:[["1","Şükran Mezmuru Ey bütün diyarlar, Yahve’ye sevinçle haykırın!"],["2","Yahve’ye sevinçle hizmet edin. O’nun huzuruna ezgilerle gelin."],["3","Bilin ki, Yahve Tanrı’dır. Bizi yaratan O’dur ve biz de O’nunuz. O’nun halkı, otlağının koyunlarıyız."],["4","Şükranla kapılarına, övgüyle avlularına girin. Şükredin O’na, adını yüceltin."],["5","Çünkü Yahve iyidir. Sevgi dolu iyiliği sonsuzdur, sadakati tüm kuşaklar boyunca sürer."]],101:[["1","David’in mezmuru Sevgi dolu iyiliğini ve adaletini ezgiyle söyleyeceğim. Seni ilahilerle öveceğim, ey Yahve."],["2","Temiz bir hayat sürdürmeye dikkat edeceğim. Bana ne zaman geleceksin? Evimin içinde pak bir yürekle yürüyeceğim."],["3","Hiçbir rezil şeyi gözümün önüne koymayacağım. Güvenilmez insanların işlerinden nefret ederim. Bana tutunmayacaklar."],["4","Sapık yürek benden uzak olsun. Kötülükle işim olmaz."],["5","Komşusuna gizlice kara çalanı sustururum. Katlanamam küstah ve kibirli insana."],["6","Gözlerim ülkedeki sadıkların üzerinde olacak, ta ki, benimle otursunlar. Kusursuzca yürüyen kişi, bana hizmet edecek."],["7","Hileci kişi evimde oturmayacak. Yalan söyleyen, gözümün önünde durmayacak."],["8","Her sabah ülkedeki bütün kötüleri yok edeceğim, Yahve’nin kentinden kötülüğün tüm işçilerini kesip atacağım."]],102:[["1","Zayıf düşen ve derdini Yahve’ye döken mazlumun duası Duamı duy, ey Yahve! Feryadım sana ulaşsın."],["2","Sıkıntılı günümde yüzünü benden saklama. Kulağını bana çevir. Çağırdığım gün bana hemen yanıt ver."],["3","Çünkü günlerim duman gibi tükeniyor. Kemiklerim meşale gibi yanıyor."],["4","Yüreğim ot gibi kurudu, soldu, ekmek yemeyi unuttum."],["5","İniltimin sesinden, kemiklerim derime yapışıyor."],["6","Çölde yaşayan kaşıkçı kuşu gibiyim. Çorak yerlerin baykuşu oldum."],["7","Gözlüyorum, damda yalnız kalan bir serçeye döndüm."],["8","Düşmanlarım bütün gün beni aşağılıyor. Bana kızgın olanlar adımı lanet için kullanıyorlar."],["9","Külü ekmek gibi yedim, içeceğime gözyaşları karıştırdım,"],["10","senin öfken ve gazabın yüzünden, çünkü sen beni kaldırıp yere çaldın."],["11","Günlerim uzayan gölge gibi. Ot gibi kurudum."],["12","Ama sen, ey Yahve, sonsuza dek kalıcısın, ünün tüm kuşaklar boyunca sürer."],["13","Sen kalkıp Siyon'a merhamet edeceksin, çünkü ona acıma vakti geldi. Evet, belirlenen zaman geldi."],["14","Çünkü hizmetkârların onun taşlarından zevk alırlar, onun tozuna acırlar."],["15","Böylece uluslar Yahve’nin adından, yeryüzü krallarının tümü görkeminden korkacaklar."],["16","Çünkü Yahve Siyon'u bina etti. Yüceliğiyle göründü."],["17","Yoksulun duasına yanıt verdi, onların duasını küçümsemedi."],["18","Bu, gelecek kuşak için yazılacak. yaratılacak bir halk Yah'ı övecek,"],["19","Çünkü O yücelerdeki kutsal yerinden aşağıya baktı. Yahve gökten yeryüzünü gördü,"],["20","tutsakların iniltilerini duymak, ölüme mahküm edilenleri serbest bırakmak için."],["21","Böylece Yahve’ye hizmet etmek için halklar ve krallıklar bir araya toplanınca,"],["22","Siyon’da Yahve’nin adını, Yeruşalem’de övgüsünü ilan etsinler."],["23","Yol boyunca gücümü zayıflattı. Günlerimi kısalttı."],["24","“Ey Tanrım, beni günlerimin ortasında alma” dedim. “Senin yılların tüm kuşaklar boyuncadır."],["25","Yeryüzünün temelini eskiden sen attın. Gökler senin ellerinin işidir."],["26","Onlar yok olacak, ama sen duracaksın. Evet, hepsi bir giysi gibi eskiyecek. Onları bir kaftan gibi değiştireceksin, onlar da değişecek."],["27","Ama sen aynısın. Yıllarının sonu yoktur."],["28","Hizmetkârlarının çocukları devam edecek. Onların soyu senin önünde sağlamlaştırılacak.”"]],103:[["1","David’in mezmuru Yahve’yi öv, ey canım! İçimde var olan her şey, O’nun kutsal adını övsün!"],["2","Yahve’yi öv, ey canım, iyiliklerinin hiçbirini unutma."],["3","Bütün günahlarını bağışlayan, bütün hastalıklarını iyileştiren,"],["4","canını yıkımdan kurtaran, sana sevgi dolu iyilikle sevecen merhametler tacı giydiren,"],["5","arzunu iyi şeylerle doyuran O’dur, böylece gençliğin kartalınki gibi yenilenir."],["6","Yahve ezilenlerin tümüne hak ve adalet sağlar."],["7","Kendi yollarını Moşe’ye, işlerini İsrael’in çocuklarına bildirdi."],["8","Yahve merhametli ve lütufkârdır, öfkelenmekte yavaş, sevgi dolu iyiliği boldur."],["9","Hep suçlamaz; sonsuza dek öfkeli kalmaz."],["10","Bize günahlarımıza göre davranmadı, ne de kötülüklerimizin karşılığını ödetti."],["11","Çünkü gökler yeryüzünden ne kadar yüksekse, kendisinden korkanlara karşı sevgi dolu iyiliği de o kadar büyüktür."],["12","Doğu batıdan ne kadar uzaksa, isyanlarımızı bizden o kadar uzaklaştırdı."],["13","Bir baba çocuklarına nasıl acırsa, Yahve kendisinden korkanlara öyle acır."],["14","Çünkü yaratılışımızı bilir. Toprak olduğumuzu hatırlar."],["15","İnsana gelince, günleri ota benzer. Kır çiçeği gibi gelişir."],["16","Üzerine rüzgâr esince gelip geçer. Bulunduğu yer artık onu hatırlamaz."],["17","Ama Yahve’nin sevgi dolu iyiliği kendisinden korkanlara karşı sonsuzdur, doğruluğu çocuklarının çocuklarınadır,"],["18","kurallarına uyanlara, O’nun buyruklarına uymayı hatırlayanlaradır."],["19","Yahve tahtını göklerde kurdu. O’nun krallığı her şeye hükmediyor."],["20","Yahve’yi övün, ey O’nun melekleri, güçte büyük olup sözünün sesine itaat eden ve sözünü yerine getiren ey sizler."],["21","Yahve’yi övün, O’nun bütün orduları, isteğini yerine getiren hizmetkârları."],["22","Hakimiyetinin her yerindeki bütün işleri Yahve’yi övün, Yahve’yi öv, ey canım!"]],104:[["1","Ey canım, Yahve’yi öv, ey Yahve, Tanrım, çok büyüksün. Saygınlık ve heybetle giyinmişsin."],["2","O’dur bir giysi gibi kendini ışıkla örten. Gökleri bir perde gibi geren."],["3","O’dur odalarının en üstünü sular üzerine kuran, bulutları kendine araba eden, rüzgârın kanatları üzerinde yürüyen."],["4","O’dur habercilerini rüzgârlar, hizmetkârlarını ateş alevleri yapan."],["5","Yeryüzünün temellerini attın, sonsuza dek sarsılmasın diye."],["6","Bir kaftan gibi onu derinlikle kapladın. Sular dağların üzerinde durdu."],["7","Senin azarlamandan sular kaçtı, gürleyişinin sesiyle hemen çekildiler."],["8","Dağlar yükseldi, vadiler battı, onlar için belirlediğin yere doğru."],["9","Üstünden geçmesinler diye bir sınır çektin, ta ki, yeryüzünü kaplamak için bir daha dönmesinler."],["10","Vadilerde çıkarttığın pınarlar, dağların arasında akarlar."],["11","Kırdaki bütün hayvanlara içecek verir. Yaban eşekleri susuzluklarını giderirler."],["12","Gökteki kuşlar onların yanında yuva yapar. Dalların arasında öterler."],["13","Dağları odalarından sular. Yeryüzü işlerinin ürünüyle doldu."],["14","Hayvanlar için ot, insanın ekip biçmesi için bitkiler yetiştirirsin, öyle ki, topraktan yiyecek çıkarsınlar."],["15","İnsanın yüreğini sevindiren şarabı, yüzünü aydınlatan yağı, yüreğini güçlendiren ekmeği sen verirsin."],["16","Yahve’nin ağaçları, kendi diktiği Lübnan sedirleri iyi sulanır."],["17","Kuşlar orada yuva yaparlar. Leylek ise evini selvi ağaçlarına yapar."],["18","Yüksek dağlar yaban keçileri içindir. Kayalar, kaya porsuklarının sığınağıdır."],["19","Ayı mevsimler için belirledi. Güneş batacağı zamanı bilir."],["20","Karartırsın, gece olur, o zaman tüm orman hayvanları çıkar."],["21","Genç aslanlar avlarının peşinden kükrer, Tanrı’dan yiyeceklerini isterler."],["22","Güneş doğar, çekilirler, inlerinde yatarlar."],["23","İnsan işine gider, akşama kadar çalışır."],["24","Ey Yahve, işlerin ne çoktur! Hepsini bilgeliğinle yaptın. Yeryüzü zenginliklerinle dolu."],["25","Deniz var, büyük ve geniş, içinde sayısız küçük büyük hayvanlar, canlı şeyler bulunur."],["26","Oraya gemiler gider, içinde oynasın diye yarattığın Livyatan oradadır."],["27","Hepsi seni bekliyor, ta ki, onlara yiyeceklerini vaktinde veresin."],["28","Onlara verirsin ve toplarlar. Elini açarsın, iyilikle doyarlar."],["29","Yüzünü gizleyince sıkıntıya düşerler. Soluklarını kesince ölüp toza dönerler."],["30","Ruhunu gönderirsin, yaratılırlar. Yerin yüzünü yenilersin."],["31","Yahve’nin yüceliği sonsuza dek sürsün. Yahve işleriyle sevinsin."],["32","O yeryüzüne bakar, yer titrer. Dağlara dokunur ve onlar tüter."],["33","Yaşadığım sürece Yahve’ye ezgiler söyleyeceğim. Var oldukça Tanrım’ı ezgilerle öveceğim."],["34","Düşüncem O’na hoş görünsün. Ben Yahve ile sevineceğim."],["35","Günahkârlar yeryüzünde tükensin. Artık kötüler olmasın. Ey canım, Yahve’yi öv. Yah’ı öv!"]],105:[["1","Yahve’ye şükredin, adını çağırın! Yaptıklarını halklar arasında bildirin."],["2","O’na ezgilerle, ilahiler söyleyin! O’nun tüm şaşılası işlerini anlatın."],["3","Kutsal adıyla övünün. Yahve’yi arayanların yüreği sevinsin."],["4","Yahve’yi ve O’nun gücünü arayın. Yüzünü daima arayın."],["5","Yaptığı şaşılası işleri, harikalarını ve ağzının hükümlerini hatırlayın:"],["6","Ey sizler, hizmetkârı Avraham’ın soyu, Yakov’un çocukları, O’nun seçilmişleri."],["7","Tanrımız Yahve O’dur. O’nun hükümleri tüm yeryüzündedir."],["8","O, antlaşmasını, bin kuşağa buyurduğu sözü,"],["9","Avraham’la yaptığı antlaşmayı, İshak'a olan andını sonsuza dek hatırlar,"],["10","bunu Yakov için bir kural, İsrael'e sonsuz bir antlaşma olarak onayladı:"],["11","“Mirasının payı olmak üzere, Kenan ülkesini sana vereceğim.”"],["12","O zaman için sayıca birkaç kişiydiler, çok azdılar ve orada yabancıydılar."],["13","Ulustan ulusa, bir krallıktan öteki halka dolaşıp durdular."],["14","Kimsenin onlara kötülük etmesine izin vermedi. Kralları bile onların uğruna azarladı:"],["15","“Meshettiklerime dokunmayın! Peygamberlerime zarar vermeyin!” dedi."],["16","Ülkeye kıtlığı çağırdı. Yiyecek kaynaklarını yok etti."],["17","Önlerinden bir adam gönderdi. Yosef köle olmak üzere satıldı."],["18","Ayaklarına pranga vurdular. Boynunu demir halkayla bağladılar."],["19","Sözü gerçekleşene dek, Yahve’nin sözü onu sınadı."],["20","Kral gönderip onu özgür kıldı. Halklara hükmeden onu salıverdi."],["21","Onu evinin efendisi, tüm malının yöneticisi yaptı,"],["22","Beylerini istediği gibi eğitsin, ihtiyarlarına bilgelik öğretsin diye."],["23","İsrael de Mısır'a geldi. Yakov Ham ülkesinde yaşadı."],["24","Halkını çok artırdı, onları düşmanlarından daha güçlü yaptı."],["25","Hizmetkârlarına karşı düzen kursunlar diye, onların yüreklerini halkından nefret etmeye yöneltti,"],["26","Hizmetkârı Moşe'yi, seçmiş olduğu Aron’u gönderdi."],["27","Aralarında mucizeler, Ham diyarında harikalar gerçekleştirdiler."],["28","Karanlık gönderip ortalığı kararttı. Sözlerine karşı gelmediler."],["29","Sularını kana çevirdi, balıklarını öldürdü."],["30","Ülkeleri kurbağalarla dolup taştı, krallarının odalarında bile."],["31","O söyleyince sinek sürüleri, tüm sınırları içine bitler geldi."],["32","Onlara yağmur yerine dolu, ülkelerine yıldırım verdi."],["33","Bağlarını, incir ağaçlarını vurdu, ülkelerinin ağaçlarını parçaladı."],["34","O söyleyince, çekirgeler, sayısız çekirgeler geldi."],["35","Ülkelerinin bütün bitkilerini, topraklarının ürününü yediler."],["36","Ülkelerinin ilk doğanlarının hepsini, güçlerinin ilk ürünlerini vurdu."],["37","Onları altın ve gümüşle çıkardı. Oymaklarının içinde tek bir zayıf insan bile yoktu."],["38","Onlar gidince Mısır sevindi, çünkü onların korkusu üzerlerine çökmüştü."],["39","Örtü olarak bulutu, geceyi aydınlatmak için ateşi serdi."],["40","İstediler, O da bıldırcın getirdi, onları gökyüzünün ekmeğiyle doyurdu."],["41","Kayayı yardı ve sular fışkırdı. Kurak yerlerde ırmak gibi aktı."],["42","Çünkü kutsal sözünü, hizmetkârı Avraham’ı hatırladı."],["43","Halkını sevinçle, seçmiş olduklarını ezgiyle dışarı çıkardı."],["44","Ulusların topraklarını onlara verdi. Halkların emeğini miras aldılar,"],["45","ta ki O’nun kurallarını tutsunlar, yasasını yerine getirsinler. Yah’ı övün!"]],106:[["1","Yahve’ye övgüler olsun! Yahve’ye şükredin, çünkü O iyidir, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["2","Yahve’nin büyük işlerini kim dile getirebilir? Ya da tüm övgülerini tam olarak kim ilan edebilir?"],["3","Ne mutlu adaleti tutanlara. Ne mutlu, her zaman doğru olanı yapan insana."],["4","Halkına gösterdiğin lütufla beni hatırla, ey Yahve. Kurtarışınla beni ziyaret et,"],["5","öyle ki, seçtiklerinin başarısını göreyim, ulusunun sevinciyle coşayım, Mirasınla birlikte övüneyim."],["6","Atalarımızla birlikte günah işledik. Suç işledik. Kötülük yaptık."],["7","Atalarımız Mısır'daki harikalarını anlamadılar. Sevgi dolu iyiliklerinin çokluğunu hatırlamadılar, denizde, Kızıldeniz'de isyan ettiler."],["8","Kudretli gücünü bildirsin diye, yine de kendi adı uğruna onları kurtardı,"],["9","Kızıldeniz'i de azarladı ve deniz kurudu, çölden geçermiş gibi onları derinliklerden geçirdi."],["10","Onları kendilerinden nefret edenin elinden kurtardı, onları düşmanın elinden kurtardı."],["11","Sular düşmanlarını örttü. Geride onlardan biri bile kalmadı."],["12","O zaman sözlerine inandılar. O’na ezgilerle övgülerini sundular."],["13","O’nun işlerini hemen unuttular. O’nun öğüdünü beklemediler,"],["14","ama çölde iştahlarına yenik düştüler, ıssız yerde Tanrı'yı denediler."],["15","Onlara istediklerini verdi, ama canlarına zayıflık gönderdi."],["16","Ordugâhta da Moşe’yi, Yahve'nin kutsalı Aron’u kıskandılar."],["17","Yer yarıldı ve Datan'ı yuttu, Aviram'ın yandaşlarını örttü."],["18","Onların arasında ateş tutuştu, alevi kötüleri yaktı."],["19","Horev'de bir buzağı yaptılar, dökme bir surete taptılar."],["20","Böylece ot yiyen bir öküzün sureti için kendi yüceliklerini değiştiler."],["21","Kurtarıcılarını, Mısır'da büyük şeyler,"],["22","Ham diyarında harika işler, Kızıldeniz'de korkunç şeyler yapmış olan Tanrı'yı unuttular."],["23","Bu nedenle onları yok edeceğini söyledi, seçtiği Moşe, yok etmesin diye, gazabını döndürmek için O’nun önünde gedikte durmasaydı, onları yok edecekti."],["24","Evet, güzel ülkeyi küçümsediler. Sözüne inanmadılar,"],["25","ama çadırlarında söylendiler, Yahve’nin sesini dinlemediler."],["26","Bu nedenle onları çölde devirmeye,"],["27","Soylarını uluslar arasında düşürmeye, onları ülkelere dağıtmaya onlara ant içti."],["28","Baal Peor'a da bağlandılar. Ölülerin kurbanlarını yediler."],["29","Böylece işleriyle O'nu öfkelendirdiler. Üstlerine veba geldi."],["30","Bunun üzerine Pinehas ayağa kalktı ve yargıyı gerçekleştirdi. Böylece veba durduruldu."],["31","Bu ona doğruluk sayıldı, gelecek tüm kuşaklar için."],["32","Meriva sularında da O'nu öfkelendirdiler; Moşe onlardan ötürü sıkıntıya düştü;"],["33","O'nun ruhuna karşı isyan ettikleri için düşünmeden dudaklarıyla konuştu."],["34","Yahve’nin onlara buyurduğu gibi, halkları yok etmediler."],["35","Ama uluslara karıştılar, onların işlerini öğrendiler."],["36","Putlarına hizmet ettiler, bu onlara tuzak oldu."],["37","Evet, oğullarını ve kızlarını iblislere kurban ettiler."],["38","Suçsuz kanı döktüler, oğullarının ve kızlarının kanlarını bile, Kenan putlarına kurban olarak sundular. Toprak kanla kirlendi."],["39","Böylece işleriyle kirlendiler, kendi eylemlerinde fahişelik ettiler."],["40","Bu yüzden Yahve’nin öfkesi halkına karşı tutuştu. Mirasından nefret etti."],["41","Onları ulusların eline verdi. Onlardan nefret edenler onlara hükmetti."],["42","Düşmanları da onlara zulmetti. Onların eli altında boyun eğdirildiler."],["43","Onları defalarca kurtardı, ama kendi öğütlerinde isyankârdılar, kötülükleri yüzünden alçaltıldılar."],["44","Yine de onların sıkıntısını gördü, onların yakarışlarını duyduğunda."],["45","Onlar için antlaşmasını hatırladı, sevgi dolu iyiliğinin çokluğuna göre düşüncesinden vazgeçti."],["46","Onları tutsak alanların onlara acımasını sağladı."],["47","Kurtar bizi, ey Tanrımız Yahve, kutsal adına şükretmek, övgünle zafer kazanmak için, bizi ulusların arasından topla!"],["48","İsrael'in Tanrısı Yahve’ye, sonsuzluklar boyunca övgüler olsun! Bütün halk “Amin” desin. Yah’a övgüler olsun! 5. KİTAP"]],107:[["1","Yahve’ye şükredin, çünkü O iyidir, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["2","Yahve’nin kurtardıkları böyle desinler, düşmanın elinden kurtardıkları,"],["3","onları, doğudan ve batıdan, kuzeyden ve güneyden, ülkelerden topladı."],["4","Çölde ıssız bir yolda dolaştılar. Yaşanacak bir kent bulamadılar."],["5","Aç ve susuz, içlerindeki canları bitkin düştü."],["6","O zaman sıkıntı içinde Yahve’ye yakardılar, onları sıkıntılarından kurtardı,"],["7","yaşamak için bir kente gidebilsinler diye, onlara doğru yolda öncülük etti."],["8","Yahve’ye sevgi dolu iyiliği için, insanoğullarına olan harika işleri için, övsünler!"],["9","Çünkü özlemle dolu canı doyurur. Aç canı iyilikle doldurur."],["10","Bazıları karanlıkta, ölümün gölgesinde, ıstırap ve demirle bağlı oturmuştu."],["11","Çünkü Tanrı'nın sözlerine isyan ettiler, Yüceler Yücesi'ni küçümsediler."],["12","Bu nedenle onların yüreğini emekle alçalttı. Düştüler, yardım edecek kimse yoktu."],["13","O zaman sıkıntı içinde Yahve’ye yakardılar, onları sıkıntılarından kurtardı."],["14","Onları karanlıktan ve ölümün gölgesinden çıkardı, zincirlerini kırdı."],["15","Yahve’ye sevgi dolu iyiliği için, insanoğullarına olan harika işleri için, övsünler!"],["16","Çünkü tunç kapıları kırdı, demir sürgüleri parçaladı."],["17","Akılsızlar itaatsizliklerinden ve kötülükleri yüzünden sıkıntı çekerler."],["18","Canları her türlü yiyecekten tiksinir. Ölüm kapılarına yaklaşırlar."],["19","O zaman sıkıntı içinde Yahve’ye feryat ederler, onları sıkıntılarından kurtarır."],["20","Sözünü gönderip onları iyileştirir, onları mezarlarından kurtarır."],["21","Yahve’ye sevgi dolu iyiliği için, insanoğullarına olan harika işleri için, övsünler!"],["22","Şükran kurbanları sunsunlar, işlerini ezgilerle ilan etsinler."],["23","Gemilerle denize inenler, büyük sularda iş yapanlar,"],["24","onlar Yahve’nin işlerini, derinlerdeki harikalarını görürler."],["25","Çünkü O buyruk verir, fırtına rüzgârını kaldırır, denizin dalgalarını yükseltir."],["26","Gökyüzüne yükselirler, yeniden derinlere inerler. Sıkıntıdan ötürü canları erir."],["27","Sarhoş biri gibi ileri geri sallanıp, sendelerler, akılları başlarından gider."],["28","O zaman sıkıntı içinde Yahve’ye feryat ederler, onları sıkıntılarından kurtarır."],["29","Fırtınayı yatıştırır, dalgalar sakinleşir."],["30","O zaman ortalık sakinleştiği için sevinirler, onları diledikleri limana götürür."],["31","Yahve’ye sevgi dolu iyiliği için, insanoğullarına olan harika işleri için, övsünler!"],["32","Halk topluluğunda O'nu yüceltsinler, ihtiyarlar meclisinde O’nu övsünler."],["33","Irmakları çöle, pınarları kuru toprağa,"],["34","verimli toprağı orada oturanların kötülüğü yüzünden çorak alana döndürür."],["35","Çölü su göletine, kurak yeri su pınarlarına çevirir."],["36","Yaşanacak bir kent hazırlasınlar diye orada açları yaşatır."],["37","Tarlalar ekerler, bağlar dikerler, çoğalan ürünü toplarlar."],["38","Onları da kutsar, böylece fazlasıyla çoğalırlar. Hayvanlarının eksilmesine izin vermez."],["39","Baskı, sıkıntı ve keder yüzünden yine azalırlar ve alçalırlar."],["40","Beylere hakaret yağdırır, yolsuz çorak bir yerde onları dolaştırır."],["41","Yine de yoksulları sıkıntılarından kurtarır, ailelerini sürü gibi çoğaltır."],["42","Doğrular bunu görecek ve sevinecek. Bütün kötüler ağzını kapayacak."],["43","Bilge olan bunlara dikkat etsin. Yahve’nin sevgi dolu iyiliklerini düşünsün."]],108:[["1","Ezgi - David’in mezmuru Yüreğim kararlıdır, ey Tanrı. İlahi söyleyecek, canımla ezgiler dizeceğim."],["2","Uyan, ey arp ve lir! Şafağı ben uyandırayım."],["3","Uluslar arasında sana şükürler sunayım, ey Yahve. Halkların arasında seni ilahilerle öveyim."],["4","Çünkü sevgi dolu iyiliğin göklerin üstünde büyüktür. Sadakatin gökyüzüne ulaşır."],["5","Ey Tanrı, göklerin üstünde yücel! Görkemin tüm yeryüzünü kaplasın."],["6","Sevdiklerin kurtulsun diye, sağ elinle kurtar ve yanıt ver bize."],["7","Tanrı kutsal yerinden şöyle konuştu: “Zafer kazanacağım. Şekem'i böleceğim, Sukkot Vadisi’ni ölçeceğim."],["8","Gilad benimdir, Manaşşe de benim. Efraim de başımın siperi, Yahuda asamdır."],["9","Moav yıkanma leğenimdir. Edom'un üzerine çarığımı atacağım. Filist üzerine zaferle haykıracağım.”"],["10","Kim beni surlu kente götürecek? Bana kim Edom'a kadar yol gösterecek?"],["11","Ey Tanrı, sen bizi reddetmedin mi? Ordularımızla yola çıkmıyorsun, ey Tanrı."],["12","Düşmana karşı bize yardım et, çünkü insanın yardımı boştur."],["13","Tanrı’yla yiğitlik ederiz, çünkü düşmanlarımızı ezecek olan O’dur."]],109:[["1","Müzik şefi için - David’in mezmuru Ey övgülerimin Tanrısı, sessiz kalma,"],["2","Çünkü kötünün ağzını, hilekâr ağzını bana karşı açtılar. Benimle yalancı bir dille konuştular."],["3","Nefret dolu sözlerle çevremi sarıp, nedensiz yere bana karşı savaştılar."],["4","Sevgime karşılık bana düşmandırlar, bense dua etmekteyim."],["5","İyiliğe kötülükle, sevgime nefretle karşılık verdiler."],["6","Başına kötü bir adam koy. Sağ yanında bir düşman dursun."],["7","Yargılandığı zaman suçlu çıksın. Duası günaha dönsün."],["8","Günleri az olsun. Makamını bir başkası alsın."],["9","Çocukları yetim, karısı dul kalsın."],["10","Çocukları başıboş gezen dilenciler olsun. Yıkık yerlerinden çıkıp aransınlar."],["11","Tefeci tüm malını kapsın. Emeğinin ürününü yabancılar yağmalasın."],["12","Ona iyilik eden kimse olmasın, yetimlerine acıyacak kimse olmasın."],["13","Soyu kesilsin. Gelecek kuşakta adları silinsin."],["14","Atalarının suçları Yahve tarafından hatırlansın. Annesinin günahı silinmesin."],["15","Sürekli Yahve’nin önünde bulunsunlar, öyle ki, anılarını yeryüzünden kesip atsın."],["16","İyilik etmeyi hatırlamadı, ama yoksulu ve muhtacı, yüreği kırık olanı öldürmek için zulmetti."],["17","Laneti sevdi ve kendi başına geldi. Kutsamaktan hoşlanmadı ve bu ondan uzak kaldı."],["18","Laneti giysisi gibi kuşandı. Su gibi iç kısımlarına, yağ gibi kemiklerine girdi."],["19","Kendisini örteceği giysi gibi olsun ona, hep kuşandığı bir kemer gibi olsun."],["20","Düşmanlarıma, canım için kötülük söyleyenlere Yahve’nin verdiği karşılık budur."],["21","Ama sen, ey Efendim Yahve, adın uğruna benimle ilgilen, çünkü sevgi dolu şefkatin iyidir, kurtar beni."],["22","Çünkü ben yoksul ve muhtacım. Yüreğim içimde yaralı."],["23","Akşam gölgesi gibi kayboluyorum. Çekirge gibi silkelenip atıldım."],["24","Dizlerim oruçtan zayıfladı. Bedenim ince ve yağsız kaldı."],["25","Ben de onlara yüzkarası oldum. Beni gördüklerinde başlarını sallıyorlar."],["26","Yardım et bana, ey Yahve Tanrım. Sevgi dolu iyiliğin uyarınca beni kurtar;"],["27","bilsinler ki bu senin elindir, bunu yapan sensin ey Yahve."],["28","Onlar lanet edebilir, ama sen kutsa. Ayağa kalktıklarında utanacaklar, ama senin hizmetkârın sevinecek."],["29","Düşmanlarım rezilliği giyinsin. Bir elbise gibi kendilerini kendi utançlarıyla örtsünler."],["30","Yahve’ye ağzımla çok şükürler sunacağım. Kalabalığın arasında O’nu öveceğim."],["31","Çünkü O, yoksulun canını yargılayanlardan onu kurtarmak için sağında durur."]],110:[["1","David’in mezmuru Yahve Efendim’e: “Ben düşmanlarını ayakların için tabure edene dek, sağımda otur” dedi."],["2","Yahve senin kuvvet asanı Siyon'dan gönderecek. Düşmanlarının arasında hüküm sür."],["3","Halkın, gücünün gününde kutsal düzen içinde kendilerini gönüllü olarak sunarlar. Gençlerin sabahın rahminden doğan çiğ gibidir."],["4","Yahve ant içti, düşüncesini değiştirmez: “Melkisedek düzeninde sen sonsuza dek kâhinsin.”"],["5","Efendi senin sağındadır. Gazabının gününde kralları ezecek."],["6","Uluslar arasında hüküm verecek. Cesetleri yığacak. Bütün dünyanın hükümdarını ezecek."],["7","Yolda dereden içecek; bu nedenle başını dik tutacak."]],111:[["1","Yah’ı övün! Doğruların meclisinde ve topluluk içinde bütün yüreğimle Yahve’ye şükürler sunacağım,"],["2","Yahve’nin işleri büyüktür, onlardan zevk alanların hepsi onları düşünür."],["3","O’nun işi saygınlık ve heybettir. Doğruluğu sonsuza dek sürer."],["4","Harika işlerinin hatırlanmasını sağladı. Yahve lütufkâr ve merhametlidir."],["5","Kendisinden korkanlara yiyecek verir. O her zaman antlaşmasını hatırlar."],["6","Ulusların mirasını onlara vermekle halkına işlerinin gücünü gösterdi,"],["7","ellerinin işleri gerçek ve adalettir. O’nun bütün kuralları kesindir."],["8","Onlar sonsuzluklar boyunca sabittir. Gerçek ve doğrulukla yapılır."],["9","Halkına kurtuluş gönderdi. Antlaşmasını sonsuza dek atamıştır. O’nun adı kutsal ve muhteşemdir!"],["10","Yahve korkusu bilgeliğin başlangıcıdır. O’nun işini yapanların hepsi iyi bir anlayışa sahiptir. O’nun övgüsü sonsuza dek sürer!"]],112:[["1","Yah’ı övün! Ne mutlu Yahve'den korkan insana, O’nun buyruklarından büyük zevk alana."],["2","Onun soyu ülkede kudretli olacak. Doğruların kuşağı kutsanacak."],["3","Bolluk ve zenginlik onun evindedir. Onun doğruluğu sonsuza dek sürer."],["4","Doğrular için karanlıkta ışık doğar, lütufkâr, merhametli ve adildir onlar."],["5","Lütfedenin ve ödünç verenin durumu iyidir. Yargıda davasını sürdürür."],["6","Çünkü o asla sarsılmaz. Doğrular daima hatırlanır."],["7","Kötü haberden korkmaz. Yüreği kararlıdır, Yahve’ye güvenir."],["8","Yüreği sağlamdır. Sonunda düşmanlarını gördüğünde korkmaz."],["9","O dağıttı, yoksullara verdi. Doğruluğu sonsuza dek durur. Boynuzu saygınlıkla yükselir."],["10","Kötü kişi bunu görüp dertlenir. Dişlerini gıcırdatır, eriyip gider. Kötülerin dileği yok olur."]],113:[["1","Yah’ı övün! Ey Yahve’nin hizmetkârları övün, Yahve’nin adını övün."],["2","Şimdiden sonsuza dek, Yahve’nin adına övgüler olsun."],["3","Güneşin doğuşundan batışına dek, Yahve’nin adı övülmelidir."],["4","Yahve bütün ulusların üstünde yücedir, O’nun görkemi göklerin üzerindedir."],["5","Kim var Tanrımız Yahve gibi, yücelerde oturan,"],["6","Gökte ve yeryüzünde olanlara bakmak için eğilen?"],["7","Yoksulu topraktan kaldırır. Muhtacı kül yığınından yükseltir,"],["8","beylerle, halkının beyleriyle oturtsun diye."],["9","Kısır kadını sevinçli bir çocuklar annesi eder evinde oturtur. Yah’ı övün!"]],114:[["1","İsrael Mısır’dan, Yakov'un evi yabancı dilli halktan ayrıldığında,"],["2","Yahuda kutsal yeri, İsrael O’nun krallığı oldu."],["3","Deniz bunu gördü ve kaçtı. Yarden tersine döndü."],["4","Dağlar koçlar gibi, küçük tepeler kuzular gibi sıçradı."],["5","Ey deniz, ne oldu da kaçtın? Ey Yarden, neden ters döndün?"],["6","Ey dağlar, neden koçlar gibi, ey küçük tepeler, neden kuzular gibi sıçradınız?"],["7","Titreyin, ey yeryüzü, Efendi’nin önünde, Yakov'un Tanrısı'nın huzurunda,"],["8","O’dur kayayı su havuzuna, çakmaktaşını su pınarına çeviren."]],115:[["1","Bize değil, ey Yahve, bize değil. Ama sevgi dolu iyiliğin ve gerçeğin uğruna, kendi adına yücelik ver."],["2","Neden uluslar: “Şimdi, onların Tanrısı nerede?” desin."],["3","Ama Tanrımız göklerdedir. Ne isterse onu yapar."],["4","Onların putları gümüş ve altındır, insan ellerinin işi."],["5","Ağızları var ama konuşmazlar. Gözleri var ama görmezler."],["6","Kulakları var ama duymazlar. Burunları var ama koku almazlar."],["7","Elleri var ama hissetmezler. Ayakları var ama yürümezler, boğazlarıyla da konuşmazlar."],["8","Onları yapanlar ve onlara güvenen herkes, onlar gibi olacak."],["9","Ey İsrael, Yahve’ye güven! O’dur onların yardımcısı ve kalkanı."],["10","Ey Aron Evi, Yahve’ye güvenin! O’dur onların yardımcısı ve kalkanı."],["11","Ey sizler Yahve’den korkanlar, Yahve’ye güvenin! O’dur onların yardımcısı ve kalkanı."],["12","Yahve bizi hatırlar. O bizi kutsayacak. İsrael'in evini kutsayacak. Aron'un evini kutsayacak."],["13","Yahve'den korkanları, küçüğü de büyüğü de kutsayacak."],["14","Yahve sizi, sizi ve çocuklarınızı fazlasıyla artırsın."],["15","Göğü ve yeri yaratan Yahve sizi kutsasın."],["16","Gökler Yahve’nin gökleridir, ama yeryüzünü insanoğullarına verdi."],["17","Ölüler, sessizliğin içine inenler, Yah'ı övmezler."],["18","Ama biz şimdiden sonsuza dek, Yah’ı öveceğiz, Yah’ı övün!"]],116:[["1","Yahve'yi seviyorum, çünkü sesimi, feryadımı merhametiyle duyar."],["2","Kulağını bana döndürdüğü için, yaşadığım sürece O’nu çağıracağım."],["3","Ölüm ipleri çevremi sarmıştı, Şeol'ün acıları beni ele geçirmişti. Sıkıntı ve keder buldum."],["4","O zaman Yahve’nin adını çağırdım: “Ey Yahve, sana yalvarıyorum, canımı kurtar.”"],["5","Yahve lütufkâr ve doğrudur. Merhametlidir Tanrımız."],["6","Yahve saf insanı korur. Alçaltılmıştım ve O beni kurtardı."],["7","Ey canım, rahatına dön, çünkü Yahve sana cömertçe davrandı."],["8","Çünkü canımı ölümden, gözlerimi gözyaşından, ayaklarımı düşmekten kurtardın."],["9","Yaşayanlar diyarında Yahve’nin önünde yürüyeceğim."],["10","İman ettim, bu nedenle şöyle dedim: “Çok acı çektim.”"],["11","Telaşla şöyle dedim: “Bütün insanlar yalancıdır.”"],["12","Bana yönelik tüm iyiliklerine karşılık Yahve’ye ne vereyim?"],["13","Kurtuluş kâsesini alıp Yahve’nin adını çağıracağım."],["14","Bütün halkının önünde, Yahve’ye adaklarımı yerine getireceğim."],["15","Yahve’nin gözünde kutsallarının ölümü değerlidir."],["16","Ey Yahve, gerçekten ben senin hizmetkârınım. Hizmetkârın, hizmetçi kızın oğluyum. Zincirlerimden beni sen serbest bıraktın."],["17","Sana şükran kurbanını sunacağım, Yahve’nin adını çağıracağım."],["18","Yahve’ye adaklarımı yerine getireceğim, bütün halkının önünde,"],["19","Yahve'nin evinin avlularında, senin ortanda, ey Yeruşalem. Yah’ı övün!"]],117:[["1","Ey bütün uluslar, Yahve’yi övün! O’nu övün, ey bütün halklar!"],["2","Çünkü bize olan sevgi dolu iyiliği büyüktür. Yahve’nin sadakati sonsuza dek sürer. Yah’ı övün!"]],118:[["1","Yahve’ye şükredin, çünkü O iyidir, sevgi dolu iyiliği sonsuza dek sürer."],["2","Şimdi İsrael, “Sevgi dolu iyiliği sonsuza dek sürer” desin."],["3","Şimdi Aron'un evi, “Sevgi dolu iyiliği sonsuza dek sürer” desin."],["4","Şimdi Yahve’den korkanlar, “Sevgi dolu iyiliği sonsuza dek sürer” desin."],["5","Sıkıntı içinde Yah’a seslendim. Yah özgürlükle bana yanıt verdi."],["6","Yahve benden yanadır. Korkmam. İnsan bana ne yapabilir?"],["7","Bana yardım edenlerin arasında Yahve benden yanadır. Bu nedenle benden nefret edenlere zaferle bakacağım."],["8","Yahve’ye sığınmak, insana güvenmekten iyidir."],["9","Yahve’ye sığınmak, beylere güvenmekten iyidir."],["10","Bütün uluslar çevremi sardı, ama Yahve’nin adıyla kopardım onları."],["11","Çevremi sardılar, evet çevremi sardılar. Yahve’nin adıyla gerçekten kopardım onları."],["12","Arılar gibi çevremi sardılar. Diken ateşi gibi söndüler. Yahve’nin adıyla kopardım onları."],["13","Düşeyim diye beni şiddetle geri ittin, ama Yahve bana yardım etti."],["14","Yah benim gücüm ve ezgimdir. O benim kurtuluşum oldu."],["15","Sevinç ve kurtuluş sesi doğruların çadırlarındadır. “Yahve’nin sağ eli yiğitlik eder."],["16","Yahve’nin sağ eli yücedir! Yahve’nin sağ eli yiğitlik eder!”"],["17","Ölmeyeceğim, yaşayacağım, Yah'ın işlerini ilan edeceğim."],["18","Yah beni ciddi bir şekilde cezalandırdı, ama beni ölüme teslim etmedi."],["19","Bana doğruluğun kapılarını aç. Onların içine gireyim. Yah’a şükürler sunayım."],["20","Yahve’nin kapısı işte budur; doğrular oraya girer."],["21","Sana şükrederim, çünkü bana yanıt verdin, benim kurtuluşum oldun."],["22","Yapıcıların reddettiği taş köşe taşı oldu."],["23","Bu Yahve’nin işidir. Gözümüzde şaşılacak bir iş."],["24","Yahve’nin yarattığı gün bu gündür. İçinde sevinip coşalım!"],["25","Bizi şimdi kurtar, ey Yahve, sana yalvarırız! Sana yalvarırız, ey Yahve, şimdi bolluk gönder."],["26","Kutsansın Yahve’nin adıyla gelen! Yahve’nin evinden seni kutsarız."],["27","Yahve Tanrı'dır ve bize ışık verdi. Kurbanınızı sunağın boynuzlarına kadar iplerle bağlayın."],["28","Sen benim Tanrım’sın, sana şükrederim. Sen benim Tanrım’sın, seni yüceltirim."],["29","Yahve’ye şükredin, çünkü O iyidir, sevgi dolu iyiliği sonsuza dek sürer."]],119:JSON.parse(`[["1","א ALEF Ne mutlu yolları kusursuz olanlara, Yahve’nin yasasına göre yürüyenlere."],["2","Ne mutlu O'nun kurallarına uyanlara, O’nu tüm yüreğiyle arayanlara."],["3","Evet, onlar hiç haksızlık etmezler. O’nun yolunda yürürler."],["4","Onlara tamamen uyalım diye, ilkelerini buyurdun."],["5","Keşke yollarım sağlam olsaydı yasalarına itaat etmek için!"],["6","O zaman hayal kırıklığına uğramazdım, bütün buyruklarını göz önünde bulundurdukça."],["7","Sana dürüst bir yürekle şükredeceğim, doğru hükümlerini öğrendikçe."],["8","Kurallarına uyacağım. Beni bütünüyle terk etme. ב BEYT"],["9","Genç insan yolunu nasıl temiz tutabilir? Sözüne göre yaşamakla."],["10","Bütün yüreğimle seni aradım. Buyruklarından sapmama izin verme."],["11","Sözünü yüreğimde sakladım, sana karşı günah işlememek için."],["12","Övgüler olsun sana, ey Yahve. Bana kurallarını öğret."],["13","Dudaklarımla, ağzından çıkan bütün hükümlerini ilan ederim."],["14","Senin tanıklıkların yolunda, tüm zenginlikler benimmiş gibi sevindim."],["15","Senin ilkelerin üzerinde derin derin düşüneceğim, yollarını göz önünde bulunduracağım."],["16","Senin kurallarından zevk alırım. Sözünü unutmam. ג GİMEL"],["17","Hizmetkârına iyilik et de yaşayayım, sözüne uyayım."],["18","Gözlerimi aç da yasandaki şaşılası şeyleri göreyim."],["19","Ben yeryüzünde bir yabancıyım. Buyruklarını benden saklama."],["20","Canım her zaman senin hükümlerinin özlemiyle yanıp tutuşuyor."],["21","Senin buyruklarından sapan lanetli küstahları azarladın."],["22","Utancı ve hakareti benden uzaklaştır, çünkü senin hükümlerini tuttum."],["23","Beyler oturup bana iftira etse bile, hizmetkârın senin ilkelerinin üzerinde derin derin düşünecek."],["24","Gerçekten de senin ilkelerin benim zevkimdir, danışmanlarımdır. ד DALET"],["25","Canım toprağa serildi. Sözün uyarınca dirilt beni!"],["26","Yollarımı açıkladım, bana yanıt verdin. Bana kurallarını öğret."],["27","İlkelerindeki öğretiyi anlamamı sağla! O zaman senin şaşılası işlerinin üzerinde derin derin düşünürüm."],["28","Canım kederden bitkin, sözün uyarınca güçlendir beni."],["29","Beni yalan yolundan uzak tut. Yasanı bana lütufla bağışla!"],["30","Ben gerçeğin yolunu seçtim. Hükümlerini önüme koydum."],["31","Senin kurallarına sarıldım, ey Yahve. Hayal kırıklığına uğratma beni."],["32","Buyruklarının yolunda koşuyorum, çünkü yüreğimi özgür kıldın. ה HE"],["33","Ey Yahve, bana yasalarının yolunu öğret. Onları sonuna dek tutayım."],["34","Bana anlayış ver, yasana uyayım. Evet, ona tüm yüreğimle itaat edeyim."],["35","Buyruklarının yolunda bana yol göster, çünkü onlardan zevk alırım."],["36","Yüreğimi bencil kazanca değil, senin kurallarına yönelt."],["37","Gözlerimi değersiz şeylere bakmaktan çevir. Beni kendi yollarınla canlandır."],["38","Hizmetkârına verdiğin sözü yerine getir ki, senden korkulsun."],["39","Korktuğum hakareti benden uzaklaştır, çünkü senin hükümlerin iyidir."],["40","İşte, senin ilkelerini özlüyorum! Beni doğruluğunun içinde dirilt. ו VAV"],["41","Sözün uyarınca, ey Yahve, sevgi dolu iyiliğin, kurtarışın da bana gelsin."],["42","Böylece bana hakaret edene bir yanıtım olsun, çünkü senin sözüne güveniyorum."],["43","Gerçeğin sözünü ağzımdan düşürme, çünkü senin hükümlerine umut bağladım ben."],["44","Bu yüzden yasana sürekli, sonsuza dek uyacağım."],["45","Özgürce yürüyeceğim, çünkü senin ilkelerini aradım."],["46","Kralların önünde de senin kuralların hakkında konuşacak, hayal kırıklığına uğramayacağım."],["47","Buyruklarından zevk alırım, çünkü onları severim."],["48","Sevdiğim buyruklarına ellerimi kaldırırım. Senin kurallarının üzerinde derin derin düşüneyim. ז ZAYİN"],["49","Hizmetkârına verdiğin sözü hatırla, çünkü bana umut verdin."],["50","Sıkıntımda tesellim budur, çünkü senin sözün beni diriltti."],["51","Küstahlar benimle çok alay ettiler, ama senin yasandan sapmadım."],["52","Eski hükümlerini hatırlarım, ey Yahve, kendimi teselli ettim."],["53","Öfke beni ele geçirdi, yasanı terk eden kötüler yüzünden."],["54","Senin kuralların yaşadığım evde benim ezgilerim oldu."],["55","Gece adını hatırladım, ey Yahve, yasana uyarım."],["56","Benim yolum budur; senin ilkelerini tutmak. ח HET"],["57","Benim payım Yahve’dir. Sözlerine uyacağıma söz verdim."],["58","Bütün yüreğimle lütfunu aradım. Sözün uyarınca bana merhamet et."],["59","Yollarımı düşündüm, adımlarımı senin hükümlerine yönelttim."],["60","Senin buyruklarını tutmak için acele ettim, geç kalmadım."],["61","Kötülerin ipleri beni bağladı, ama yasanı unutmadım."],["62","Doğru hükümlerin için gece yarısı kalkıp sana şükrederim."],["63","Senden korkan, ilkelerine uyan herkesin, dostuyum ben."],["64","Yeryüzü sevgi dolu iyiliğinle dolu, ey Yahve. Bana kurallarını öğret. ט TET"],["65","Sözün uyarınca hizmetkârına iyilik ettin, ey Yahve."],["66","Bana sağduyu ve bilgi öğret, çünkü senin buyruklarına inanıyorum."],["67","Acı çekmeden önce yoldan sapmıştım, ama şimdi sözüne uyuyorum."],["68","Sen iyisin ve iyilik edersin. Bana kurallarını öğret."],["69","Küstahlar yalanla bana kara çaldılar. Ben bütün yüreğimle ilkelerini tutarım."],["70","Onların yürekleri yağ gibi katılaştı, bense yasandan zevk alırım."],["71","Acı çekmem benim için iyi oldu, ta ki, kurallarını öğreneyim."],["72","Senin ağzının yasası benim için binlerce altın ve gümüşten daha iyidir. י YOD"],["73","Senin ellerin beni yarattı ve biçim verdi. Bana anlayış ver ki, buyruklarını öğrenebileyim."],["74","Senden korkanlar beni görecek ve sevinecek, çünkü ben umudumu senin sözüne bağladım."],["75","Ey Yahve, yargılarının doğru olduğunu bilirim, sadakatinde bana acı verdin."],["76","Hizmetkârına olan sözün uyarınca, lütfen sevgi dolu iyiliğin bana teselli olsun."],["77","Senin şefkatli merhametlerin bana gelsin, yaşayayım, çünkü yasan benim zevkimdir."],["78","Küstahlar hayal kırıklığına uğrasın, çünkü haksız yere beni düşürdüler. Ben senin ilkelerinin üzerinde derin derin düşüneceğim."],["79","Senden korkanlar bana dönsünler. Yasalarını bilecekler."],["80","Yüreğim senin hükümlerine karşı suçsuz olsun ki, hayal kırıklığına uğramayayım. כ KAF"],["81","Canım senin kurtarışın için bitkin durumda. Senin sözüne umut bağladım."],["82","Gözlerim senin sözün için sönüyor. “Beni ne zaman teselli edeceksin?” diyorum."],["83","Çünkü dumanda kalmış şarap tulumu gibi oldum. Senin kurallarını unutmuyorum."],["84","Hizmetkârının günleri ne kadardır? Bana zulmedenleri ne zaman yargılayacaksın?"],["85","Yasana aykırı olarak küstahlar benim için çukur kazdılar."],["86","Buyruklarının tümü sadakattir. Bana haksız yere zulmediyorlar. Yardım et bana!"],["87","Neredeyse beni yeryüzünden sileceklerdi, ama ben senin ilkelerini bırakmadım."],["88","Sevgi dolu iyiliğin uyarınca koru canımı, böylece ağzının kurallarını tutayım. ל LAMED"],["89","Ey Yahve, sözün Göklerde sonsuza dek kalıcıdır."],["90","Sadakatin tüm kuşakları kapsar. Yeryüzünü kurdun ve o duruyor."],["91","Yasaların bugüne dek duruyor, çünkü her şey sana hizmet eder."],["92","Eğer yasan benim zevkim olmasaydı, acım yüzünden yok olurdum."],["93","İlkelerini asla unutmayacağım, çünkü onlarla beni dirilttin."],["94","Ben seninim. Kurtar beni, çünkü senin ilkelerini aradım."],["95","Kötüler beni yok etmek için beklediler. Ben senin kurallarını dikkate alıyorum."],["96","Her kusursuzluğun bir sınırını gördüm, ama senin buyrukların sınırsızdır. מ MEM"],["97","Yasanı ne kadar severim! Bütün gün düşüncem odur."],["98","Buyrukların beni düşmanlarımdan daha bilge kılar, çünkü buyrukların her zaman benimledir."],["99","Bütün öğretmenlerimden daha anlayışlıyım, çünkü tanıklıkların benim düşüncemdir."],["100","Yaşlılardan daha iyi anlarım, çünkü senin ilkelerine uydum."],["101","Ayaklarımı her kötü yoldan uzak tuttum, senin sözüne uymak için."],["102","Senin hükümlerinden ayrılmadım, çünkü bana sen öğrettin."],["103","Vaatlerin damağıma ne tatlıdır, ağzım için baldan tatlıdır!"],["104","İlkelerin sayesinde anlayış kazanıyorum, bunun için her yanlış yoldan nefret ediyorum. נ NUN"],["105","Sözün ayaklarım için bir fener, yolum için bir ışıktır."],["106","Senin doğru hükümlerini yerine getireyim diye ant içtim, andımı pekiştirdim."],["107","Çok acı çekiyorum. Sözün uyarınca beni dirilt, ey Yahve."],["108","Yalvarırım sana, ağzımın gönüllü sunularını kabul et. Ey Yahve, bana hükümlerini öğret."],["109","Canım sürekli elimdedir, yine de yasanı unutmam."],["110","Kötüler bana tuzak kurdu, yine de senin ilkelerinden sapmadım."],["111","Senin tanıklıklarını sonsuza dek miras olarak aldım, çünkü onlar yüreğimin sevincidir."],["112","Kurallarını uygulamaya yüreğimi koydum, ta sonuna, sonsuza dek. ם SAMEH"],["113","Çift fikirli insanlardan nefret ederim ama senin yasanı severim."],["114","Saklanacak yerim ve kalkanım sensin. Senin sözüne umut bağlarım."],["115","Uzak durun benden, ey siz kötülük edenler. Ta ki, Tanrım’ın buyruklarını tutabileyim."],["116","Sözün uyarınca bana destek ol ki, yaşayayım. Umudumdan utanmayayım."],["117","Beni tutup kaldır, güvende olurum, senin kurallarına daima saygı duyarım."],["118","Kurallarından sapan herkesi reddedersin, çünkü onların hilesi boşunadır."],["119","Yeryüzünün bütün kötülerini süprüntü gibi bir kenara attın. Bunun için tanıklıklarını severim."],["120","Senin korkundan bedenim titrer. Yargılarından korkarım. ע AYİN"],["121","Adil ve doğru olanı yaptım. Beni zalimlerin eline bırakma."],["122","Hizmetkârının mutluluğunu güven altına al. Küstahların beni ezmesine izin verme."],["123","Gözlerim senin kurtarışını ve doğru sözünü, aramayı bırakıyor."],["124","Hizmetkârına sevgi dolu iyiliğine göre davran. Bana kurallarını öğret."],["125","Ben senin hizmetkârınım. Bana anlayış ver de senin tanıklıklarını bileyim."],["126","Harekete geçme zamanıdır, ey Yahve, çünkü yasanı çiğniyorlar."],["127","Bunun için senin buyruklarını, altından, saf altından daha çok severim."],["128","Bu nedenle tüm ilkelerini doğru sayarım. Her yanlış yoldan nefret ediyorum. פ PE"],["129","Tanıklıkların harikadır, bunun için canım onlara uyuyor."],["130","Sözlerinin açılışı ışık verir, saf insana anlayış."],["131","Ağzımı genişçe açtım ve hasret kaldım. Çünkü buyruklarını özlüyorum."],["132","Bana yönel ve bana merhamet et, adını sevenlere her zaman yaptığın gibi."],["133","Adımlarımı sözünde pekiştir. Hiçbir kötülük bana hakim olmasın."],["134","Beni insanların baskısından kurtar da ilkelerine uyayım."],["135","Yüzünü hizmetkârının üzerinde parlat. Bana kurallarını öğret."],["136","Gözlerimden oluk oluk yaşlar akıyor, çünkü yasana uymuyorlar. צ TSADE"],["137","Sen doğrusun, ey Yahve. Yargıların dosdoğrudur."],["138","Kurallarını doğrulukla buyurdun. Onlar tamamen güvenilirdir."],["139","Gayretim beni tüketti, çünkü düşmanlarım senin sözlerini görmezden geliyor."],["140","Vaatlerin tümüyle sınandı, hizmetkârın onları sever."],["141","Ben küçük ve hor görülen biriyim. Senin ilkelerini unutmuyorum."],["142","Senin doğruluğun sonsuz bir doğruluktur. Yasan gerçektir."],["143","Sıkıntı ve ıstırap beni ele geçirdi. Buyrukların benim zevkimdir."],["144","Tanıklıkların daima doğrudur. Bana anlayış ver ki, yaşayayım. ק KOF"],["145","Tüm yüreğimle çağırdım. Yanıt ver bana, ey Yahve! Senin kurallarını tutacağım."],["146","Seni çağırdım. Kurtar beni! Senin kurallarına uyacağım."],["147","Şafaktan önce kalkıyorum ve yardım için yakarıyorum. Umudumu senin sözlerine bağladım."],["148","Gece nöbetleri boyunca gözlerim açık kalıyor, senin sözünü düşüneyim diye."],["149","Sevgi dolu iyiliğine göre sesimi duy. Hükümlerin uyarınca beni dirilt, ey Yahve."],["150","Kötülüğün ardına düşenler yaklaşıyor. Onlar senin yasandan uzaklar."],["151","Sen yakınsın, ey Yahve. Buyruklarının tümü gerçektir."],["152","Eskiden beri tanıklıklarından bilirim ki, sen onları sonsuza dek kurdun. ר REŞ"],["153","Çektiğim sıkıntıyı gör ve kurtar beni, çünkü senin yasanı unutmuyorum."],["154","Davamı savun ve kurtar beni! Sözün uyarınca beni dirilt."],["155","Kurtuluş kötülerden uzaktır, çünkü senin hükümlerini aramıyorlar."],["156","Senin sevecen merhametlerin ne büyüktür, ey Yahve. Beni hükümlerine göre dirilt."],["157","Bana zulmedenler ve düşmanlarım çoktur. Ben senin tanıklıklarından sapmadım."],["158","Hainlere nefretle bakarım, çünkü onlar senin sözünü tutmuyorlar."],["159","İlkelerini ne kadar sevdiğimi gör. Sevgi dolu iyiliğine göre beni dirilt, ey Yahve."],["160","Bütün sözlerin doğrudur. Her doğru hükmün sonsuza dek durur. ש SİN ve ŞİN"],["161","Beyler yok yere bana zulmettiler, ama yüreğim sözlerine hayran kalır."],["162","Büyük ganimet bulan biri gibi, ben senin sözünde sevinirim."],["163","Yalandan nefret ederim ve tiksinirim. Yasanı severim."],["164","Doğru hükümlerin için, günde yedi kez seni överim."],["165","Yasanı sevenler büyük esenliğe sahip olurlar. Hiçbir şey onları tökezletemez."],["166","Kurtarışına umut bağladım, ey Yahve. Buyruklarını yerine getirdim."],["167","Canım senin tanıklıklarını tuttu. Onları fazlasıyla severim."],["168","İlkelerine ve tanıklıklarına uydum, çünkü bütün yollarım senin önündedir. ת TAV"],["169","Feryadım önüne gelsin, ey Yahve. Sözün uyarınca bana anlayış ver."],["170","Yalvarışım senin önüne gelsin. Sözün uyarınca kurtar beni."],["171","Dudaklarım övsün, çünkü bana kurallarını öğretiyorsun."],["172","Dilim senin sözünü ezgiye çevirsin, çünkü bütün buyrukların doğruluktur."],["173","Elin bana yardım etmeye hazır olsun, çünkü ben senin ilkelerini seçtim."],["174","Senin kurtarışını özledim, ey Yahve. Yasan benim zevkimdir."],["175","Canımı yaşat ki, seni öveyim. Senin hükümlerin bana yardım etsin."],["176","Kaybolmuş bir koyun gibi yoldan saptım. Hizmetkârını ara, çünkü ben senin buyruklarını unutmam."]]`),120:[["1","Sıkıntı içinde Yahve’yi çağırdım. Bana yanıt verdi."],["2","Ey Yahve, canımı yalancı dudaklardan, aldatıcı dilden kurtar."],["3","Ey aldatıcı dil, sana ne verilecek, senin için daha çok ne yapılacak?"],["4","Güçlünün sivri oklarıyla, ardıç kömürü."],["5","Vay halime, Meşek'te yaşadığım, Kedar'ın çadırları arasında oturduğum için!"],["6","Canım uzun zamandır esenlikten nefret edenle mesken tutuyor."],["7","Ben esenlikten yanayım, ama ben konuşunca, onlar savaştan yana."]],121:[["1","Hagga ilahisi Gözlerimi tepelere kaldırıyorum. Yardımım nereden gelecek?"],["2","Yardımım yeri ve göğü yaratan Yahve'den gelecek."],["3","O ayaklarının sarsılmasına izin vermez. Seni koruyan uyuklamaz."],["4","İşte İsrael'i koruyan ne uyur, ne de uyuklar."],["5","Senin koruyucun Yahve’dir. Sağ yanında Yahve sana gölgedir."],["6","Gündüz güneş, gece ay sana zarar vermez."],["7","Yahve seni her kötülükten korur. O senin canını korur."],["8","Şimdiden sonsuza dek, Yahve senin gidişini gelişini koruyacak."]],122:[["1","David’in hagga ilahisi Bana, “Hadi Yahve'nin evine gidelim!” dediklerinde sevindim."],["2","Ayaklarımız senin kapılarında duruyor, ey Yeruşalem,"],["3","bitişik kurulmuş bir kenttir Yeruşalem,"],["4","oymaklar, Yah’ın oymakları, İsrael için olan kural uyarınca, Yahve’nin adına şükretmek için oraya çıkarlar."],["5","Çünkü yargı için kurulmuş tahtlar, David'in evinin tahtları vardır."],["6","Yeruşalem'in esenliği için dua edin. Seni sevenler bolluğa kavuşur."],["7","Surlarının içinde esenlik, saraylarında bolluk olsun."],["8","Kardeşlerim ve dostlarım için, şimdi “Sende esenlik olsun” derim."],["9","Tanrımız Yahve’nin evi için, senin iyiliğini ararım."]],123:[["1","Hagga ilahisi Ey göklerde oturan, gözlerimi sana kaldırıyorum"],["2","Hizmetkârların gözleri efendilerinin eline, hizmetçinin gözleri hanımının eline baktığı gibi, işte, bizim gözlerimiz de Tanrımız Yahve’ye öyle bakar, O bize merhamet edene kadar."],["3","Bize merhamet et, ey Yahve, bize merhamet et, çünkü fazlasıyla aşağılanmaya katlandık."],["4","Canımız rahat olanların alaylarına, küstahların küçümsemesine, fazlasıyla doydu."]],124:[["1","David’in hagga ilahisi Yahve bizim tarafımızda olmasaydı, desin şimdi İsrael:"],["2","Yahve bizim tarafımızda olmasaydı, insanlar bize karşı çıktığında,"],["3","öfkeleri bize karşı alevlendiğinde, o vakit bizi diri diri yutarlardı."],["4","O vakit sular bizi boğardı, sel canımızı aşardı,"],["5","O vakit gururlu sular canımızı aşardı."],["6","Övgüler olsun, bizi onların dişlerine yem etmeyen Yahve’ye."],["7","Canımız kuş avcısının tuzağından bir kuş gibi kurtuldu. Tuzak kırıldı, biz kurtulduk."],["8","Yeri göğü yaratan Yahve’nin adı yardımcımızdır."]],125:[["1","Hagga ilahisi Yahve'ye güvenenler Siyon Dağı gibidir, sarsılmaz, sonsuza dek kalır."],["2","Dağlar Yeruşalem'i nasıl sarmışsa, Yahve de halkını Şimdiden sonsuza dek öyle sarmıştır."],["3","Çünkü kötülüğün asası doğruların payında kalmayacak, öyle ki, doğrular ellerini kötülük yapmak için kullanmasınlar."],["4","İyilere, yüreği dürüst olanlara, iyilik et, ey Yahve."],["5","Ama kendi eğri yollarına sapanlara gelince, Yahve onları kötülüğün işçileriyle birlikte uzaklaştıracak. Esenlik İsrael’in üzerinde olsun."]],126:[["1","Hagga ilahisi Yahve Siyon'a dönenleri geri getirdiğinde, düş görenler gibiydik."],["2","O zaman ağzımız kahkahalarla, dilimiz ezgiyle doldu. O zaman uluslar arasında şöyle dediler: “Yahve onlar için büyük şeyler yaptı.”"],["3","Yahve bizim için büyük şeyler yaptı, bunun için sevinçliyiz."],["4","Eski bolluk günlerimize geri döndür, ey Yahve, Negev'deki dereler gibi."],["5","Gözyaşları içinde ekenler, sevinçle biçecekler."],["6","Ağlayarak ekilecek tohumu taşıyıp dışarı çıkan, elbette sevinçle demetleri taşıyarak geri gelecektir."]],127:[["1","Solomon’un hagga ilahisi Evi Yahve yapmazsa, yapıcılar boşuna çalışır. Kente Yahve göz kulak olmazsa, bekçi boşuna nöbet tutar."],["2","Boşunadır sizin için erken kalkıp geç yatmanız, ey zahmet ekmeği yiyenler. Çünkü O sevdiklerine uyku verir."],["3","İşte çocuklar Yahve’nin mirasıdır. Rahmin ürünü, onun ödülüdür."],["4","Yiğidin elindeki oklar gibi, gençlik çocukları da böyledir."],["5","Ok kılıfı onlarla dolu olan adama ne mutlu. Düşmanlarıyla kapıda konuşurken, hayal kırıklığına uğramazlar."]],128:[["1","Hagga ilahisi Ne mutlu Yahve’den korkan, O’nun yolunda yürüyen herkese."],["2","Çünkü ellerinin emeğini yiyeceksin. Mutlu olacaksın ve senin için iyi olacak."],["3","Eşin evinin içinde verimli bir asma gibi olacak, çocukların sofranın etrafındaki zeytin filizleri gibi."],["4","İşte, Yahve’den korkan adam böyle kutsanır."],["5","Yahve seni Siyon'dan kutsasın, hayatının bütün günlerinde Yeruşalem'in iyiliğini göresin."],["6","Evet, çocuklarının çocuklarını göresin. Esenlik İsrael’in üzerinde olsun."]],129:[["1","Hagga ilahisi Gençliğimden beri bana çok kez eziyet ettiler. Şimdi İsrael desin:"],["2","Gençliğimden beri bana çok kez eziyet ettiler, yine de bana karşı galip gelemediler."],["3","Çiftçiler sırtımda saban sürdüler. Saban izlerini uzun bıraktılar."],["4","Yahve doğrudur. Kötülerin bağlarını kopardı."],["5","Hayal kırıklığına uğrayıp geri dönsünler, Siyon'dan nefret edenlerin hepsi."],["6","Büyümeden önce kuruyan, damlardaki ot gibi olsunlar."],["7","Onunla orakçı elini, demetçi kucağını doldurmaz."],["8","Oradan geçenler de, “Yahve’nin kutsaması üzerinize olsun. Sizi Yahve'nin adıyla kutsuyoruz” demezler."]],130:[["1","Hagga ilahisi Derinliklerden seni çağırdım, ey Yahve."],["2","Ey Efendim, sesimi duy. Dikkatli olsun kulakların dileklerimin sesine."],["3","Ey Yah, sen eğer günahların kaydını tutarsan, kim ayakta durabilir, ey Efendim?"],["4","Ama sende bağışlanma var, bunun için senden korkulsun."],["5","Yahve'yi bekliyorum. Canım bekliyor. O’nun sözüne umut bağlıyorum."],["6","Bekçilerin sabahı özlemesinden daha çok, sabah bekçilerinden daha çok, canım Efendi’yi özlüyor."],["7","Ey İsrael, Yahve’ye umut bağla, çünkü Yahve’nin sevgi dolu iyiliği vardır. O’nda bol kurtuluş vardır."],["8","İsrael'i bütün günahlarından O kurtaracaktır."]],131:[["1","David’in hagga ilahisi Ey Yahve, yüreğim gururlu, gözlerim yükseklerde değil, ne büyük meselelerle, ne de benim için fazlasıyla harika olan şeylerle ilgilenmiyorum."],["2","Ana kucağında sütten kesilmiş bir çocuk gibi gerçekten canımı sakinleştirip susturdum, canım sütten kesilmiş bir çocuk gibi."],["3","Ey İsrael, Yahve’ye umut bağla, şimdiden sonsuza dek."]],132:[["1","Hagga ilahisi Ey Yahve, David’i ve bütün sıkıntılarını hatırla,"],["2","Yahve’ye nasıl ant içtiğini, Yakov'un Güçlüsü’ne olan adağını:"],["3","“Gerçekten evimin içine girmeyeceğim, yatağıma çıkmayacağım,"],["4","Gözlerime uyku, göz kapaklarıma uyuklama vermeyeceğim;"],["5","Yahve’ye bir yer, Yakov'un Güçlüsü'ne bir mesken bulana dek.”"],["6","İşte onun Efrata'da olduğunu duyduk. Onu Yaar kırında bulduk:"],["7","“O’nun meskenine gidelim. O’nun ayağının taburesinde tapınalım."],["8","Sen ve gücünün sandığı, ey Yahve, kendi dinlenme yerine çık,"],["9","kâhinleriniz doğrulukla giyinsin. Kutsallarınız sevinçle haykırsın!”"],["10","Hizmetkârın David'in hatırı için, meshetmiş olduğuna yüz çevirme."],["11","Yahve David'e gerçekle ant içti. Ondan geri dönmez: “Senin bedeninin ürününü tahtına oturtacağım."],["12","Eğer çocukların antlaşmamı, onlara öğreteceğim tanıklığımı tutarsa, onların çocukları da daima senin tahtında oturacaklar.”"],["13","Çünkü Yahve Siyon'u seçti. Kendine mesken olarak onu arzu etti."],["14","“Burası benim sonsuza dek dinlenme yerimdir. Burada yaşayacağım çünkü bunu ben arzuladım."],["15","Onun erzağını bol bol bereketleyeceğim. Yoksulunu ekmekle doyuracağım."],["16","Kâhinlerine de kurtuluş giydireceğim. Kutsalları sevinç içinde yüksek sesle haykıracaklar."],["17","Orada David'in boynuzunu yeşerteceğim. Meshedilmişim için bir kandil atadım."],["18","Düşmanlarını utançla örteceğim ama kendi üzerindeki tacı parlayacak.”"]],133:[["1","David’in hagga ilahisi Bakın, ne iyi, ne hoştur kardeşlerin beraberce birlik içinde yaşaması!"],["2","Baştaki değerli yağ gibi, sakaldan, Aron’un sakalından akan, kaftanlarının yakasına dek inen yağ gibi."],["3","Siyon tepelerine inen, Hermon’un çiyi gibidir, çünkü Yahve orada bereketi, sonsuz hayatı verdi."]],134:[["1","Hagga ilahisi Bakın! Ey sizler Yahve’nin bütün hizmetkârları, geceyi Yahve'nin evinde geçirenler, Yahve’yi övün!"],["2","Kutsal yerde ellerinizi kaldırın. Yahve’yi övün!"],["3","Göğü ve yeri yapan Yahve sizi Siyon'dan kutsasın."]],135:[["1","Yah’ı övün! Yahve’nin adını övün! Ey Yahve'nin hizmetkârları, O'nu övün,"],["2","ey sizler Yahve’nin evinde, Tanrımız’ın evinin avlularında duranlar."],["3","Yahve’yi övün, çünkü Yahve iyidir. Adını ezgilerle övün, çünkü bu hoştur."],["4","Çünkü Yahve kendisi için Yakov'u, kendi mülkü olarak İsrael’i seçti."],["5","Çünkü bilirim ki Yahve büyüktür, Efendimiz bütün ilâhlardan üstündür."],["6","Yahve ne dilediyse onu yaptı, gökte, yeryüzünde, denizlerde ve tüm derinliklerde."],["7","Yeryüzünün uçlarından bulutları yükseltir. Yağmurla birlikte şimşekler yapar. Rüzgârı hazinelerinden çıkarır."],["8","Hem insanı hem hayvanı, Mısır’ın ilk doğanlarını vurdu,"],["9","senin orta yerinde, ey Mısır, Firavun'nun ve onun bütün hizmetkârlarının üzerine, belirtiler ve harikalar gönderdi."],["10","Birçok ulusu vurdu, güçlü kralları öldürdü,"],["11","Amorlular'ın kralı Sihon’u, Başan Kralı Og’u, Kenan'ın bütün krallıklarını."],["12","Onların topraklarını mülk olarak, kendi halkı İsrael'e miras olarak verdi."],["13","Adın, ey Yahve, sonsuza dek durur, ünün, ey Yahve, tüm kuşaklar boyuncadır."],["14","Çünkü Yahve halkını yargılar, hizmetkârlarına merhamet gösterir."],["15","Ulusların putları gümüş ve altındır, insan ellerinin işi."],["16","Ağızları var ama konuşmazlar. Gözleri var ama görmezler."],["17","Kulakları var ama duymazlar. Ağızlarında hiç soluk bulunmaz."],["18","Onları yapanlar ve onlara güvenen herkes, onlar gibi olacak."],["19","Ey İsrael evi, Yahve’yi övün! Ey Aron evi, Yahve’yi övün!"],["20","Ey Levi evi, Yahve’yi övün! Ey Yahve'den korkanlar, Yahve’yi övün!"],["21","Yeruşalem’de oturan Yahve Siyon'dan övülsün. Yah’ı övün!"]],136:[["1","Yahve’ye şükredin, çünkü O iyidir, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["2","Tanrılar Tanrısı'na şükredin, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["3","Efendilerin Efendisi’ne şükredin, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["4","Büyük harikalar yapan tek varlığa, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["5","Gökleri anlayışla yapana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["6","Yeryüzünü suların üzerine yayana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["7","Büyük ışıklar yapana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["8","Gündüze hükmetsin diye güneşi, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["9","Geceye hükmetmek için ayı ve yıldızları, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["10","Mısır’ın ilk doğanını vurana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["11","İsrael'i aralarından çıkarana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["12","Güçlü eli ve uzanmış koluyla; çünkü sevgi dolu iyiliği sonsuza dek sürer."],["13","Kızıldeniz'i ikiye bölene; çünkü sevgi dolu iyiliği sonsuza dek sürer."],["14","İsrael'i ortasından geçirene, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["15","Firavun'la ordusunu Kızıldeniz'de bozguna uğratana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["16","Halkına çölde öncülük edene, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["17","Büyük kralları vurana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["18","Güçlü kralları öldürene, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["19","Amorluları'ın kralı Sihon’u, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["20","Başan Kralı Og’u, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["21","Topraklarını mülk olarak, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["22","Hizmetkârı İsrael'e miras olarak verene, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["23","Düşkünlüğümüzde bizi hatırlayana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["24","Bizi düşmanlarımızdan kurtarana, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["25","Her yaratığa yiyecek verene, çünkü sevgi dolu iyiliği sonsuza dek sürer."],["26","Göklerin Tanrısı’na şükredin, çünkü sevgi dolu iyiliği sonsuza dek sürer."]],137:[["1","Babil ırmakları kıyısında, orada oturduk. Siyon'u hatırladığımızda, evet ağladık."],["2","O diyardaki söğütlere, arplarımızı astık."],["3","Çünkü orada bizi tutsak edenler bizden ezgiler. Bize eziyet edenler sevinç ezgileri istediler: “Bize Siyon ezgilerinden birini söyleyin!” dediler."],["4","Yahve'nin ezgisini yabancı bir diyarda nasıl söyleriz?"],["5","Eğer seni unutursam, ey Yeruşalem, sağ elim becerisini unutsun."],["6","Eğer seni hatırlamazsam eğer Yeruşalem’i baş sevincimden üstün tutmazsam, dilim damağıma yapışsın,"],["7","Yeruşalem gününde, “Yıkın! Onu temeline kadar yıkın!” diyen Edom'un çocuklarına karşı, hatırla, ey Yahve."],["8","Ey sen, yıkıma mahkûmsun ey Babil kızı, bize yaptığının karşılığını, sana ödetecek olana ne mutlu."],["9","Senin yavrularını alıp kayaya çarpacak olana ne mutlu!"]],138:[["1","David’in mezmuru Bütün yüreğimle sana şükrederim. İlâhlar önünde seni ilahilerle överim."],["2","Kutsal tapınağına doğru eğilirim, sevgi dolu iyiliğin ve gerçeğin için adına şükrederim; çünkü Adını ve Sözü'nü her şeyin üstünde yücelttin."],["3","Çağırdığım gün bana yanıt verdin. Canımdaki güçle beni cesaretlendirdin."],["4","Yeryüzünün bütün kralları sana şükredecek, ey Yahve, çünkü ağzının sözlerini işittiler."],["5","Yahve’nin yollarını, evet, ezgilere dökecekler, çünkü Yahve'nin yüceliği büyüktür!"],["6","Çünkü Yahve yükseklerde ise de, alçakgönüllülerle ilgilenir, ama kibirliyi uzaktan tanır."],["7","Sıkıntının ortasında yürüsem bile, sen beni canlandırırsın. Düşmanlarımın gazabına karşı elini uzatırsın. Sağ elin beni kurtaracak."],["8","Yahve beni endişelendiren şeyi tamam eder. Sevgi dolu iyiliğin sonsuza dek sürer, ey Yahve. Kendi ellerinin işlerini bırakma."]],139:[["1","Müzik şefi için - David’in mezmuru Yahve, sen beni yokladın ve tanıdın."],["2","Oturuşumu ve kalkışımı bilirsin. Düşüncelerimi uzaktan sezersin."],["3","Yolumu ve yatışımı araştırırsın, bütün yollarımı bilirsin."],["4","Çünkü dilimde tek söz yokken, işte, ey Yahve, sen bunun hepsini bilirsin."],["5","Beni arkadan ve önden kuşattın. Elini üzerime koydun."],["6","Bu bilgi beni aşıyor, yüce, ona erişemem."],["7","Senin Ruhun’dan nereye gidebilirim? Ya da senin varlığından nereye kaçabilirim?"],["8","Göğe çıksam oradasın. Yatağımı Şeol'e sersem, işte oradasın!"],["9","Şafağın kanatlarını alsam, denizin en uzak uçlarına konsam,"],["10","orada bile elin bana yol gösterir, sağ elin beni tutar."],["11","Desem ki, “Karanlık beni mutlaka örter, çevremdeki ışık gece olsun.”"],["12","Karanlık bile senden gizlenemez, gece gündüz gibi parlar. Karanlık senin için ışık gibidir."],["13","Çünkü benim iç varlığımı sen biçimlendirdin. Annemin rahminde beni sen ördün."],["14","Sana şükürler sunarım, çünkü saygın ve harika yapılmışım. Senin işlerin harikadır. Canım bunu çok iyi bilir."],["15","Gizlide yapıldığımda, yeryüzünün derinliklerinde örüldüğümde, bedenim senden gizli değildi."],["16","Gözlerin bedenimi gördü. Benim için tayin edilen günlerin, henüz hiçbiri yokken, hepsi senin kitabında yazılmıştı."],["17","Düşüncelerin benim için ne değerlidir, ey Tanrı! Onların hesabı uçsuz bucaksızdır!"],["18","Onları saysam, sayıları kumdan çoktur. Uyandığımda yine seninleyim."],["19","Keşke sen, ey Tanrı, kötüleri öldürsen. Uzak durun benden, siz kana susamış insanlar!"],["20","Çünkü onlar sana karşı kötü konuşuyorlar. Düşmanların adını boş yere anıyorlar."],["21","Ey Yahve, senden nefret edenlerden nefret etmez miyim? Sana karşı ayaklananlara kederlenmez miyim?"],["22","Onlardan katıksızca nefret ederim. Onlar benim düşmanım oldular."],["23","Beni yokla, ey Tanrı, yüreğimi bil. Beni dene ve düşüncelerimi öğren."],["24","Bak, içimde kötü bir yol var mı, sonsuzluk yolunda bana öncülük et."]],140:[["1","Müzik şefi için - David’in mezmuru Ey Yahve, kurtar beni kötü insanlardan. Koru beni zalimden."],["2","Onlar, yüreklerinde kötülük tasarlar, sürekli savaş için toplanırlar."],["3","Dillerini yılan gibi keskinleştirdiler. Engerek zehri dudaklarının altındadır. Selah."],["4","Ey Yahve, koru beni kötülerin elinden. Ayaklarıma çelme takmaya kararlı zalim insanlardan koru beni."],["5","Küstahlar bana tuzak kurdular, yol kenarına ağ gerdiler. Benim için kapan yerleştirdiler. Selah."],["6","Yahve’ye, “Sen benim Tanrım’sın” dedim. Dileklerimin feryadını dinle, ey Yahve."],["7","Kurtuluşumun gücü, ey Efendi Yahve, savaş gününde başımı örttün."],["8","Ey Yahve, kötülerin dileklerini verme. Kötü planları başarıya ulaşmasın, yoksa gurura kapılırlar. Selah."],["9","Beni kuşatanların başına gelince, kendi dudaklarının kötülüğü onları kaplasın."],["10","Üzerlerine kızgın korlar yağsın. Ateşe atılsınlar, asla çıkamayacakları çamurlu çukurlara."],["11","Kötülük konuşan yeryüzünde tutunamasın. Kötülük, zalimi yıkmak için onu avlasın."],["12","Bilirim ki, Yahve dertlinin davasına bakar, muhtacı haklı çıkarır."],["13","Gerçekten doğrular senin adına şükredecekler. Doğrular senin huzurunda oturur."]],141:[["1","David’in mezmuru Ey Yahve, seni çağırdım. Bana tez gel! Seni çağırdığımda sesimi dinle."],["2","Duam buhur gibi, el kaldırışım akşam kurbanı gibi senin önünde dursun."],["3","Ey Yahve, ağzıma bekçi koy. Dudaklarımın kapısını koru."],["4","Yüreğimi kötülüğe meyletme, kötülük yapan adamlarla fesat işlemeyeyim. Onların lezzetlerinden yemeyeyim."],["5","Doğru bana vursun, iyiliktir bu, azarlasın beni, başa sürülen yağ gibidir, başım onu reddetmesin, ama benim duam hep kötü işlere karşıdır."],["6","Onların yargıçları kayanın yanına atıldı. Sözlerimi duyacaklar, çünkü yerinde söylenmiştir."],["7","“Nasıl biri toprağı sürüp yararsa, kemiklerimiz de Şeol'ün ağzında öyle dağılmış durumda.”"],["8","Çünkü gözlerim senin üzerinde, ey Efendimiz Yahve. Sana sığınıyorum. Canımı yoksul bırakma."],["9","Bana kurdukları tuzaktan, kötülük işçilerinin kapanlarından koru beni."],["10","Ben geçip giderken, kötüler hep birlikte kendi ağlarına düşsünler."]],142:[["1","David’in Maskili - Mağaradayken ettiği dua Sesimle Yahve'ye yakarıyorum. Sesimle Yahve'den merhamet diliyorum."],["2","Yakınmamı O’nun önünde döküyorum. O’na dertlerimi anlatıyorum."],["3","Ruhum içimde bunaldığında, sen yolumu bilirsin. Yürüdüğüm yolda, bana tuzak kurdular."],["4","Sağıma bak da gör, çünkü beni düşünen kimse yok. Sığınacak yer benden kaçtı. Kimse canımı umursamıyor."],["5","Sana feryat ettim, ey Yahve. “Sen benim sığınağımsın” dedim. “Yaşayanlar diyarından benim payımsın.”"],["6","Feryadımı dinle, çünkü çok çaresizim. Kurtar beni bana zulmedenlerden, çünkü onlar benden güçlüdür."],["7","Canımı zindandan çıkar da, adına şükredeyim. Doğrular çevremi saracak, çünkü bana iyilik edeceksin."]],143:[["1","David’in mezmuru Duamı duy, ey Yahve. Dileklerimi dinle. Sadakatin ve doğruluğunla beni rahatlat."],["2","Hizmetkârınla yargıya girme, çünkü senin önünde yaşayanlardan hiçbiri doğru değildir."],["3","Çünkü düşman canımın peşinde. Hayatımı yerle bir etti. Çoktan ölmüş olanlar gibi beni karanlık yerlerde yaşattı."],["4","Bunun için ruhum içimde bunalmış durumda. İçimde yüreğim kimsesiz."],["5","Eski günleri hatırlıyorum. Yaptıklarının tümü üzerinde derin derin düşünüyorum. Ellerinin işi üzerinde düşünceye dalıyorum."],["6","Ellerimi sana açıyorum. Kurak toprak gibi canım sana susamış. Selah."],["7","Bana tez yanıt ver, ey Yahve. Ruhum tükeniyor. Yüzünü benden gizleme, yoksa çukura inenler gibi olurum."],["8","Sabahleyin sevgi dolu iyiliğini duyur, çünkü sana güveniyorum. Yürümem gereken yolu bana bildir, çünkü canımı sana kaldırıyorum."],["9","Ey Yahve, kurtar beni düşmanlarımdan. Beni saklaman için sana kaçıyorum."],["10","İsteğini yapmayı bana öğret, çünkü sen benim Tanrım’sın. Senin Ruh’un iyidir. Doğruluk diyarında bana öncülük et."],["11","Ey Yahve, adın uğruna beni dirilt. Doğruluğunla canımı sıkıntıdan kurtar."],["12","Sevgi dolu iyiliğinle düşmanlarımı yok et, canıma eziyet eden herkesi yok et, çünkü ben senin hizmetkârınım."]],144:[["1","David’in mezmuru Ellerime savaşmayı, parmaklarıma mücadeleyi öğreten kayam Yahve’ye övgüler olsun."],["2","O’dur sevgi dolu iyiliğim, kalem, yüksek kulem, kurtarıcım, kalkanım ve kendisine sığındığım; halkımı bana boyun eğdiren."],["3","Ey Yahve, insan nedir ki, ona değer veresin? Ya da insanoğlu nedir ki, onu düşünesin?"],["4","İnsan soluğa benzer. Günleri, geçip giden gölge gibidir."],["5","Ey Yahve, gökleri yar ve aşağı in. Dağlara dokun da tütsünler."],["6","Şimşek çaktır, onları dağıt. Oklarını gönder de onları bozguna uğrat."],["7","Yukarıdan elini uzat, kurtar beni. beni büyük sulardan, yabancıların elinden özgür kıl."],["8","Ağızları hile söyler, onların sağ eli yalanın sağ elidir."],["9","Sana yeni bir ezgi söyleyeyim, ey Tanrı. On telli lirle sana ezgiler söyleyeyim."],["10","Krallara kurtuluş veren, hizmetkârı David'i ölümcül kılıçtan kurtaran sensin."],["11","Beni kurtar, yabancıların elinden özgür kıl, onların ağızları yalan söyler, onların sağ eli yalanın sağ elidir."],["12","O zaman oğullarımız iyi yetişmiş fidanlar gibi, kızlarımız sarayın oymalı sütunları gibi olacak."],["13","Ambarlarımız her türlü erzakla dolu. otlaklarımızda koyunlarımız binlerce, on binlerce yavru verecek."],["14","Öküzlerimiz bol yük çekecek. Saldırı ve sürgün, sokaklarımızda çığlık olmayacak."],["15","Ne mutlu bu durumda olan halka. Ne mutlu Tanrısı Yahve olan halka."]],145:[["1","David’in övgü mezmuru Seni yücelteceğim, ey Tanrım, ey Kral. Adını daima öveceğim."],["2","Her gün seni öveceğim. Adını daima yücelteceğim."],["3","Yahve büyüktür, övgüye çok layıktır! O’nun büyüklüğü keşfedilemez."],["4","Senin işlerini bir kuşak öbür kuşağa methedecek, kudretli işlerini bildirecek."],["5","Saygınlığının yüce heybeti, şaşılası işlerinin üzerinde derin derin düşüneceğim."],["6","İnsanlar müthiş işlerinin gücünden söz edecekler. Senin büyüklüğünü ilan edeceğim."],["7","Senin büyük iyiliğinin anısını dile getirecekler, doğruluğunu ezgiyle söyleyecekler."],["8","Yahve lütufkârdır, merhametlidir, yavaş öfkelenir, sevgi dolu iyiliği büyüktür."],["9","Yahve herkese iyidir. O’nun sevecen merhametleri bütün işlerinin üzerindedir."],["10","Bütün işlerin sana şükreder, ey Yahve. Kutsalların seni yüceltir."],["11","Krallığının görkeminden söz eder, gücün hakkında konuşur,"],["12","insanoğlu O’nun güçlü işlerini, krallığının yüce heybetini bilsin diye."],["13","Senin krallığın sonsuz bir krallıktır. Hakimiyetin tüm kuşaklar boyunca sürer. Yahve bütün sözlerinde sadıktır, tüm işlerinde sevgi doludur."],["14","Yahve düşen herkese destek olur, eğilenlerin hepsini doğrultur."],["15","Hepsinin gözleri seni bekler. Onlara yiyeceklerini mevsiminde verirsin."],["16","Elini açarsın, her canlıyı dilediğince doyurursun."],["17","Yahve bütün yollarında doğrudur, tüm işlerinde lütufkârdır."],["18","Yahve kendisini çağıranların hepsine, kendisini içtenlikle çağıran herkese yakındır."],["19","Kendisinden korkanların dileklerini yerine getirir. Onların feryadını işitir ve onları kurtarır."],["20","Yahve kendisini seven herkesi korur, ama kötülerin hepsini yok eder."],["21","Ağzım Yahve’yi över. Bütün canlılar O’nun kutsal adını, daima övsün."]],146:[["1","Yah’ı övün! Ey canım, Yahve’yi öv."],["2","Yaşadıkça Yahve’yi öveceğim. Var oldukça Tanrım’a ezgiler söyleyeceğim."],["3","Beylere, kendisinde yardım olmayan insanoğluna güvenmeyin."],["4","Ruhu ayrılır, kendisi toprağa döner. O gün fikirleri yok olur."],["5","Ne mutlu yardımcısı Yakov'un Tanrısı olana, umudu Tanrısı Yahve olana:"],["6","O’dur göğü ve yeri, denizi ve içindeki her şeyi yaratan, gerçeği sonsuza dek koruyan,"],["7","Ezilenlere adalet sağlayan, açlara yemek veren. Yahve tutsakları özgür kılar."],["8","Yahve körlerin gözlerini açar. Yahve eğilmiş olanları doğrultur. Yahve doğruları sever."],["9","Yahve yabancıları korur. Yetime ve dul kadına destek olur, kötülerin yolunuysa altüst eder."],["10","Yahve sonsuza dek, ey Siyon, senin Tanrın tüm kuşaklar boyunca hüküm sürecektir. Yah’ı övün!"]],147:[["1","Yah’ı övün, çünkü Tanrımız’a ilahiler söylemek iyidir; çünkü O’nu övmek hoş ve yerindedir."],["2","Yahve Yeruşalem'i bina ediyor. İsrael'in sürgünlerini bir araya topluyor."],["3","O, kırık yürekleri iyileştirir, yaralarını sarar."],["4","Yıldızların sayısını sayar. Hepsini adlarıyla çağırır."],["5","Efendimiz büyüktür, güçte muazzamdır. Anlayışı sonsuzdur."],["6","Yahve alçakgönüllülere destek olur. Kötüleri yere çalar."],["7","Yahve’ye şükranla ilahi söyleyin. Arpla, Tanrımız’a ezgiler söyleyin,"],["8","O’dur gökyüzünü bulutlarla kaplayan, yeryüzü için yağmuru hazırlayan, dağlarda ot bitiren."],["9","O, hayvanlara yiyecek sağlar, bağrışan kuzgun yavrularına."],["10","Atın gücünden zevk almaz. İnsanın bacaklarından hoşnut olmaz."],["11","Yahve kendisinden korkanlardan, sevgi dolu iyiliğine umut bağlayanlardan hoşnut olur."],["12","Ey Yeruşalem, Yahve’yi öv! Ey Siyon, Tanrın’ı yücelt!"],["13","Çünkü kapılarınızın sürgülerini güçlendirdi. İçindeki çocuklarını kutsadı."],["14","Sınırlarında esenlik sağlar. Seni buğdayın en iyisiyle doyurur."],["15","Buyruğunu yeryüzüne gönderir. Sözü çok hızlı gider."],["16","Yapağı gibi kar verir, kırağıyı kül gibi saçar."],["17","Doluyu çakıl taşları gibi yağdırır. Kim O'nun soğuğuna dayanabilir?"],["18","Sözünü gönderir ve onları eritir. Rüzgârını estirir, sular akar."],["19","Sözünü Yakov'a, kurallarını ve hükümlerini İsrael'e gösterir."],["20","Bunu hiçbir ulus için yapmadı. Onlar O’nun hükümlerini bilmezler. Yah’ı övün!"]],148:[["1","Yah’ı övün! Yahve'yi göklerden övün! O’nu yücelerde övün!"],["2","O'nu, övün, ey bütün melekleri! O’nu övün, ey bütün ordusu!"],["3","O'nu övün, ey güneş ve ay! O’nu övün, ey bütün parlayan yıldızlar!"],["4","O'nu övün, ey göklerin gökleri, göklerin üstündeki sular."],["5","Yahve’nin adını övsünler, çünkü O buyurdu ve yaratıldılar."],["6","Onları sonsuza dek yerleştirdi. Bozulmayacak bir hüküm koydu."],["7","Yeryüzünden Yahve’yi övün, ey büyük deniz yaratıkları ve tüm derinlikler,"],["8","şimşek ve dolu, kar ve bulutlar, O’nun sözünü yerine getiren kasırga,"],["9","dağlar ve bütün tepeler; meyve ağaçları ve bütün sedirler,"],["10","yabanıl ve evcil bütün hayvanlar, küçük yaratıklar ve uçan kuşlar,"],["11","yeryüzünün kralları ve bütün halklar, beyler ve bütün dünya hakimleri,"],["12","delikanlılar ve genç kızlar, yaşlılar ve çocuklar,"],["13","Yahve’nin adını övsünler, çünkü yalnızca O’nun adı yücedir. O’nun görkemi yeryüzünün ve göklerin üstündedir."],["14","Halkının boynuzunu yükseltti, tüm kutsallarını, kendisine yakın olan halkı, İsrael’in çocuklarını methettirdi. Yah’ı övün!"]],149:[["1","Yahve’yi övün! Yahve'ye yeni bir ezgi söyleyin, kutsallar topluluğunda övgüsünü sunun."],["2","İsrael kendisini yapanla sevinsin. Siyon çocukları Kralları’yla coşsun."],["3","Dans ederek O'nun adını övsünler! Tef ve arp çalarak O'nu ilahilerle yüceltsinler!"],["4","Çünkü Yahve halkından hoşlanır. Alçakgönüllüleri kurtuluşla taçlandırır."],["5","Kutsallar onur içinde sevinsinler. Yataklarında sevinçle ezgi söylesinler."],["6","Ağızlarında Tanrı'ya yüce övgüler, ellerinde iki ağızlı kılıçla,"],["7","uluslardan öç alsınlar, halkları cezalandırsınlar,"],["8","krallarını zincirlerle, soylularını demir prangalarla bağlasınlar,"],["9","ta ki, yazılı hükmü onlara karşı yerine getirsinler. O'nun bütün kutsalları bu onuru taşır. Yah’ı övün!"]],150:[["1","Yah’ı övün! Kutsal yerinde Tanrı’yı övün! Güçlü işleri için O’nu göklerde övün!"],["2","Güçlü işlerinden ötürü O’nu övün! Harika büyüklüğüne yaraşır biçimde O’nu övün!"],["3","Boru çalarak O’nu övün! Arp ve lirle O’nu övün!"],["4","Tefle, dansla O’nu övün! Yaylı çalgılar ve flütle O’nu övün!"],["5","Yüksek ses çıkaran zillerle O'nu övün! Çınlayan zillerle O’nu övün!"],["6","Nefesi olan her şey Yah'ı övsün! Yah’ı övün!"]]};export{a as default};
